@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --glass-bg: rgba(15, 23, 42, 0.45); /* Deep Slate/Black Tint */
    --glass-border: rgba(255, 255, 255, 0.12);
    --glass-highlight: rgba(255, 255, 255, 0.05);
    --neon-primary: #06b6d4; /* Cyan */
    --neon-secondary: #f59e0b; /* Amber */
    --neon-danger: #ef4444; /* Red */
  }

  html {
    font-size: 16px;
    height: 100%;
  }

  body {
    @apply bg-slate-950 text-slate-200 overflow-hidden select-none;
    font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    height: 100%;
    margin: 0;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  code, pre, .font-mono {
    font-family: 'JetBrains Mono', 'Consolas', 'Courier New', monospace;
  }
}

@layer components {
  /* ========================================= */
  /* 🧪 IOS 26 LIQUID GLASS DESIGN SYSTEM      */
  /* ========================================= */

  /* Surface: The container for all HUDs */
  .liquid-card {
    @apply bg-slate-900/60 backdrop-blur-2xl backdrop-saturate-150 
           border border-white/10 shadow-[0_8px_32px_0_rgba(0,0,0,0.5)] 
           ring-1 ring-white/5 rounded-3xl transition-all duration-300;
  }

  /* Surface Variant: Darker for internal sections */
  .liquid-card-dark {
    @apply bg-black/40 backdrop-blur-md border border-white/5 rounded-2xl;
  }

  /* Controls: Standard Action Button */
  .liquid-btn {
    @apply relative overflow-hidden flex items-center justify-center transition-all duration-200
           bg-white/5 border border-white/10 text-slate-300 backdrop-blur-md font-bold tracking-wider
           hover:bg-white/15 hover:border-white/25 hover:text-white hover:shadow-[0_0_15px_rgba(255,255,255,0.1)]
           active:scale-95 disabled:opacity-30 disabled:cursor-not-allowed disabled:active:scale-100;
  }

  /* Controls: Primary Action (Cyan Glow) */
  .liquid-btn-primary {
    @apply liquid-btn bg-cyan-500/10 border-cyan-500/30 text-cyan-400
           hover:bg-cyan-500/20 hover:border-cyan-400/50 hover:text-cyan-200 hover:shadow-[0_0_20px_rgba(6,182,212,0.4)];
  }

  /* Controls: Danger Action (Red Glow) */
  .liquid-btn-danger {
    @apply liquid-btn bg-red-500/10 border-red-500/30 text-red-400
           hover:bg-red-500/20 hover:border-red-400/50 hover:text-red-200 hover:shadow-[0_0_20px_rgba(239,68,68,0.4)];
  }

  /* Controls: Icon Button (Circular) */
  .liquid-icon-btn {
    @apply w-10 h-10 rounded-full liquid-btn text-lg shadow-lg;
  }

  /* Inputs: Standardized Form Field */
  /* Replaces old .tactical-input to maintain compatibility while upgrading style */
  .liquid-input, .tactical-input {
    @apply bg-black/20 border border-white/10 rounded-xl px-4 py-2 text-slate-200 font-mono text-sm
           focus:border-cyan-500/50 focus:bg-black/40 focus:ring-2 focus:ring-cyan-500/20 
           outline-none transition-all placeholder-slate-600 shadow-inner;
  }

  /* Badges & Tags */
  .liquid-tag {
    @apply px-2 py-0.5 rounded-full text-[10px] font-bold border backdrop-blur-sm uppercase tracking-wider;
  }
}

@layer utilities {
  .no-scrollbar::-webkit-scrollbar { display: none; }
  .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

  .text-glow-cyan { text-shadow: 0 0 10px rgba(6,182,212,0.6); }
  .text-glow-red { text-shadow: 0 0 10px rgba(239,68,68,0.6); }
  .text-glow-amber { text-shadow: 0 0 10px rgba(245,158,11,0.6); }
}

::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { @apply bg-white/10 rounded-full hover:bg-white/20 transition-colors; }

/* --- Animations --- */
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes slideUp { from { transform: translateY(30px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
@keyframes slideDown { from { transform: translateY(-20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
@keyframes pulseGlow { 
  0%, 100% { box-shadow: 0 0 5px rgba(6, 182, 212, 0.2); border-color: rgba(6, 182, 212, 0.3); }
  50% { box-shadow: 0 0 20px rgba(6, 182, 212, 0.5); border-color: rgba(6, 182, 212, 0.6); }
}
@keyframes bounceIn {
  0% { opacity: 0; transform: scale(0.3); }
  50% { opacity: 1; transform: scale(1.05); }
  70% { transform: scale(0.9); }
  100% { transform: scale(1); }
}
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

.animate-fade-in { animation: fadeIn 0.4s cubic-bezier(0.4, 0, 0.2, 1) forwards; }
.animate-slide-up { animation: slideUp 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.animate-slide-down { animation: slideDown 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
.animate-pulse-glow { animation: pulseGlow 3s infinite; }
.animate-bounce-in { animation: bounceIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both; }
.animate-float { animation: float 3s ease-in-out infinite; }

import React, { useRef } from 'react';
import { Team } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';

interface PlaybackHUDProps {
    hidden: boolean;
    isPlaying: boolean;
    winner: Team | null;
    timeScale: number;
    onTogglePlay: () => void;
    onRestart: () => void;
    onRandom: () => void;
    onSetTimeScale: (v: number) => void;
    onShowcase: () => void;
}

export const PlaybackHUD: React.FC<PlaybackHUDProps> = ({
    hidden, isPlaying, winner, timeScale, onTogglePlay, onRestart, onRandom, onSetTimeScale, onShowcase
}) => {
    const ref = useRef<HTMLDivElement>(null);

    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-center',
        margin: 40
    });

    return (
        <div 
            ref={ref}
            className={`z-40 transition-all duration-500 ${hidden ? 'opacity-0 translate-y-10 pointer-events-none' : 'opacity-100 translate-y-0'}`}
            style={style}
            {...dragHandlers}
        >
            <div className={`liquid-card !rounded-full p-2 pr-6 flex items-center gap-5 select-none cursor-grab ${isDragging ? 'cursor-grabbing scale-105 shadow-[0_0_30px_rgba(6,182,212,0.3)]' : ''} bg-black/60`}>

                {/* 1. Main Controls (Circle Buttons) */}
                <div className="flex items-center gap-2 pl-1">
                    <button 
                        onClick={(e) => { e.stopPropagation(); onTogglePlay(); }}
                        disabled={winner !== null}
                        className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl transition-all duration-300 shadow-lg group ${isPlaying ? 'bg-amber-500/10 text-amber-400 border border-amber-500/50 hover:bg-amber-500/20' : 'bg-white/5 text-emerald-400 border border-emerald-500/30 hover:bg-emerald-500/20 hover:border-emerald-400/60'}`}
                        title={isPlaying ? "暫停" : "開始"}
                        onPointerDown={e => e.stopPropagation()}
                    >
                        <span className="group-active:scale-90 transition-transform">{isPlaying ? '⏸' : '▶'}</span>
                    </button>

                    <div className="flex flex-col gap-1.5">
                        <button 
                            onClick={(e) => { e.stopPropagation(); onRestart(); }}
                            className="w-10 h-5 rounded-full bg-white/5 hover:bg-white/15 text-[10px] text-slate-400 hover:text-white flex items-center justify-center border border-white/10 transition-colors"
                            title="重置回合"
                            onPointerDown={e => e.stopPropagation()}
                        >
                            ↺
                        </button>
                        <button 
                            onClick={(e) => { e.stopPropagation(); onRandom(); }}
                            className="w-10 h-5 rounded-full bg-purple-500/10 hover:bg-purple-500/30 text-[10px] text-purple-300 hover:text-white flex items-center justify-center border border-purple-500/20 hover:border-purple-400/50 transition-colors"
                            title="隨機戰場"
                            onPointerDown={e => e.stopPropagation()}
                        >
                            🎲
                        </button>
                    </div>
                </div>

                {/* Divider */}
                <div className="w-px h-8 bg-white/10"></div>

                {/* 2. Time Control */}
                <div className="flex flex-col w-32 md:w-40 gap-1">
                    <div className="flex justify-between items-center px-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">SIM_SPEED</span>
                        <span className="text-[10px] font-mono font-bold text-cyan-400 text-glow-cyan">{timeScale.toFixed(1)}x</span>
                    </div>
                    <div className="relative h-2 bg-black/40 rounded-full border border-white/5 overflow-hidden group">
                        <div className="absolute top-0 left-0 h-full bg-cyan-500/50 rounded-full transition-all" style={{width: `${(timeScale/3)*100}%`}}></div>
                        <input 
                            type="range" min="0.1" max="3.0" step="0.1" 
                            value={timeScale} onChange={(e) => onSetTimeScale(parseFloat(e.target.value))}
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                            onPointerDown={e => e.stopPropagation()}
                        />
                    </div>
                </div>

                {/* Divider */}
                <div className="w-px h-8 bg-white/10"></div>

                {/* 3. System */}
                <button 
                    onClick={(e) => { e.stopPropagation(); onShowcase(); }}
                    className="text-slate-500 hover:text-white transition-all hover:scale-110 active:scale-95"
                    title="返回展示模式"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <span className="text-xl filter drop-shadow-md">📺</span>
                </button>

                {/* Drag Handle */}
                <div className="flex flex-col gap-1 opacity-20 px-1 cursor-grab active:cursor-grabbing">
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                    <div className="w-1 h-1 rounded-full bg-white"></div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

type ConfigModalType = 'UNIT' | 'OBSTACLE' | null;

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    const [isOpen, setIsOpen] = useState(false);
    const [configModal, setConfigModal] = useState<ConfigModalType>(null);
    const [pendingTool, setPendingTool] = useState<ToolType | null>(null);

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    const handleToolClick = (targetTool: ToolType) => {
        if (targetTool === ToolType.ADD_BLUE || targetTool === ToolType.ADD_RED) {
            setPendingTool(targetTool);
            setConfigModal('UNIT');
        } else if (targetTool === ToolType.OBSTACLE) {
            setPendingTool(targetTool);
            setConfigModal('OBSTACLE');
        } else {
            setTool(targetTool);
        }
    };

    const confirmConfig = () => {
        if (pendingTool) setTool(pendingTool);
        setConfigModal(null);
        setPendingTool(null);
    };

    return (
        <>
            {/* CONFIG MODALS (Liquid Glass) */}
            {configModal && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-md animate-fade-in" onClick={() => setConfigModal(null)}>
                    <div className="liquid-card p-6 w-80 animate-bounce-in flex flex-col gap-4" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center border-b border-white/10 pb-3">
                            <span className="text-xs font-bold text-cyan-400 text-glow-cyan uppercase tracking-widest">
                                {configModal === 'UNIT' ? 'DEPLOY PARAMETERS' : 'OBSTACLE TYPE'}
                            </span>
                            <button onClick={() => setConfigModal(null)} className="text-slate-500 hover:text-white">✕</button>
                        </div>

                        {configModal === 'UNIT' && (
                            <div className="space-y-4">
                                <div>
                                    <label className="text-[10px] font-bold text-slate-400 block mb-2 tracking-wider">INITIAL HP</label>
                                    <input type="number" value={hpInput} onChange={(e) => setHpInput(parseInt(e.target.value))} className="liquid-input w-full text-center text-lg" />
                                </div>
                                <div className="flex liquid-card-dark p-1">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>RANDOM</button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SELECT</button>
                                </div>
                                {spawnMode === 'DRAFT' && (
                                    <select value={draftRole} onChange={(e) => setDraftRole(e.target.value as Role)} className="liquid-input w-full h-10 cursor-pointer">
                                        {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                                    </select>
                                )}
                            </div>
                        )}

                        {configModal === 'OBSTACLE' && (
                            <select value={selectedObstacle} onChange={(e) => setSelectedObstacle(e.target.value)} className="liquid-input w-full h-12 text-center text-base cursor-pointer">
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}

                        <button onClick={confirmConfig} className="liquid-btn-primary w-full py-3 rounded-xl mt-2">
                            CONFIRM & EQUIP
                        </button>
                    </div>
                </div>
            )}

            {/* DRAGGABLE TOOLBAR */}
            <div 
                ref={ref}
                className="z-40"
                style={style}
                {...dragHandlers}
            >
                {/* CLOSED STATE */}
                {!isOpen && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsOpen(true); }}
                        onPointerDown={e => e.stopPropagation()} 
                        className="liquid-card !rounded-full px-8 py-3 text-slate-300 hover:text-white hover:border-cyan-500/50 transition-all font-bold tracking-widest flex items-center gap-4 group cursor-pointer animate-float"
                    >
                        <span className="text-xl filter drop-shadow-md">🛠️</span>
                        <span className="text-sm">EDITOR</span>

                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex gap-1 opacity-0 group-hover:opacity-50 transition-opacity" onPointerDown={dragHandlers.onPointerDown}>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                        </div>
                    </button>
                )}

                {/* OPEN STATE */}
                {isOpen && (
                    <div className={`liquid-card p-2 pr-10 flex flex-col md:flex-row items-center gap-4 relative cursor-grab ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                        {/* Drag Handle */}
                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-12 h-4 flex gap-1 justify-center items-center opacity-0 hover:opacity-50 transition-opacity">
                            <div className="w-8 h-1 bg-white/50 rounded-full"></div>
                        </div>

                        {/* Close Button */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); setIsOpen(false); }}
                            onPointerDown={e => e.stopPropagation()}
                            className="absolute -top-3 -right-3 w-7 h-7 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg hover:scale-110 active:scale-95 transition-all z-50 border border-white/20"
                        >
                            ✕
                        </button>

                        {/* 1. Map Settings */}
                        <div className="flex flex-col gap-2 p-3 liquid-card-dark" onPointerDown={e => e.stopPropagation()}>
                            <div className="text-[9px] font-bold text-slate-500 text-center uppercase tracking-wider">GRID SIZE</div>
                            <div className="flex gap-2 items-center justify-center">
                                <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, parseInt(e.target.value)))} className="w-10 h-7 bg-black/30 rounded-lg text-center text-xs text-slate-300 border border-white/10 outline-none focus:border-cyan-500/50" />
                                <span className="text-slate-600 text-xs">×</span>
                                <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, parseInt(e.target.value)))} className="w-10 h-7 bg-black/30 rounded-lg text-center text-xs text-slate-300 border border-white/10 outline-none focus:border-cyan-500/50" />
                            </div>
                            <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="h-7 bg-black/30 rounded-lg text-[10px] text-slate-400 border border-white/10 outline-none px-2 cursor-pointer hover:text-white transition-colors">
                                {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>

                        {/* Divider */}
                        <div className="hidden md:block w-px h-16 bg-white/10"></div>

                        {/* 2. Tools Group */}
                        <div className="flex gap-2 p-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setTool(ToolType.SELECT)} className={`liquid-icon-btn ${tool === ToolType.SELECT ? 'bg-white/20 text-white border-white/40 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'text-slate-400'}`} title="選取">↖</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.ADD_BLUE)} className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-300 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 hover:text-blue-300'}`} title="部署藍軍">🔵</button>
                            <button onClick={() => handleToolClick(ToolType.ADD_RED)} className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-300 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-300'}`} title="部署紅軍">🔴</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.OBSTACLE)} className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-300 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 hover:text-amber-300'}`} title="放置障礙">🧱</button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-900/50 text-red-500 border-red-800 shadow-inner' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

import React, { useState, useRef } from 'react';
import { Agent } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    onClose: () => void;
    onExpand?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
    '待機': 'IDLE',
    '移動': 'MOVING',
    '詠唱 BASIC': 'CASTING',
    '詠唱 ACTIVE': 'CASTING',
    '詠唱 ULT': 'CASTING ULT',
    '暈眩': 'STUNNED',
    '放逐': 'BANISHED',
    '沉默': 'SILENCED',
    '死亡': 'KIA'
};

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, onClose, onExpand }) => {
    const [isMinimized, setIsMinimized] = useState(false);

    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 40
    });

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/50' : 'border-red-500/50';
    const glowClass = isBlue ? 'shadow-[0_0_30px_rgba(59,130,246,0.15)]' : 'shadow-[0_0_30px_rgba(239,68,68,0.15)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    return (
        <div 
            ref={ref}
            className={`z-30 w-[calc(100%-2rem)] md:w-80 pointer-events-auto select-none transition-transform duration-200`}
            style={style}
            {...dragHandlers}
        >
            {isMinimized ? (
                // Minimized Pill
                <div 
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab ${isDragging ? 'cursor-grabbing' : ''} w-fit ml-auto border-l-4 ${borderColor}`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-6 h-6 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        ↗
                    </button>
                </div>
            ) : (
                // Full Card
                <div className={`liquid-card p-4 flex flex-col gap-3 ${glowClass} cursor-grab ${isDragging ? 'cursor-grabbing scale-[1.01]' : ''}`}>

                    {/* Header */}
                    <div className="flex justify-between items-start border-b border-white/5 pb-3">
                        <div className="flex items-center gap-3 pointer-events-none">
                            {/* Class Icon with Glass container */}
                            <div className={`w-12 h-12 flex items-center justify-center rounded-2xl liquid-card-dark border ${borderColor} ${themeColor} text-2xl shadow-inner`}>
                                {agent.role === Role.TANK && '🛡️'}
                                {agent.role === Role.WARRIOR && '⚔️'}
                                {agent.role === Role.RANGER && '🏹'}
                                {agent.role === Role.MAGE && '🔮'}
                                {agent.role === Role.SUPPORT && '⚕️'}
                            </div>
                            <div>
                                <div className={`font-mono font-black text-xl ${themeColor} leading-none tracking-tight`}>{agent.id}</div>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="liquid-tag bg-white/5 border-white/10 text-slate-300">{agent.role}</span>
                                    <span className={`liquid-tag ${isBlue ? 'bg-blue-500/10 border-blue-500/30 text-blue-300' : 'bg-red-500/10 border-red-500/30 text-red-300'}`}>LV.1</span>
                                </div>
                            </div>
                        </div>

                        {/* Controls */}
                        <div className="flex gap-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setIsMinimized(true)} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-white/10 text-slate-500 hover:text-white transition-all">_</button>
                            {onExpand && (
                                <button onClick={onExpand} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-cyan-500/20 text-slate-500 hover:text-cyan-400 transition-all">
                                    🔍
