                        </div>
                    </div>

                    {/* Vitals */}
                    <div className="space-y-2 pointer-events-none py-1">
                        {/* HP */}
                        <div className="relative">
                            <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1 tracking-wider">
                                <span>INTEGRITY</span>
                                <span className={agent.hp < agent.maxHp * 0.3 ? 'text-red-400 animate-pulse' : 'text-green-400'}>{Math.ceil(agent.hp)} / {agent.maxHp}</span>
                            </div>
                            <div className="h-2 bg-black/50 rounded-full overflow-hidden border border-white/5">
                                <div className="h-full bg-gradient-to-r from-green-600 to-green-400 transition-all duration-300 shadow-[0_0_10px_rgba(74,222,128,0.3)]" style={{width: `${Math.max(0, hpPct)}%`}}></div>
                            </div>
