                        {/* MP */}
                        <div className="relative">
                            <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1 tracking-wider">
                                <span>ENERGY</span>
                                <span className="text-blue-400">{Math.floor(agent.mp)}%</span>
                            </div>
                            <div className="h-1.5 bg-black/50 rounded-full overflow-hidden border border-white/5">
                                <div className="h-full bg-gradient-to-r from-blue-600 to-blue-400 transition-all duration-300 shadow-[0_0_10px_rgba(96,165,250,0.3)]" style={{width: `${mpPct}%`}}></div>
                            </div>
                        </div>
                    </div>

                    {/* AI Monitor */}
                    <div className="flex justify-between items-center liquid-card-dark p-3 pointer-events-none border-l-2 border-cyan-500/50">
                        <div className="flex flex-col">
                            <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">NEURAL STATE</span>
                            <span className={`text-sm font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300 text-glow-cyan'}`}>
                                {STATUS_LABELS[agent.btStatus] || agent.btStatus}
                            </span>
                        </div>
                        {/* Active Effects */}
                        <div className="flex gap-1">
                            {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300">STUN</span>}
                            {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300">SILENCE</span>}
                            {agent.banished && <span className="liquid-tag bg-purple-500/20 border-purple-500/50 text-purple-300">BANISH</span>}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

