import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './showcase/types';
import { DEFAULT_MATRIX_CONFIG } from './showcase/defaults';
import { useMatrixRain } from './showcase/useMatrixRain';
import { ShowcaseSettings } from './showcase/ShowcaseSettings';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [config, setConfig] = useState<MatrixConfig>(DEFAULT_MATRIX_CONFIG);
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [showSettings, setShowSettings] = useState(false);

    // Track window size for canvas init
    const [viewport, setViewport] = useState({ w: window.innerWidth, h: window.innerHeight });

    useEffect(() => {
        const handleResize = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Hook: Handles the Matrix Rain rendering on the transparent canvas
    useMatrixRain(canvasRef, config, viewport.w, viewport.h);

    // Helper: Determine UI Layout classes
    const getLayoutClasses = () => {
        switch (layout) {
            case 'CENTER': 
                return 'inset-0 flex-col justify-center items-center text-center p-4 md:p-8';
            case 'BOTTOM_CENTER': 
                return 'bottom-12 left-0 right-0 mx-auto w-full max-w-[calc(100vw-4rem)] md:max-w-5xl flex-col md:flex-row justify-between items-center';
            case 'BOTTOM_LEFT': 
                return 'bottom-10 left-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-start';
            case 'BOTTOM_RIGHT': 
                return 'bottom-10 right-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-end text-right';
            default: 
                return 'inset-0 justify-center items-center';
        }
    };

    const isCompact = layout !== 'CENTER';
    const isWideBar = layout === 'BOTTOM_CENTER';

    const getRgbaBg = (hex: string, alpha: number) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        const r = parseInt(result[1], 16);
        const g = parseInt(result[2], 16);
        const b = parseInt(result[3], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    };

    return (
        <div className="absolute inset-0 z-50 overflow-hidden pointer-events-none">

            {/* LAYER 1: Background Color Overlay */}
            <div 
                className="absolute inset-0 transition-colors duration-300"
                style={{ backgroundColor: getRgbaBg(config.bgColor, config.enabled ? config.bgOpacity : 0) }}
            ></div>

            {/* LAYER 2: Matrix Rain Canvas */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 block w-full h-full pointer-events-none mix-blend-screen"
            />

            {/* LAYER 3: CRT Scanline / Vignette Effects */}
            {config.enabled && config.bgOpacity > 0.1 && (
                <>
                    <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_90%)] pointer-events-none"></div>
                </>
            )}

            {/* LAYER 4: UI Content */}
            <div className={`absolute z-[55] flex animate-slide-up pointer-events-none transition-all duration-500 ${getLayoutClasses()}`}>

                {/* Main Liquid Card */}
                <div className={`liquid-card p-8 md:p-10 pointer-events-auto flex max-w-full ${isWideBar ? 'w-full flex-col md:flex-row items-center gap-8' : 'flex-col items-center gap-8 w-full'}`}>

                    {/* Content Text */}
                    <div className={`relative flex flex-col max-w-full ${isWideBar ? 'items-center md:items-start text-center md:text-left flex-1' : (layout.includes('RIGHT') ? 'items-end' : 'items-center')}`}>

                        {/* Header Badge */}
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-cyan-950/30 border border-cyan-500/30 text-[10px] text-cyan-400 font-mono tracking-widest mb-4 shadow-[0_0_10px_rgba(6,182,212,0.2)]">
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse box-shadow-[0_0_5px_cyan]"></span>
                            <span>SYSTEM_READY // V4.0.3</span>
                        </div>

                        <h1 className={`font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-100 to-cyan-500 font-mono tracking-tighter drop-shadow-[0_0_30px_rgba(6,182,212,0.5)] ${isCompact ? 'text-5xl' : 'text-7xl md:text-8xl'}`}>
                            TACTICAL.OS
                        </h1>

                        <div className="text-slate-400 font-mono text-xs tracking-[0.4em] uppercase mt-3 opacity-80 mix-blend-plus-lighter">
                            Neural Battle Simulation
                        </div>
                    </div>

                    {/* Start Button */}
                    <div className={`relative shrink-0 ${isCompact && !isWideBar ? 'w-full' : ''}`}>
                        <button 
                            onClick={onEnter}
                            className={`group liquid-btn-primary rounded-2xl overflow-hidden transition-all duration-300 ${isWideBar ? 'px-16 py-6 w-full md:w-auto text-xl' : 'w-full px-12 py-5 text-lg'} shadow-[0_0_30px_rgba(6,182,212,0.2)]`}
                        >
                            <span className="relative flex items-center justify-center gap-4 z-10">
                                <span>INITIALIZE</span>
                                <svg className="w-5 h-5 fill-current group-hover:translate-x-1 transition-transform" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                            </span>
                        </button>
                    </div>
                </div>
            </div>

            {/* LAYER 5: Controls */}
            <div className="absolute top-6 left-6 z-[60] pointer-events-auto">
                <button 
                    onClick={() => setShowSettings(!showSettings)}
                    className={`liquid-icon-btn hover:text-cyan-400 hover:border-cyan-500/50 hover:bg-white/10 ${showSettings ? 'text-cyan-400 border-cyan-500/50 bg-white/10' : 'text-slate-400'}`}
                    title="特效設定"
                >
                    <svg className={`w-5 h-5 ${showSettings ? 'animate-spin-slow' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    </svg>
                </button>
            </div>

            <ShowcaseSettings 
                show={showSettings} 
                onClose={() => setShowSettings(false)}
                config={config} 
                setConfig={setConfig} 
                timeScale={timeScale}
                setTimeScale={setTimeScale}
                layout={layout}
                setLayout={setLayout}
            />
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

type ConfigModalType = 'UNIT' | 'OBSTACLE' | null;

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    const [isOpen, setIsOpen] = useState(false);
    const [configModal, setConfigModal] = useState<ConfigModalType>(null);
    const [pendingTool, setPendingTool] = useState<ToolType | null>(null);

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    const handleToolClick = (targetTool: ToolType) => {
        if (targetTool === ToolType.ADD_BLUE || targetTool === ToolType.ADD_RED) {
            setPendingTool(targetTool);
            setConfigModal('UNIT');
        } else if (targetTool === ToolType.OBSTACLE) {
            setPendingTool(targetTool);
            setConfigModal('OBSTACLE');
        } else {
            setTool(targetTool);
        }
    };

    const confirmConfig = () => {
        if (pendingTool) setTool(pendingTool);
        setConfigModal(null);
        setPendingTool(null);
    };

    return (
        <>
            {/* CONFIG MODALS (Liquid Glass) */}
            {configModal && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-md animate-fade-in" onClick={() => setConfigModal(null)}>
                    <div className="liquid-card p-6 w-80 animate-bounce-in flex flex-col gap-4" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center border-b border-white/10 pb-3">
                            <span className="text-xs font-bold text-cyan-400 text-glow-cyan uppercase tracking-widest">
                                {configModal === 'UNIT' ? 'DEPLOY PARAMETERS' : 'OBSTACLE TYPE'}
                            </span>
                            <button onClick={() => setConfigModal(null)} className="text-slate-500 hover:text-white">✕</button>
                        </div>

                        {configModal === 'UNIT' && (
                            <div className="space-y-4">
                                <div>
                                    <label className="text-[10px] font-bold text-slate-400 block mb-2 tracking-wider">INITIAL HP</label>
                                    <input type="number" value={hpInput} onChange={(e) => setHpInput(parseInt(e.target.value))} className="liquid-input w-full text-center text-lg" />
                                </div>
                                <div className="flex liquid-card-dark p-1">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>RANDOM</button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SELECT</button>
                                </div>
                                {spawnMode === 'DRAFT' && (
                                    <select value={draftRole} onChange={(e) => setDraftRole(e.target.value as Role)} className="liquid-input w-full h-10 cursor-pointer">
                                        {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                                    </select>
                                )}
                            </div>
                        )}

                        {configModal === 'OBSTACLE' && (
                            <select value={selectedObstacle} onChange={(e) => setSelectedObstacle(e.target.value)} className="liquid-input w-full h-12 text-center text-base cursor-pointer">
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}

                        <button onClick={confirmConfig} className="liquid-btn-primary w-full py-3 rounded-xl mt-2">
                            CONFIRM & EQUIP
                        </button>
                    </div>
                </div>
            )}

            {/* DRAGGABLE TOOLBAR */}
            <div 
                ref={ref}
                className="z-40"
                style={style}
                {...dragHandlers}
            >
                {/* CLOSED STATE */}
                {!isOpen && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsOpen(true); }}
                        onPointerDown={e => e.stopPropagation()} 
                        className="liquid-card !rounded-full px-8 py-3 text-slate-300 hover:text-white hover:border-cyan-500/50 transition-all font-bold tracking-widest flex items-center gap-4 group cursor-pointer animate-float"
                    >
                        <span className="text-xl filter drop-shadow-md">🛠️</span>
                        <span className="text-sm">EDITOR</span>

                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex gap-1 opacity-0 group-hover:opacity-50 transition-opacity" onPointerDown={dragHandlers.onPointerDown}>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                        </div>
                    </button>
                )}

                {/* OPEN STATE - Increased Opacity Here (bg-slate-950/90) */}
                {isOpen && (
                    <div className={`liquid-card bg-slate-950/90 backdrop-blur-3xl p-2 pr-10 flex flex-col md:flex-row items-center gap-4 relative cursor-grab ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                        {/* Drag Handle */}
                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-12 h-4 flex gap-1 justify-center items-center opacity-0 hover:opacity-50 transition-opacity">
                            <div className="w-8 h-1 bg-white/50 rounded-full"></div>
                        </div>

                        {/* Close Button */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); setIsOpen(false); }}
                            onPointerDown={e => e.stopPropagation()}
                            className="absolute -top-3 -right-3 w-7 h-7 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg hover:scale-110 active:scale-95 transition-all z-50 border border-white/20"
                        >
                            ✕
                        </button>

                        {/* 1. Map Settings */}
                        <div className="flex flex-col gap-2 p-3 liquid-card-dark" onPointerDown={e => e.stopPropagation()}>
                            <div className="text-[9px] font-bold text-slate-500 text-center uppercase tracking-wider">GRID SIZE</div>
                            <div className="flex gap-2 items-center justify-center">
                                <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, parseInt(e.target.value)))} className="w-10 h-7 bg-black/30 rounded-lg text-center text-xs text-slate-300 border border-white/10 outline-none focus:border-cyan-500/50" />
                                <span className="text-slate-600 text-xs">×</span>
                                <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, parseInt(e.target.value)))} className="w-10 h-7 bg-black/30 rounded-lg text-center text-xs text-slate-300 border border-white/10 outline-none focus:border-cyan-500/50" />
                            </div>
                            <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="h-7 bg-black/30 rounded-lg text-[10px] text-slate-400 border border-white/10 outline-none px-2 cursor-pointer hover:text-white transition-colors">
                                {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>

                        {/* Divider */}
                        <div className="hidden md:block w-px h-16 bg-white/10"></div>

                        {/* 2. Tools Group */}
                        <div className="flex gap-2 p-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setTool(ToolType.SELECT)} className={`liquid-icon-btn ${tool === ToolType.SELECT ? 'bg-white/20 text-white border-white/40 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'text-slate-400'}`} title="選取">↖</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.ADD_BLUE)} className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-300 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 hover:text-blue-300'}`} title="部署藍軍">🔵</button>
                            <button onClick={() => handleToolClick(ToolType.ADD_RED)} className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-300 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-300'}`} title="部署紅軍">🔴</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.OBSTACLE)} className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-300 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 hover:text-amber-300'}`} title="放置障礙">🧱</button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-900/50 text-red-500 border-red-800 shadow-inner' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

import React, { useEffect, useState, memo } from 'react';
import { LogEntry, Team } from '../../../types';

interface LogTabProps {
    engine: any;
}

const LogItem = memo(({ log }: { log: LogEntry }) => (
    <div className="group flex items-start gap-3 py-2 px-2 border-b border-white/5 hover:bg-white/5 transition-colors text-xs font-mono">
        <span className="text-slate-600 shrink-0 w-12 text-right group-hover:text-slate-400 transition-colors">
            {log.time}s
        </span>
        <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-0.5">
                <span className={`font-bold tracking-tight ${log.team === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_5px_rgba(96,165,250,0.3)]' : (log.team === Team.RED ? 'text-red-400 drop-shadow-[0_0_5px_rgba(248,113,113,0.3)]' : 'text-slate-400')}`}>
                    {log.agentId || 'SYSTEM'}
                </span>
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-white/5 text-slate-300 border border-white/10 uppercase">
                    {log.action}
                </span>
                {log.target && log.target !== '自身' && (
                    <>
                        <span className="text-slate-600">➜</span>
                        <span className="text-amber-200 opacity-90">{log.target}</span>
                    </>
                )}
            </div>
            <p className="text-slate-400 group-hover:text-slate-300 transition-colors leading-relaxed opacity-80">
                {log.detail}
            </p>
        </div>
    </div>
));

export const LogTab: React.FC<LogTabProps> = ({ engine }) => {
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);

    useEffect(() => {
        const interval = setInterval(() => {
            if (engine.logs.length !== localLogs.length) setLocalLogs(engine.logs.slice(-100));
        }, 200);
        return () => clearInterval(interval);
    }, [engine, localLogs.length]);

    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Control Header */}
            <div className="flex justify-between items-center p-4 border-b border-white/10 shrink-0">
                <div className="flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse box-shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                    <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest text-glow-cyan">REAL-TIME DATA</span>
                </div>
                <button 
                    onClick={downloadLogs} 
                    className="liquid-btn px-3 py-1.5 !text-[10px] rounded-lg border-white/20 text-slate-300 hover:text-white"
                >
                    EXPORT JSON
                </button>
            </div>

            {/* Log Stream */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 pb-24 scroll-smooth">
                {localLogs.slice().reverse().map(log => (
                    <LogItem key={log.id} log={log} />
                ))}
                {localLogs.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-40 opacity-30 gap-3">
                        <span className="text-4xl">📡</span>
                        <span className="text-xs font-mono tracking-widest">AWAITING SIGNAL...</span>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Role, Skill, Team } from '../../../types';
import { SKILL_FIELD_GROUPS, TAG_MAP, ROLE_MAP } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';

interface SkillDbTabProps {
    db: Skill[];
    onUpdate: () => void;
}

export const SkillDbTab: React.FC<SkillDbTabProps> = ({ db, onUpdate }) => {
    const [dbTypeTab, setDbTypeTab] = useState<'ALL' | 'BASIC' | 'ACTIVE' | 'ULT'>('ALL');
    const [dbRoleFilter, setDbRoleFilter] = useState<Role | 'ALL'>('ALL');
    const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);

    const filteredSkills = db.filter(s => {
        if (dbTypeTab !== 'ALL' && s.tag !== dbTypeTab) return false;
        if (dbRoleFilter !== 'ALL' && s.role !== dbRoleFilter) return false;
        return true;
    });

    const updateSkill = (field: keyof Skill, value: any) => {
        const skill = db.find(s => s.id === selectedSkillId);
        if (skill) { 
            if (field === 'team') {
                if (value === 'ANY') (skill as any)[field] = undefined;
                else if (value === 'BLUE') (skill as any)[field] = Team.BLUE;
                else if (value === 'RED') (skill as any)[field] = Team.RED;
            } else {
                (skill as any)[field] = value; 
            }
            onUpdate(); 
        }
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Header / Controls */}
            <div className="p-4 border-b border-white/10 shrink-0 space-y-4">
                <div className="flex justify-between items-end">
                    <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">NEURAL ARCHIVE</div>
                    <div className="text-[10px] font-mono text-cyan-400 text-glow-cyan">
                        INDEX: {filteredSkills.length} / {db.length}
                    </div>
                </div>

                <div className="flex flex-col gap-2">
                    {/* Type Tabs */}
                    <div className="flex liquid-card-dark p-1 gap-1">
                        {['ALL', 'BASIC', 'ACTIVE', 'ULT'].map(t => (
                            <button 
                                key={t}
                                onClick={() => setDbTypeTab(t as any)} 
                                className={`flex-1 py-2 text-[10px] rounded-xl font-bold transition-all uppercase tracking-wider ${dbTypeTab === t ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 shadow-[0_0_10px_rgba(6,182,212,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
                            >
                                {t === 'ALL' ? 'ALL TYPES' : TAG_MAP[t].label}
                            </button>
                        ))}
                    </div>

                    {/* Role Select */}
                    <div className="relative group">
                        <select 
                            className="liquid-input w-full h-10 text-xs appearance-none cursor-pointer uppercase font-bold tracking-wider group-hover:border-white/30 transition-colors"
                            value={dbRoleFilter}
                            onChange={(e) => setDbRoleFilter(e.target.value as any)}
                        >
                            <option value="ALL">FILTER CLASS: ALL</option>
                            {Object.values(Role).map(r => <option key={r} value={r}>FILTER: {ROLE_MAP[r].label}</option>)}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-xs">▼</div>
                    </div>
                </div>
            </div>

            {/* List Area */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 pb-24 space-y-3">
                {filteredSkills.map(skill => {
                    const isSelected = selectedSkillId === skill.id;
                    return (
                        <div 
                            key={skill.id} 
                            className={`liquid-card !rounded-2xl transition-all duration-300 overflow-hidden ${isSelected ? 'border-cyan-500/50 shadow-[0_0_20px_rgba(6,182,212,0.15)] bg-slate-900/80' : 'hover:border-white/20 hover:scale-[1.01]'}`}
                        >
                            <div 
                                className="flex items-center gap-4 p-3 cursor-pointer select-none"
                                onClick={() => setSelectedSkillId(isSelected ? null : skill.id)}
                            >
                                <SkillIcon skill={skill} className="w-12 h-12 !rounded-xl !border-white/10" />
                                <div className="flex-1 min-w-0">
                                    <div className={`font-bold text-sm ${isSelected ? 'text-cyan-300' : 'text-slate-200'}`}>{skill.name}</div>
                                    <div className="text-[10px] text-slate-500 flex gap-2 items-center mt-1 uppercase font-bold tracking-wider">
                                        <span>{ROLE_MAP[skill.role].label}</span>
                                        <span className="w-1 h-1 bg-slate-600 rounded-full"></span>
                                        <span className={`${skill.tag === 'ULT' ? 'text-purple-400' : (skill.tag === 'ACTIVE' ? 'text-blue-400' : 'text-slate-400')}`}>{TAG_MAP[skill.tag].label}</span>
                                    </div>
                                </div>
                                <div className={`text-xl transition-transform duration-300 ${isSelected ? 'rotate-90 text-cyan-400' : 'text-slate-600'}`}>
                                    ›
                                </div>
                            </div>

                            {/* Edit Form */}
                            {isSelected && (
                                <div className="p-4 bg-black/40 border-t border-white/5 space-y-5 animate-slide-down">
                                    {SKILL_FIELD_GROUPS.map((group) => (
                                        <div key={group.name} className="space-y-3">
                                            <div className="flex items-center gap-2 pb-1 border-b border-white/5">
                                                <div className="w-1 h-1 bg-cyan-500 rounded-full"></div>
                                                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{group.name}</span>
                                            </div>

                                            <div className="grid grid-cols-2 gap-3">
                                                {group.fields.map((field) => {
                                                    const val = (skill as any)[field.key];
                                                    let displayVal = val;

                                                    if (field.key === 'team') {
                                                        if (val === undefined) displayVal = 'ANY';
                                                        else if (val === Team.BLUE) displayVal = 'BLUE';
                                                        else if (val === Team.RED) displayVal = 'RED';
                                                    } else if (val === undefined || val === null) {
                                                        displayVal = '';
                                                    }

                                                    const isWide = field.type === 'textarea';

                                                    return (
                                                        <div key={field.key} className={isWide ? "col-span-2 space-y-1" : "space-y-1"}>
                                                            <label className="text-[9px] font-bold text-slate-400 block ml-1" title={field.label}>{field.label}</label>

                                                            {field.type === 'textarea' ? (
                                                                <textarea 
                                                                    className="liquid-input w-full p-3 h-24 resize-none !rounded-xl leading-relaxed"
                                                                    value={displayVal}
                                                                    onChange={e => updateSkill(field.key, e.target.value)}
                                                                />
                                                            ) : field.type === 'select' ? (
                                                                <div className="relative">
                                                                    <select 
                                                                        className="liquid-input w-full h-9 text-xs appearance-none cursor-pointer"
                                                                        value={displayVal}
                                                                        onChange={e => {
                                                                            const v = e.target.value;
                                                                            if (v === 'NONE' || v === 'ANY' || v === '') updateSkill(field.key, undefined);
                                                                            else updateSkill(field.key, v); 
                                                                        }}
                                                                    >
                                                                        {field.options ? 
                                                                            field.options.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>) :
                                                                            field.simpleOptions?.map(opt => <option key={opt} value={opt}>{opt}</option>)
                                                                        }
                                                                    </select>
                                                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[10px]">▼</div>
                                                                </div>
                                                            ) : field.type === 'color' ? (
                                                                <div className="flex gap-2 items-center">
                                                                    <div className="relative flex-1">
                                                                        <input 
                                                                            type="text" 
                                                                            className="liquid-input w-full h-9 text-xs font-mono" 
                                                                            value={displayVal} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                    <div className="relative w-9 h-9 rounded-xl overflow-hidden border border-white/20 shadow-inner">
                                                                        <input 
                                                                            type="color" 
                                                                            className="absolute -top-1/2 -left-1/2 w-[200%] h-[200%] cursor-pointer p-0 border-0" 
                                                                            value={displayVal.startsWith('#') ? displayVal : '#ffffff'} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                </div>
                                                            ) : (
                                                                <input 
                                                                    type={field.type} 
                                                                    className="liquid-input w-full h-9 text-xs font-mono"
                                                                    value={displayVal}
                                                                    step={field.step || 1}
                                                                    onChange={e => updateSkill(field.key, field.type === 'number' ? parseFloat(e.target.value) : e.target.value)}
                                                                />
                                                            )}
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

type ConfigModalType = 'UNIT' | 'OBSTACLE' | null;

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    const [isOpen, setIsOpen] = useState(false);
    const [configModal, setConfigModal] = useState<ConfigModalType>(null);
    const [pendingTool, setPendingTool] = useState<ToolType | null>(null);

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    const handleToolClick = (targetTool: ToolType) => {
        if (targetTool === ToolType.ADD_BLUE || targetTool === ToolType.ADD_RED) {
            setPendingTool(targetTool);
            setConfigModal('UNIT');
        } else if (targetTool === ToolType.OBSTACLE) {
            setPendingTool(targetTool);
            setConfigModal('OBSTACLE');
        } else {
            setTool(targetTool);
        }
    };

    const confirmConfig = () => {
        if (pendingTool) setTool(pendingTool);
        setConfigModal(null);
        setPendingTool(null);
    };

    return (
        <>
            {/* CONFIG MODALS (Liquid Glass) */}
            {configModal && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-md animate-fade-in" onClick={() => setConfigModal(null)}>
                    <div className="liquid-card p-6 w-80 animate-bounce-in flex flex-col gap-4 border border-white/10" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center border-b border-white/10 pb-3">
                            <span className="text-xs font-bold text-cyan-400 text-glow-cyan uppercase tracking-widest">
                                {configModal === 'UNIT' ? 'DEPLOY PARAMETERS' : 'OBSTACLE TYPE'}
                            </span>
                            <button onClick={() => setConfigModal(null)} className="liquid-icon-btn w-8 h-8 text-sm hover:text-red-400">✕</button>
                        </div>

                        {configModal === 'UNIT' && (
                            <div className="space-y-4">
                                <div>
                                    <label className="text-[10px] font-bold text-slate-400 block mb-2 tracking-wider">INITIAL HP</label>
                                    <input type="number" value={hpInput} onChange={(e) => setHpInput(parseInt(e.target.value))} className="liquid-input w-full text-center text-lg" />
                                </div>
                                <div className="flex liquid-card-dark p-1">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>RANDOM</button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SELECT</button>
                                </div>
                                {spawnMode === 'DRAFT' && (
                                    <select value={draftRole} onChange={(e) => setDraftRole(e.target.value as Role)} className="liquid-input w-full h-10 cursor-pointer">
                                        {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                                    </select>
                                )}
                            </div>
                        )}

                        {configModal === 'OBSTACLE' && (
                            <select value={selectedObstacle} onChange={(e) => setSelectedObstacle(e.target.value)} className="liquid-input w-full h-12 text-center text-base cursor-pointer">
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}

                        <button onClick={confirmConfig} className="liquid-btn-primary w-full py-3 rounded-xl mt-2">
                            CONFIRM & EQUIP
                        </button>
                    </div>
                </div>
            )}

            {/* DRAGGABLE TOOLBAR */}
            <div 
                ref={ref}
                className="z-40"
                style={style}
                {...dragHandlers}
            >
                {/* CLOSED STATE */}
                {!isOpen && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsOpen(true); }}
                        onPointerDown={e => e.stopPropagation()} 
                        className="liquid-card !rounded-full px-8 py-3 text-slate-300 hover:text-white hover:border-cyan-500/50 transition-all font-bold tracking-widest flex items-center gap-4 group cursor-pointer animate-float"
                    >
                        <span className="text-xl filter drop-shadow-md">🛠️</span>
                        <span className="text-sm">EDITOR</span>

                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex gap-1 opacity-0 group-hover:opacity-50 transition-opacity" onPointerDown={dragHandlers.onPointerDown}>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                        </div>
                    </button>
                )}

                {/* OPEN STATE - Pure Liquid Glass */}
                {isOpen && (
                    <div className={`liquid-card !bg-slate-900/80 !backdrop-blur-3xl !rounded-3xl p-3 pr-12 flex flex-col md:flex-row items-center gap-4 relative cursor-grab border border-white/10 shadow-[0_10px_40px_rgba(0,0,0,0.5)] ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                        {/* Drag Handle */}
                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-12 h-4 flex gap-1 justify-center items-center opacity-0 hover:opacity-50 transition-opacity">
                            <div className="w-8 h-1 bg-white/50 rounded-full"></div>
                        </div>

                        {/* Close Button (Liquid Style) */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); setIsOpen(false); }}
                            onPointerDown={e => e.stopPropagation()}
                            className="absolute -top-3 -right-3 w-8 h-8 rounded-full bg-slate-800 border border-white/10 text-slate-400 hover:bg-red-500/20 hover:text-red-400 hover:border-red-500/50 flex items-center justify-center shadow-lg transition-all z-50 active:scale-95"
                        >
                            ✕
                        </button>

                        {/* 1. Map Settings */}
                        <div className="flex flex-col gap-2 p-3 liquid-card-dark" onPointerDown={e => e.stopPropagation()}>
                            <div className="text-[9px] font-bold text-slate-500 text-center uppercase tracking-wider">GRID SIZE</div>
                            <div className="flex gap-2 items-center justify-center">
                                <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, parseInt(e.target.value)))} className="liquid-input w-12 h-8 !px-1 text-center" />
                                <span className="text-slate-600 text-xs font-bold">×</span>
                                <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, parseInt(e.target.value)))} className="liquid-input w-12 h-8 !px-1 text-center" />
                            </div>
                            <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="liquid-input h-8 text-[10px] !py-0 cursor-pointer">
                                {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>

                        {/* Divider */}
                        <div className="hidden md:block w-px h-20 bg-gradient-to-b from-transparent via-white/10 to-transparent"></div>

                        {/* 2. Tools Group */}
                        <div className="flex gap-3 p-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setTool(ToolType.SELECT)} className={`liquid-icon-btn ${tool === ToolType.SELECT ? 'bg-white/20 text-white border-white/40 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'text-slate-400'}`} title="選取">↖</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.ADD_BLUE)} className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-300 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 hover:text-blue-300'}`} title="部署藍軍">🔵</button>
                            <button onClick={() => handleToolClick(ToolType.ADD_RED)} className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-300 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-300'}`} title="部署紅軍">🔴</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.OBSTACLE)} className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-300 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 hover:text-amber-300'}`} title="放置障礙">🧱</button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-500/20 text-red-400 border-red-500/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

import React, { useState, useRef } from 'react';
import { Agent } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    onClose: () => void;
    onExpand?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
    '待機': 'IDLE',
    '移動': 'MOVING',
    '詠唱 BASIC': 'CASTING',
    '詠唱 ACTIVE': 'CASTING',
    '詠唱 ULT': 'CASTING ULT',
    '暈眩': 'STUNNED',
    '放逐': 'BANISHED',
    '沉默': 'SILENCED',
    '死亡': 'KIA'
};

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, onClose, onExpand }) => {
    const [isMinimized, setIsMinimized] = useState(false);

    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 40
    });

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/50' : 'border-red-500/50';
    const glowClass = isBlue ? 'shadow-[0_0_30px_rgba(59,130,246,0.15)]' : 'shadow-[0_0_30px_rgba(239,68,68,0.15)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    return (
        <div 
            ref={ref}
            className={`z-30 w-[calc(100%-2rem)] md:w-80 pointer-events-auto select-none transition-transform duration-200`}
            style={style}
            {...dragHandlers}
        >
            {isMinimized ? (
                // Minimized Pill
                <div 
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab ${isDragging ? 'cursor-grabbing' : ''} w-fit ml-auto border-l-4 ${borderColor}`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-6 h-6 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        ↗
                    </button>
                </div>
            ) : (
                // Full Card
                <div className={`liquid-card p-4 flex flex-col gap-3 ${glowClass} cursor-grab ${isDragging ? 'cursor-grabbing scale-[1.01]' : ''}`}>

                    {/* Header */}
                    <div className="flex justify-between items-start border-b border-white/5 pb-3">
                        <div className="flex items-center gap-3 pointer-events-none">
                            {/* Class Icon Container (Liquid Style) */}
                            <div className={`w-12 h-12 flex items-center justify-center rounded-2xl liquid-card-dark border ${borderColor} ${themeColor} text-2xl shadow-inner relative overflow-hidden`}>
                                <div className={`absolute inset-0 opacity-20 bg-gradient-to-br from-white to-transparent`}></div>
                                {agent.role === Role.TANK && '🛡️'}
                                {agent.role === Role.WARRIOR && '⚔️'}
                                {agent.role === Role.RANGER && '🏹'}
                                {agent.role === Role.MAGE && '🔮'}
                                {agent.role === Role.SUPPORT && '⚕️'}
                            </div>
                            <div>
                                <div className={`font-mono font-black text-xl ${themeColor} leading-none tracking-tight`}>{agent.id}</div>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="liquid-tag bg-white/5 border-white/10 text-slate-300 shadow-sm">{agent.role}</span>
                                    <span className={`liquid-tag ${isBlue ? 'bg-blue-500/10 border-blue-500/30 text-blue-300' : 'bg-red-500/10 border-red-500/30 text-red-300'} shadow-sm`}>LV.1</span>
                                </div>
                            </div>
                        </div>

                        {/* Controls */}
                        <div className="flex gap-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setIsMinimized(true)} className="liquid-icon-btn w-7 h-7 text-xs bg-transparent border-transparent hover:bg-white/10">_</button>
                            {onExpand && (
                                <button onClick={onExpand} className="liquid-icon-btn w-7 h-7 text-xs bg-transparent border-transparent hover:bg-cyan-500/20 hover:text-cyan-400">
                                    🔍
                                </button>
                            )}
                            <button onClick={onClose} className="liquid-icon-btn w-7 h-7 text-xs bg-transparent border-transparent hover:bg-red-500/20 hover:text-red-400">✕</button>
                        </div>
                    </div>

                    {/* Vitals (Liquid Tube Style) */}
                    <div className="space-y-3 pointer-events-none py-1">
                        {/* HP */}
                        <div className="relative group">
                            <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1 tracking-wider">
                                <span>INTEGRITY</span>
                                <span className={`font-mono ${agent.hp < agent.maxHp * 0.3 ? 'text-red-400 animate-pulse' : 'text-green-400'}`}>{Math.ceil(agent.hp)} / {agent.maxHp}</span>
                            </div>
                            <div className="h-3 bg-black/60 rounded-full overflow-hidden border border-white/10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)]">
                                <div 
                                    className="h-full bg-gradient-to-r from-green-800 via-green-500 to-green-400 transition-all duration-300 relative" 
                                    style={{width: `${Math.max(0, hpPct)}%`}}
                                >
                                    <div className="absolute top-0 left-0 w-full h-[1px] bg-white/30"></div>
                                    <div className="absolute bottom-0 left-0 w-full h-[1px] bg-black/20"></div>
                                </div>
                            </div>
                        </div>
                        {/* MP */}
                        <div className="relative group">
                            <div className="flex justify-between text-[9px] font-bold text-slate-400 mb-1 tracking-wider">
                                <span>ENERGY</span>
                                <span className="font-mono text-blue-400">{Math.floor(agent.mp)}%</span>
                            </div>
                            <div className="h-2 bg-black/60 rounded-full overflow-hidden border border-white/10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)]">
                                <div 
                                    className="h-full bg-gradient-to-r from-blue-800 via-blue-500 to-blue-400 transition-all duration-300 relative" 
                                    style={{width: `${mpPct}%`}}
                                >
                                    <div className="absolute top-0 left-0 w-full h-[1px] bg-white/30"></div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* AI Monitor */}
                    <div className="flex justify-between items-center liquid-card-dark p-3 pointer-events-none border-l-2 border-cyan-500/50 shadow-inner">
                        <div className="flex flex-col">
                            <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">NEURAL STATE</span>
                            <span className={`text-sm font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300 text-glow-cyan'}`}>
                                {STATUS_LABELS[agent.btStatus] || agent.btStatus}
                            </span>
                        </div>
                        {/* Active Effects */}
                        <div className="flex gap-1">
                            {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300 shadow-[0_0_10px_rgba(245,158,11,0.3)]">STUN</span>}
                            {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300">SILENCE</span>}
                            {agent.banished && <span className="liquid-tag bg-purple-500/20 border-purple-500/50 text-purple-300 shadow-[0_0_10px_rgba(168,85,247,0.3)]">BANISH</span>}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { Skill } from '../../types';
import { UnitStatusTab } from '../inspector/tabs/UnitStatusTab';
import { BehaviorTreeTab } from '../inspector/tabs/BehaviorTreeTab';

interface UnitDetailViewProps {
    agent: Agent;
    db: Skill[];
    engine: GameEngine;
}

export const UnitDetailView: React.FC<UnitDetailViewProps> = ({ agent, db, engine }) => {
    const [subTab, setSubTab] = useState<'STATUS' | 'AI'>('STATUS');
    const [version, setVersion] = useState(0); 

    // Refresh Loop for visual updates (Health, AI Nodes)
    useEffect(() => {
        const interval = setInterval(() => setVersion(n => n + 1), 100); // 10 FPS is enough for UI
        return () => clearInterval(interval);
    }, []);

    const handleUpdate = () => {
        setVersion(n => n + 1);
    };

    return (
        <div className="flex flex-col h-full w-full select-none">
            {/* UNIT HEADER (Liquid Glass) */}
            <div className="p-5 border-b border-white/10 shrink-0 z-20 flex items-center justify-between gap-4 bg-slate-900/40 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 flex items-center justify-center rounded-2xl liquid-card-dark border text-2xl shadow-inner ${agent.team === 0 ? 'border-blue-500/50 text-blue-400' : 'border-red-500/50 text-red-400'}`}>
                        {agent.role === 'TANK' && '🛡️'}
                        {agent.role === 'WARRIOR' && '⚔️'}
                        {agent.role === 'RANGER' && '🏹'}
                        {agent.role === 'MAGE' && '🔮'}
                        {agent.role === 'SUPPORT' && '⚕️'}
                    </div>
                    <div>
                        <div className="font-mono font-black text-2xl leading-none text-white tracking-tight">{agent.id}</div>
                        <div className="flex items-center gap-2 mt-1">
                            <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase bg-white/5 px-2 py-0.5 rounded-full border border-white/5">Level 1</span>
                            <span className={`text-[10px] font-bold tracking-widest uppercase ${agent.team === 0 ? 'text-blue-400' : 'text-red-400'}`}>{agent.role}</span>
                        </div>
                    </div>
                </div>

                {/* SUB TABS (Liquid Capsules) */}
                <div className="flex liquid-card-dark p-1 gap-1">
                    <button onClick={() => setSubTab('STATUS')} className={`px-6 py-2 text-xs rounded-xl font-bold transition-all uppercase tracking-wider ${subTab === 'STATUS' ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 shadow-[0_0_15px_rgba(6,182,212,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>STATUS</button>
                    <button onClick={() => setSubTab('AI')} className={`px-6 py-2 text-xs rounded-xl font-bold transition-all uppercase tracking-wider ${subTab === 'AI' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30 shadow-[0_0_15px_rgba(245,158,11,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>BEHAVIOR</button>
                </div>
            </div>

            {/* CONTENT AREA */}
            <div className="flex-1 overflow-hidden relative">
                {subTab === 'STATUS' ? (
                    <UnitStatusTab 
                        agent={agent} 
                        db={db} 
                        onHoverSkill={() => {}} 
                        onUpdate={handleUpdate}
                    />
                ) : (
                    <BehaviorTreeTab 
                        agent={agent} 
                        version={version}
                        engine={engine} 
                    />
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { Agent } from '../../../engine/game';
import { Role, Skill, Team } from '../../../types';
import { ROLE_MAP, TAG_MAP, Helpers } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';

interface UnitStatusTabProps {
    agent: Agent;
    db: Skill[];
    onHoverSkill?: (skill: Skill | null) => void;
    onUpdate: () => void;
}

export const UnitStatusTab: React.FC<UnitStatusTabProps> = ({ agent, db, onHoverSkill, onUpdate }) => {

    const setRole = (r: string) => { 
        agent.role = r as Role; 
        onUpdate(); 
    };

    const setSkill = (idx: number, id: string) => {
        agent.skillIds[idx] = id || null; 
        onUpdate();
    };

    const roleConfig = Helpers.getRoleConfig(agent.role);

    return (
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 pb-24 space-y-8">
            {/* STAT BLOCK */}
            <div className="space-y-5">
                <div>
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block mb-2 ml-1">CLASS CONFIGURATION</label>
                    <select 
                        className={`liquid-input h-14 w-full text-lg font-bold cursor-pointer border-2 ${roleConfig.border} ${roleConfig.color} bg-black/40`}
                        value={agent.role} 
                        onChange={(e) => setRole(e.target.value)}
                    >
                        {Object.values(Role).map(r => <option key={r} value={r}>{ROLE_MAP[r].label}</option>)}
                    </select>
                </div>

                <div className="grid grid-cols-2 gap-5">
                    <div className="liquid-card-dark p-4 border border-white/5 relative group">
                        <label className="text-[10px] font-bold text-green-500/70 uppercase tracking-widest block mb-2">MAX INTEGRITY</label>
                        <input 
                            type="number" 
                            className="liquid-input h-12 w-full text-2xl text-center text-green-400 font-mono !bg-black/50 !border-green-900/50 focus:!border-green-500"
                            value={Math.round(agent.maxHp)} 
                            onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; onUpdate(); }} 
                        />
                        <div className="h-1 bg-black/50 mt-3 rounded-full overflow-hidden border border-white/5">
                            <div className="h-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]" style={{width: `${(agent.hp/agent.maxHp)*100}%`}}></div>
                        </div>
                    </div>
                    <div className="liquid-card-dark p-4 border border-white/5 relative group">
                        <label className="text-[10px] font-bold text-blue-500/70 uppercase tracking-widest block mb-2">MAX ENERGY</label>
                        <input 
                            type="number" 
                            className="liquid-input h-12 w-full text-2xl text-center text-blue-400 font-mono !bg-black/50 !border-blue-900/50 focus:!border-blue-500"
                            value={Math.round(agent.maxMp)} 
                            onChange={(e) => { agent.maxMp = parseInt(e.target.value); onUpdate(); }} 
                        />
                        <div className="h-1 bg-black/50 mt-3 rounded-full overflow-hidden border border-white/5">
                            <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]" style={{width: `${(agent.mp/agent.maxMp)*100}%`}}></div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="border-t border-white/10 pt-6">
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-4 ml-1">NEURAL LINKAGE (SKILLS)</div>
                <div className="space-y-4">
                    {['ULT', 'ACTIVE', 'BASIC'].map((tag, i) => {
                        const currentSkillId = agent.skillIds[i];
                        const currentSkill = db.find(s => s.id === currentSkillId);

                        const availableSkills = db.filter(s => s.tag === tag);
                        const skillsByRole: Record<string, Skill[]> = {};
                        availableSkills.forEach(s => {
                            if(!skillsByRole[s.role]) skillsByRole[s.role] = [];
                            skillsByRole[s.role].push(s);
                        });
                        const roleOrder = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

                        return (
                            <div key={i} className="liquid-card !bg-slate-900/40 border border-white/5 transition-all hover:border-white/20 group" onMouseEnter={() => onHoverSkill && onHoverSkill(currentSkill || null)} onMouseLeave={() => onHoverSkill && onHoverSkill(null)}>
                                <div className="flex items-center gap-4 p-4 border-b border-white/5 bg-white/[0.02]">
                                    <SkillIcon skill={currentSkill || null} className="w-14 h-14 !rounded-2xl shadow-lg" />
                                    <div className="flex-1">
                                        <div className="text-[10px] font-bold text-slate-500 mb-1.5 flex justify-between uppercase tracking-wider">
                                            <span>{TAG_MAP[tag].label} SLOT</span>
                                            {currentSkill && <span className="text-cyan-500/50 font-mono">ID: {currentSkill.id}</span>}
                                        </div>
                                        <div className="relative">
                                            <select 
                                                className={`liquid-input h-10 w-full text-sm font-bold appearance-none cursor-pointer uppercase tracking-wide ${!currentSkillId ? 'text-slate-500' : 'text-slate-200'}`}
                                                value={agent.skillIds[i] || ""} 
                                                onChange={(e) => setSkill(i, e.target.value)}
                                            >
                                                <option value="">-- EMPTY SLOT --</option>
                                                {roleOrder.map(role => {
                                                    const skills = skillsByRole[role];
                                                    if (!skills || skills.length === 0) return null;
                                                    return (
                                                        <optgroup key={role} label={ROLE_MAP[role].label} className="bg-slate-900 text-slate-400">
                                                            {skills.map(s => (
                                                                <option key={s.id} value={s.id} className="text-white">
                                                                    {s.name} {s.team !== undefined ? (s.team === Team.BLUE ? '🔵' : '🔴') : ''}
                                                                </option>
                                                            ))}
                                                        </optgroup>
                                                    );
                                                })}
                                            </select>
                                            <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[10px]">▼</div>
                                        </div>
                                    </div>
                                </div>

                                {currentSkill && (
                                    <div className="p-4 text-sm bg-black/20">
                                        <div className="text-slate-400 italic mb-4 leading-relaxed pl-3 border-l-2 border-slate-700/50">
                                            "{currentSkill.desc}"
                                        </div>
                                        <div className="grid grid-cols-4 gap-2 text-xs font-mono text-slate-300">
                                            <div className="liquid-card-dark p-2 text-center">
                                                <div className="text-slate-500 text-[9px] mb-1 uppercase">PWR</div>
                                                <div className="font-bold text-base text-white">{currentSkill.power}</div>
                                            </div>
                                            <div className="liquid-card-dark p-2 text-center">
                                                <div className="text-slate-500 text-[9px] mb-1 uppercase">CD</div>
                                                <div className="font-bold text-base text-white">{currentSkill.cd}s</div>
                                            </div>
                                            <div className="liquid-card-dark p-2 text-center">
                                                <div className="text-slate-500 text-[9px] mb-1 uppercase">COST</div>
                                                <div className="font-bold text-base text-blue-400">{currentSkill.cost}</div>
                                            </div>
                                            <div className="liquid-card-dark p-2 text-center">
                                                <div className="text-slate-500 text-[9px] mb-1 uppercase">RNG</div>
                                                <div className="font-bold text-base text-white">{currentSkill.range}</div>
                                            </div>
                                        </div>
                                        {(currentSkill.ccType || currentSkill.effectType) && (
                                            <div className="mt-4 pt-3 border-t border-white/5 flex gap-2 flex-wrap">
                                                {currentSkill.ccType && <span className="liquid-tag bg-amber-500/10 border-amber-500/30 text-amber-300">{currentSkill.ccType}</span>}
                                                {currentSkill.effectType && <span className="liquid-tag bg-purple-500/10 border-purple-500/30 text-purple-300">{currentSkill.effectType}</span>}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState, memo } from 'react';
import { LogEntry, Team } from '../../../types';

interface LogTabProps {
    engine: any;
}

const LogItem = memo(({ log }: { log: LogEntry }) => (
    <div className="group flex items-start gap-4 py-3 px-4 border-b border-white/5 hover:bg-white/5 transition-all duration-200 text-xs font-mono relative overflow-hidden">
        {/* Hover Highlight Bar */}
        <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-cyan-500/0 group-hover:bg-cyan-500/50 transition-colors"></div>

        <span className="text-slate-600 shrink-0 w-12 text-right group-hover:text-cyan-500/70 transition-colors pt-0.5">
            {log.time}s
        </span>
        <div className="flex-1 min-w-0">
            <div className="flex items-center gap-3 mb-1">
                <span className={`font-bold tracking-tight text-sm ${log.team === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_8px_rgba(96,165,250,0.4)]' : (log.team === Team.RED ? 'text-red-400 drop-shadow-[0_0_8px_rgba(248,113,113,0.4)]' : 'text-slate-400')}`}>
                    {log.agentId || 'SYSTEM'}
                </span>
                <span className="liquid-tag bg-white/5 border-white/10 text-slate-300">
                    {log.action}
                </span>
                {log.target && log.target !== '自身' && (
                    <>
                        <span className="text-slate-600">➜</span>
                        <span className="text-amber-200 opacity-90 font-bold tracking-tight">{log.target}</span>
                    </>
                )}
            </div>
            <p className="text-slate-400 group-hover:text-slate-200 transition-colors leading-relaxed opacity-80 pl-1">
                {log.detail}
            </p>
        </div>
    </div>
));

export const LogTab: React.FC<LogTabProps> = ({ engine }) => {
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);

    useEffect(() => {
        const interval = setInterval(() => {
            if (engine.logs.length !== localLogs.length) setLocalLogs(engine.logs.slice(-100));
        }, 200);
        return () => clearInterval(interval);
    }, [engine, localLogs.length]);

    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Control Header */}
            <div className="flex justify-between items-center p-5 border-b border-white/10 shrink-0 bg-white/[0.02]">
                <div className="flex items-center gap-3">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse box-shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                    <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest text-glow-cyan">REAL-TIME DATA STREAM</span>
                </div>
                <button 
                    onClick={downloadLogs} 
                    className="liquid-btn px-4 py-1.5 !text-[10px] rounded-lg border-white/20 text-slate-300 hover:text-white"
                >
                    EXPORT JSON
                </button>
            </div>

            {/* Log Stream */}
            <div className="flex-1 overflow-y-auto custom-scrollbar pb-24 scroll-smooth">
                {localLogs.slice().reverse().map(log => (
                    <LogItem key={log.id} log={log} />
                ))}
                {localLogs.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-40 opacity-30 gap-3 mt-10">
                        <span className="text-4xl filter grayscale opacity-50">📡</span>
                        <span className="text-xs font-mono tracking-widest">AWAITING SIGNAL...</span>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Role, Skill, Team } from '../../../types';
import { SKILL_FIELD_GROUPS, TAG_MAP, ROLE_MAP } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';

interface SkillDbTabProps {
    db: Skill[];
    onUpdate: () => void;
}

export const SkillDbTab: React.FC<SkillDbTabProps> = ({ db, onUpdate }) => {
    const [dbTypeTab, setDbTypeTab] = useState<'ALL' | 'BASIC' | 'ACTIVE' | 'ULT'>('ALL');
    const [dbRoleFilter, setDbRoleFilter] = useState<Role | 'ALL'>('ALL');
    const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);

    const filteredSkills = db.filter(s => {
        if (dbTypeTab !== 'ALL' && s.tag !== dbTypeTab) return false;
        if (dbRoleFilter !== 'ALL' && s.role !== dbRoleFilter) return false;
        return true;
    });

    const updateSkill = (field: keyof Skill, value: any) => {
        const skill = db.find(s => s.id === selectedSkillId);
        if (skill) { 
            if (field === 'team') {
                if (value === 'ANY') (skill as any)[field] = undefined;
                else if (value === 'BLUE') (skill as any)[field] = Team.BLUE;
                else if (value === 'RED') (skill as any)[field] = Team.RED;
            } else {
                (skill as any)[field] = value; 
            }
            onUpdate(); 
        }
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Header / Controls */}
            <div className="p-5 border-b border-white/10 shrink-0 space-y-4 bg-white/[0.02]">
                <div className="flex justify-between items-end">
                    <div className="text-xs font-bold text-slate-400 uppercase tracking-widest">NEURAL ARCHIVE</div>
                    <div className="text-[10px] font-mono text-cyan-400 text-glow-cyan">
                        INDEX: {filteredSkills.length} / {db.length}
                    </div>
                </div>

                <div className="flex flex-col gap-3">
                    {/* Type Tabs */}
                    <div className="flex liquid-card-dark p-1 gap-1">
                        {['ALL', 'BASIC', 'ACTIVE', 'ULT'].map(t => (
                            <button 
                                key={t}
                                onClick={() => setDbTypeTab(t as any)} 
                                className={`flex-1 py-2 text-[10px] rounded-xl font-bold transition-all uppercase tracking-wider ${dbTypeTab === t ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 shadow-[0_0_10px_rgba(6,182,212,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
                            >
                                {t === 'ALL' ? 'ALL' : TAG_MAP[t].label}
                            </button>
                        ))}
                    </div>

                    {/* Role Select */}
                    <div className="relative group">
                        <select 
                            className="liquid-input w-full h-10 text-xs appearance-none cursor-pointer uppercase font-bold tracking-wider group-hover:border-white/30 transition-colors"
                            value={dbRoleFilter}
                            onChange={(e) => setDbRoleFilter(e.target.value as any)}
                        >
                            <option value="ALL">FILTER CLASS: ALL</option>
                            {Object.values(Role).map(r => <option key={r} value={r}>FILTER: {ROLE_MAP[r].label}</option>)}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-xs">▼</div>
                    </div>
                </div>
            </div>

            {/* List Area */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 pb-24 space-y-3">
                {filteredSkills.map(skill => {
                    const isSelected = selectedSkillId === skill.id;
                    return (
                        <div 
                            key={skill.id} 
                            className={`liquid-card !rounded-2xl transition-all duration-300 overflow-hidden ${isSelected ? 'border-cyan-500/50 shadow-[0_0_20px_rgba(6,182,212,0.15)] bg-slate-900/80' : 'hover:border-white/20 hover:scale-[1.01] bg-slate-900/40'}`}
                        >
                            <div 
                                className="flex items-center gap-4 p-3 cursor-pointer select-none"
                                onClick={() => setSelectedSkillId(isSelected ? null : skill.id)}
                            >
                                <SkillIcon skill={skill} className="w-12 h-12 !rounded-xl !border-white/10 shadow-md" />
                                <div className="flex-1 min-w-0">
                                    <div className={`font-bold text-sm ${isSelected ? 'text-cyan-300' : 'text-slate-200'}`}>{skill.name}</div>
                                    <div className="text-[10px] text-slate-500 flex gap-2 items-center mt-1 uppercase font-bold tracking-wider">
                                        <span>{ROLE_MAP[skill.role].label}</span>
                                        <span className="w-1 h-1 bg-slate-600 rounded-full"></span>
                                        <span className={`${skill.tag === 'ULT' ? 'text-purple-400' : (skill.tag === 'ACTIVE' ? 'text-blue-400' : 'text-slate-400')}`}>{TAG_MAP[skill.tag].label}</span>
                                    </div>
                                </div>
                                <div className={`text-xl transition-transform duration-300 ${isSelected ? 'rotate-90 text-cyan-400' : 'text-slate-600'}`}>
                                    ›
                                </div>
                            </div>

                            {/* Edit Form */}
                            {isSelected && (
                                <div className="p-4 bg-black/40 border-t border-white/5 space-y-5 animate-slide-down">
                                    {SKILL_FIELD_GROUPS.map((group) => (
                                        <div key={group.name} className="space-y-3">
                                            <div className="flex items-center gap-2 pb-1 border-b border-white/5">
                                                <div className="w-1 h-1 bg-cyan-500 rounded-full"></div>
                                                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{group.name}</span>
                                            </div>

                                            <div className="grid grid-cols-2 gap-3">
                                                {group.fields.map((field) => {
                                                    const val = (skill as any)[field.key];
                                                    let displayVal = val;

                                                    if (field.key === 'team') {
                                                        if (val === undefined) displayVal = 'ANY';
                                                        else if (val === Team.BLUE) displayVal = 'BLUE';
                                                        else if (val === Team.RED) displayVal = 'RED';
                                                    } else if (val === undefined || val === null) {
                                                        displayVal = '';
                                                    }

                                                    const isWide = field.type === 'textarea';

                                                    return (
                                                        <div key={field.key} className={isWide ? "col-span-2 space-y-1" : "space-y-1"}>
                                                            <label className="text-[9px] font-bold text-slate-400 block ml-1" title={field.label}>{field.label}</label>

                                                            {field.type === 'textarea' ? (
                                                                <textarea 
                                                                    className="liquid-input w-full p-3 h-24 resize-none !rounded-xl leading-relaxed"
                                                                    value={displayVal}
                                                                    onChange={e => updateSkill(field.key, e.target.value)}
                                                                />
                                                            ) : field.type === 'select' ? (
                                                                <div className="relative">
                                                                    <select 
                                                                        className="liquid-input w-full h-9 text-xs appearance-none cursor-pointer"
                                                                        value={displayVal}
                                                                        onChange={e => {
                                                                            const v = e.target.value;
                                                                            if (v === 'NONE' || v === 'ANY' || v === '') updateSkill(field.key, undefined);
                                                                            else updateSkill(field.key, v); 
                                                                        }}
                                                                    >
                                                                        {field.options ? 
                                                                            field.options.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>) :
                                                                            field.simpleOptions?.map(opt => <option key={opt} value={opt}>{opt}</option>)
                                                                        }
                                                                    </select>
                                                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[10px]">▼</div>
                                                                </div>
                                                            ) : field.type === 'color' ? (
                                                                <div className="flex gap-2 items-center">
                                                                    <div className="relative flex-1">
                                                                        <input 
                                                                            type="text" 
                                                                            className="liquid-input w-full h-9 text-xs font-mono" 
                                                                            value={displayVal} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                    <div className="relative w-9 h-9 rounded-xl overflow-hidden border border-white/20 shadow-inner">
                                                                        <input 
                                                                            type="color" 
                                                                            className="absolute -top-1/2 -left-1/2 w-[200%] h-[200%] cursor-pointer p-0 border-0" 
                                                                            value={displayVal.startsWith('#') ? displayVal : '#ffffff'} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                </div>
                                                            ) : (
                                                                <input 
                                                                    type={field.type} 
                                                                    className="liquid-input w-full h-9 text-xs font-mono"
                                                                    value={displayVal}
                                                                    step={field.step || 1}
                                                                    onChange={e => updateSkill(field.key, field.type === 'number' ? parseFloat(e.target.value) : e.target.value)}
                                                                />
                                                            )}
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

type ConfigModalType = 'UNIT' | 'OBSTACLE' | null;

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    const [isOpen, setIsOpen] = useState(false);
    const [configModal, setConfigModal] = useState<ConfigModalType>(null);
    const [pendingTool, setPendingTool] = useState<ToolType | null>(null);

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    // Toggle logic: If clicking the active tool, switch back to SELECT (Default/Hand mode)
    const handleToolClick = (targetTool: ToolType) => {
        if (tool === targetTool) {
            setTool(ToolType.SELECT); // Toggle off
            return;
        }

        if (targetTool === ToolType.ADD_BLUE || targetTool === ToolType.ADD_RED) {
            setPendingTool(targetTool);
            setConfigModal('UNIT');
        } else if (targetTool === ToolType.OBSTACLE) {
            setPendingTool(targetTool);
            setConfigModal('OBSTACLE');
        } else {
            setTool(targetTool);
        }
    };

    const confirmConfig = () => {
        if (pendingTool) setTool(pendingTool);
        setConfigModal(null);
        setPendingTool(null);
    };

    return (
        <>
            {/* CONFIG MODALS (Liquid Glass) */}
            {configModal && (
                <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-md animate-fade-in" onClick={() => setConfigModal(null)}>
                    <div className="liquid-card p-6 w-80 animate-bounce-in flex flex-col gap-4 border border-white/10" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center border-b border-white/10 pb-3">
                            <span className="text-xs font-bold text-cyan-400 text-glow-cyan uppercase tracking-widest">
                                {configModal === 'UNIT' ? 'DEPLOY PARAMETERS' : 'OBSTACLE TYPE'}
                            </span>
                            <button onClick={() => setConfigModal(null)} className="liquid-icon-btn w-8 h-8 text-sm hover:text-red-400">✕</button>
                        </div>

                        {configModal === 'UNIT' && (
                            <div className="space-y-4">
                                <div>
                                    <label className="text-[10px] font-bold text-slate-400 block mb-2 tracking-wider">INITIAL HP</label>
                                    <input type="number" value={hpInput} onChange={(e) => setHpInput(parseInt(e.target.value))} className="liquid-input w-full text-center text-lg" />
                                </div>
                                <div className="flex liquid-card-dark p-1">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>RANDOM</button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-2 text-xs rounded-xl font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300 shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SELECT</button>
                                </div>
                                {spawnMode === 'DRAFT' && (
                                    <select value={draftRole} onChange={(e) => setDraftRole(e.target.value as Role)} className="liquid-input w-full h-10 cursor-pointer">
                                        {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                                    </select>
                                )}
                            </div>
                        )}

                        {configModal === 'OBSTACLE' && (
                            <select value={selectedObstacle} onChange={(e) => setSelectedObstacle(e.target.value)} className="liquid-input w-full h-12 text-center text-base cursor-pointer">
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}

                        <button onClick={confirmConfig} className="liquid-btn-primary w-full py-3 rounded-xl mt-2">
                            CONFIRM & EQUIP
                        </button>
                    </div>
                </div>
            )}

            {/* DRAGGABLE TOOLBAR */}
            <div 
                ref={ref}
                className="z-40"
                style={style}
                {...dragHandlers}
            >
                {/* CLOSED STATE - Improved Opacity (!bg-slate-950) */}
                {!isOpen && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsOpen(true); }}
                        onPointerDown={e => e.stopPropagation()} 
                        className="liquid-card !bg-slate-950 !rounded-full px-8 py-3 text-slate-300 hover:text-white hover:border-cyan-500/50 transition-all font-bold tracking-widest flex items-center gap-4 group cursor-pointer animate-float shadow-xl border-white/20"
                    >
                        <span className="text-xl filter drop-shadow-md">🛠️</span>
                        <span className="text-sm">EDITOR</span>

                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 flex gap-1 opacity-0 group-hover:opacity-50 transition-opacity" onPointerDown={dragHandlers.onPointerDown}>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                            <div className="w-1 h-1 bg-white rounded-full"></div>
                        </div>
                    </button>
                )}

                {/* OPEN STATE */}
                {isOpen && (
                    <div className={`liquid-card !bg-slate-900/90 !backdrop-blur-3xl !rounded-3xl p-3 pr-12 flex flex-col md:flex-row items-center gap-4 relative cursor-grab border border-white/10 shadow-[0_10px_40px_rgba(0,0,0,0.5)] ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                        {/* Drag Handle */}
                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-12 h-4 flex gap-1 justify-center items-center opacity-0 hover:opacity-50 transition-opacity">
                            <div className="w-8 h-1 bg-white/50 rounded-full"></div>
                        </div>

                        {/* Close Button */}
                        <button 
                            onClick={(e) => { e.stopPropagation(); setIsOpen(false); }}
                            onPointerDown={e => e.stopPropagation()}
                            className="absolute -top-3 -right-3 w-8 h-8 rounded-full bg-slate-800 border border-white/10 text-slate-400 hover:bg-red-500/20 hover:text-red-400 hover:border-red-500/50 flex items-center justify-center shadow-lg transition-all z-50 active:scale-95"
                        >
                            ✕
                        </button>

                        {/* 1. Map Settings */}
                        <div className="flex flex-col gap-2 p-3 liquid-card-dark" onPointerDown={e => e.stopPropagation()}>
                            <div className="text-[9px] font-bold text-slate-500 text-center uppercase tracking-wider">GRID SIZE</div>
                            <div className="flex gap-2 items-center justify-center">
                                <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, parseInt(e.target.value)))} className="liquid-input w-12 h-8 !px-1 text-center" />
                                <span className="text-slate-600 text-xs font-bold">×</span>
                                <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, parseInt(e.target.value)))} className="liquid-input w-12 h-8 !px-1 text-center" />
                            </div>
                            <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="liquid-input h-8 text-[10px] !py-0 cursor-pointer">
                                {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>

                        {/* Divider */}
                        <div className="hidden md:block w-px h-20 bg-gradient-to-b from-transparent via-white/10 to-transparent"></div>

                        {/* 2. Tools Group (Unified UX) */}
                        <div className="flex gap-3 p-1" onPointerDown={e => e.stopPropagation()}>
                            {/* NOTE: ToolType.SELECT is removed from UI. It is the default state when no other tool is active. */}

                            <button onClick={() => handleToolClick(ToolType.ADD_BLUE)} className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-300 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 hover:text-blue-300'}`} title="部署藍軍">🔵</button>
                            <button onClick={() => handleToolClick(ToolType.ADD_RED)} className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-300 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-300'}`} title="部署紅軍">🔴</button>

                            <div className="w-px h-8 bg-white/5 mx-1 my-auto"></div>

                            <button onClick={() => handleToolClick(ToolType.OBSTACLE)} className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-300 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 hover:text-amber-300'}`} title="放置障礙">🧱</button>
                            <button onClick={() => handleToolClick(ToolType.DELETE)} className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-500/20 text-red-400 border-red-500/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                        </div>
                    </div>
                )}
            </div>
        </>
    );
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

export const useGameInput = ({
    canvasRef, engine, rendererRef, cameraRef,
    tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
    onSelect, onCameraPan, onCameraZoom
}: GameInputProps) => {

    // --- 1. STATE REFS ---
    // Interaction States:
    // IDLE: Waiting
    // DOWN: Mouse/Touch is down, waiting to see if it becomes a drag, pan, or paint
    // DRAG_UNIT: Moving a unit (Editor only)
    // DRAG_OBS: Moving an obstacle (Editor only) - Legacy/Bonus feature
    // PAN: Moving camera
    // PAINT: Painting/Deleting grid cells (Editor only)
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Tooling State Refs
    const toolRef = useRef(tool);
    const obsRef = useRef(selectedObstacle);
    const hpRef = useRef(hpInput);
    const spawnRef = useRef(spawnMode);
    const roleRef = useRef(draftRole);
    const winnerRef = useRef(winner);

    useEffect(() => {
        toolRef.current = tool;
        obsRef.current = selectedObstacle;
        hpRef.current = hpInput;
        spawnRef.current = spawnMode;
        roleRef.current = draftRole;
        winnerRef.current = winner;
    }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // Operational Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // Tracking Refs
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    const lastPinchDist = useRef<number>(0);

    // --- 2. CORE UTILITIES ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPosFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgentFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;

        // Sort agents by screen Y (Painter's algorithm sort for hit test)
        // We use visual Y which includes height offset
        const agentsWithVisuals = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            // Rough visual center of the unit relative to ground
            const visualY = a.py - h - 40; 
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(item => item !== null) as { agent: Agent, visualY: number, dist: number }[];

        // Sort by visual Y desc (Front units first)
        agentsWithVisuals.sort((a, b) => b.visualY - a.visualY);

        for (const item of agentsWithVisuals) {
            // Hitbox: approx 40px wide, 70px tall around visual center
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 

            // Hitbox bias: -30 (top) to +40 (feet)
            if (dx < 35 && dy > -35 && dy < 40) {
                return item.agent;
            }
        }
        return null;
    };

    const executeToolAction = (h: Hex) => {
        const _tool = toolRef.current;
        const _winner = winnerRef.current;
        const _obs = obsRef.current;
        const _spawn = spawnRef.current;
        const _role = roleRef.current;
        const _hp = hpRef.current;

        // Painting is only allowed if not running and no winner
        if (engine.isRunning || _winner !== null) return;

        // Prevent spamming same hex in one drag
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 

        lastPaintHex.current = k;
        const existingAgent = engine.getAgentAt(h.q, h.r);
        let agent: Agent | null = null;

        if (_tool === ToolType.DELETE) {
            if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
            if (existingAgent) {
                engine.removeAgent(h.q, h.r);
                onSelect(null);
            }
            return;
        }

        if (_tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, _obs);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            if (_tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, _hp);
            else if (_tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, _hp);
        }

        if (agent && _spawn === 'DRAFT') {
            agent.role = _role;
            const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
            const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
            agent.skillIds = [
                rnd(validSkills.filter(s => s.tag === 'ULT')),
                rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                rnd(validSkills.filter(s => s.tag === 'BASIC'))
            ];
            agent.saveState();
            agent.reset(engine.mapConfig);
        }
    };

    // --- 3. UNIFIED INTERACTION LOGIC ---

    const startInteraction = (sx: number, sy: number, isRightClick: boolean) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        // Default to DOWN state (waiting for drag threshold)
        interactionMode.current = 'DOWN';

        // Right click always Pans
        if (isRightClick) {
            interactionMode.current = 'PAN';
            return;
        }

        // 1. Check for Unit Hit (Priority)
        // Even if running, we want to detect unit clicks for selection
        const hitAgent = getHitAgentFromCoords(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
            // If dragging isn't allowed (Running or Tool active), this remains 'DOWN'
            // and will become 'PAN' or 'SELECT' later.
            return;
        }

        // 2. Check for Obstacle Hit (Only if editing and not deleting)
        const isEditing = !engine.isRunning && winnerRef.current === null;
        if (isEditing && toolRef.current === ToolType.SELECT) {
            const h = getHexFromCoords(sx, sy);
            if (engine.isValid(h.q, h.r) && engine.hasObstacle(h.q, h.r)) {
                const obsType = engine.obstacles.get(HexUtils.key(h));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
                }
            }
        }

        // 3. If a tool is active (Deploy/Obstacle/Delete) and we hit ground
        const activeTool = toolRef.current !== ToolType.SELECT;
        if (activeTool && isEditing) {
            // We are prepared to Paint
            // We don't paint immediately on Down to allow for small jitter/clicks vs intended drags
            // But usually painting feels better if immediate? 
            // Let's keep it 'DOWN' and execute on small move or up.
        }
    };

    const updateInteraction = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);

        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        // Cursor Logic
        if (cvs) {
            const hitAgent = getHitAgentFromCoords(sx, sy);
            const isEditing = !engine.isRunning && winnerRef.current === null;
            const isTool = toolRef.current !== ToolType.SELECT;

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (isTool && isEditing) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer'; 
            else if (engine.hasObstacle(h.q, h.r) && isEditing) cvs.style.cursor = 'grab';
            else cvs.style.cursor = 'default'; 
        }

        const prev = lastPointerPos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastPointerPos.current = { x: sx, y: sy };

        if (interactionMode.current === 'IDLE') return;

        // --- ACTIVE STATES ---

        if (interactionMode.current === 'PAN') {
            onCameraPan(dx, dy); 
            return;
        }

        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executeToolAction(h);
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // --- THRESHOLD CHECK (DOWN -> ?) ---
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
            // Only change state if moved significantly
            if (dist > 8) {
                const _tool = toolRef.current;
                const isEditing = !engine.isRunning && winnerRef.current === null;

                // A. Painting Tool Active -> Paint Mode
                if (isEditing && _tool !== ToolType.SELECT) {
                    interactionMode.current = 'PAINT';
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                    return;
                }

                // B. Hit Unit & Editing & No Tool -> Drag Unit
                if (pressedAgentRef.current && isEditing && _tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                    return;
                }

                // C. Hit Obstacle & Editing & No Tool -> Drag Obstacle
                if (draggedObstacleRef.current && isEditing && _tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    onSelect(null);
                    const wPos = getWorldPosFromCoords(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                    return;
                }

                // D. Otherwise -> Pan Camera
                interactionMode.current = 'PAN';
                onCameraPan(dx, dy);
            }
        }
    };

    const endInteraction = (sx: number, sy: number) => {
        const h = getHexFromCoords(sx, sy);
        const isEditing = !engine.isRunning && winnerRef.current === null;
        const _tool = toolRef.current;

        // 1. CLICK LOGIC (Released without dragging much)
        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                // Unit Clicked: Select (Works in Battle & Edit)
                // If Delete tool is active, delete it
                if (isEditing && _tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (engine.hasObstacle(h.q, h.r) && isEditing) {
                if (_tool === ToolType.DELETE) engine.removeObstacle(h.q, h.r);
            } else if (isEditing && _tool !== ToolType.SELECT) {
                // Clicked empty ground with Paint Tool -> Paint once
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            } else {
                // Clicked empty ground with no tool -> Deselect
                onSelect(null);
            }
        }

        // 2. DRAG DROP LOGIC
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.hasObstacle(h.q, h.r) && (!engine.getAgentAt(h.q, h.r) || engine.getAgentAt(h.q, h.r) === agent);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else if (dragStartHex.current) {
                // Revert
                agent.q = dragStartHex.current.q;
                agent.r = dragStartHex.current.r;
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
                engine.updateAgentPosition(agent, agent.q, agent.r);
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);

            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); // Revert
        }

        // Reset
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPointerPos.current = null;
        lastPaintHex.current = "";
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    // --- 4. PLATFORM HANDLERS ---

    const setupMouseListeners = (cvs: HTMLCanvasElement) => {
        const getCoords = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            return { x: e.clientX - rect.left, y: e.clientY - rect.top };
        };

        const onMouseDown = (e: MouseEvent) => {
            const { x, y } = getCoords(e);
            startInteraction(x, y, e.button === 2);
        };

        const onMouseMove = (e: MouseEvent) => {
            const { x, y } = getCoords(e);
            updateInteraction(x, y);
        };

        const onMouseUp = (e: MouseEvent) => {
            const { x, y } = getCoords(e);
            endInteraction(x, y);
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };

        const onCtx = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
        };
    };

    const setupTouchListeners = (cvs: HTMLCanvasElement) => {
        const getCoords = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const { x, y } = getCoords(e.touches[0]);
                startInteraction(x, y, false);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE'; 
                pressedAgentRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const { x, y } = getCoords(e.touches[0]);
                updateInteraction(x, y);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    const delta = dist - lastPinchDist.current;
                    onCameraZoom(delta * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getCoords(e.changedTouches[0]);
                endInteraction(x, y);
            }
            if (e.touches.length < 2) lastPinchDist.current = 0;
        };

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchEnd);
        };
    };

    // --- 5. INITIALIZATION ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const cleanupMouse = setupMouseListeners(cvs);
        const cleanupTouch = setupTouchListeners(cvs);

        return () => {
            cleanupMouse();
            cleanupTouch();
        };
    }, []); 

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan, onCameraZoom 
    } = props;

    // --- State Refs (Mutable for Performance) ---
    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Action Context Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const lastPaintHex = useRef<string>("");

    // Config Refs (Sync with props to avoid stale closures in event listeners)
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // --- 1. HELPERS: Coordinate Mapping & Hit Testing ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPos = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgent = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;

        // Painter's Algorithm Hit Test (Front units first)
        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; 
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);

        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    // --- 2. LOGIC: Action Execution ---

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;

        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
            return;
        }

        const existingAgent = engine.getAgentAt(h.q, h.r);
        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            let agent: Agent | null = null;
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                // Assign random skills for draft role
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        }
    };

    // --- 3. EVENT HANDLERS (Unified Logic) ---

    const handleInputStart = (sx: number, sy: number, isRightClick: boolean) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        if (isRightClick) {
            interactionMode.current = 'PAN';
            return;
        }

        // 1. Hit Test Agent
        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN'; // Wait to see if drag or click
            return;
        }

        // 2. Editing Logic
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (isEditing) {
            // Hit Obstacle?
            if (tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
                const obsType = engine.obstacles.get(HexUtils.key(h));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            // Paint Tool?
            if (tool !== ToolType.SELECT) {
                // Immediate paint on down for better feel
                if (engine.isValid(h.q, h.r)) {
                    executePaintAction(h);
                    interactionMode.current = 'PAINT';
                }
                return;
            }
        }

        interactionMode.current = 'DOWN'; // Default to potential pan
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        // Cursor & Hover Logic
        if (cvs) {
            const { tool, winner } = configRef.current;
            const isEditing = !engine.isRunning && winner === null;
            const hitAgent = getHitAgent(sx, sy);

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (isEditing && tool !== ToolType.SELECT) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        const prev = lastPointerPos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastPointerPos.current = { x: sx, y: sy };

        // --- Active State Handling ---
        if (interactionMode.current === 'PAN') {
            onCameraPan(dx, dy);
            return;
        }
        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executePaintAction(h);
            return;
        }
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // --- State Transition (Threshold Check) ---
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 8) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;

                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; // Lift
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    // Remove from grid temporarily
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    const wPos = getWorldPos(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                } else {
                    interactionMode.current = 'PAN';
                    onCameraPan(dx, dy);
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        // Click Logic (Released without dragging)
        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (isEditing && engine.hasObstacle(h.q, h.r) && tool === ToolType.DELETE) {
                engine.removeObstacle(h.q, h.r);
            } else if (!pressedAgentRef.current) {
                onSelect(null);
            }
        }

        // Drop Logic
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, engine, agent.id, agent.movementType);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                // Revert
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); // Revert
        }

        // Reset
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
    };

    // --- 4. BINDINGS ---

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        // --- Mouse ---
        const onMouseDown = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top, e.button === 2);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };
        const onCtx = (e: MouseEvent) => e.preventDefault();

        // --- Touch ---
        const getTouchPos = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };
        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputStart(x, y, false);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE'; 
            }
        };
        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputMove(x, y);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    onCameraZoom((dist - lastPinchDist.current) * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };
        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getTouchPos(e.changedTouches[0]);
                handleInputEnd(x, y);
            }
            if (e.touches.length < 2) lastPinchDist.current = 0;
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchEnd);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import React, { useRef } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';
import { useDraggable } from '../../hooks/useDraggable';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;
}

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle
    } = props;

    // Draggable Hook
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-center',
        margin: 40
    });

    const isUnitTool = tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED;
    const isObstacleTool = tool === ToolType.OBSTACLE;

    return (
        <div 
            ref={ref}
            className={`z-40 flex flex-col items-center gap-2`}
            style={style}
            {...dragHandlers}
        >
            {/* MAIN TOOLBAR */}
            <div className={`liquid-card !bg-slate-900/90 !backdrop-blur-3xl !rounded-full p-2 flex items-center gap-2 shadow-[0_10px_40px_rgba(0,0,0,0.5)] cursor-grab ${isDragging ? 'cursor-grabbing ring-2 ring-cyan-500/30' : ''}`}>

                {/* Drag Handle */}
                <div className="w-6 flex flex-col gap-1 items-center justify-center opacity-30 hover:opacity-100 transition-opacity px-2 border-r border-white/10" onPointerDown={dragHandlers.onPointerDown}>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                    <div className="w-1 h-1 bg-white rounded-full"></div>
                </div>

                {/* 1. SELECT */}
                <button 
                    onClick={() => setTool(ToolType.SELECT)} 
                    className={`liquid-icon-btn ${tool === ToolType.SELECT ? 'bg-white/20 text-white border-white/40 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'text-slate-400 border-transparent bg-transparent hover:bg-white/10'}`}
                    title="選取 / 移動"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" /></svg>
                </button>

                <div className="w-px h-6 bg-white/10 mx-1"></div>

                {/* 2. BLUE TEAM */}
                <button 
                    onClick={() => setTool(ToolType.ADD_BLUE)} 
                    className={`liquid-icon-btn ${tool === ToolType.ADD_BLUE ? 'bg-blue-500/20 text-blue-400 border-blue-400/50 shadow-[0_0_15px_rgba(59,130,246,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-blue-400 hover:bg-blue-500/10'}`}
                    title="部署藍軍"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <svg className="w-5 h-5 fill-current" viewBox="0 0 24 24"><path d="M12 2L2 22h20L12 2zm0 4.8l5.6 11.2H6.4L12 6.8z"/></svg>
                </button>

                {/* 3. RED TEAM */}
                <button 
                    onClick={() => setTool(ToolType.ADD_RED)} 
                    className={`liquid-icon-btn ${tool === ToolType.ADD_RED ? 'bg-red-500/20 text-red-400 border-red-400/50 shadow-[0_0_15px_rgba(239,68,68,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-red-400 hover:bg-red-500/10'}`}
                    title="部署紅軍"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <svg className="w-5 h-5 fill-current" viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zm0 9l2.5-1.25L12 12l-2.5-1.25L12 11zm0 2.5l-5-2.5-5 2.5L12 22l10-8.5-5-2.5-5 2.5z"/></svg>
                </button>

                <div className="w-px h-6 bg-white/10 mx-1"></div>

                {/* 4. OBSTACLE */}
                <button 
                    onClick={() => setTool(ToolType.OBSTACLE)} 
                    className={`liquid-icon-btn ${tool === ToolType.OBSTACLE ? 'bg-amber-500/20 text-amber-400 border-amber-400/50 shadow-[0_0_15px_rgba(245,158,11,0.4)]' : 'text-slate-500 border-transparent bg-transparent hover:text-amber-400 hover:bg-amber-500/10'}`}
                    title="地形編輯"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                </button>

                {/* 5. DELETE */}
                <button 
                    onClick={() => setTool(ToolType.DELETE)} 
                    className={`liquid-icon-btn ${tool === ToolType.DELETE ? 'bg-red-900/50 text-red-500 border-red-800 shadow-inner' : 'text-slate-500 border-transparent bg-transparent hover:text-red-500 hover:bg-red-900/20'}`}
                    title="移除"
                    onPointerDown={e => e.stopPropagation()}
                >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
            </div>

            {/* SUB MENU: UNIT SETTINGS */}
            {isUnitTool && (
                <div className="liquid-card !rounded-2xl p-2 flex items-center gap-3 animate-slide-down origin-top shadow-xl border-t-0" onPointerDown={e => e.stopPropagation()}>
                    {/* HP Input */}
                    <div className="flex items-center gap-1 bg-black/40 rounded-lg px-2 py-1 border border-white/5">
                        <span className="text-[10px] font-bold text-green-500">HP</span>
                        <input 
                            type="number" 
                            value={hpInput} 
                            onChange={(e) => setHpInput(Math.max(1, parseInt(e.target.value)))} 
                            className="w-10 bg-transparent text-white text-xs font-mono text-center outline-none"
                        />
                    </div>

                    {/* Mode Toggle */}
                    <div className="flex bg-black/40 rounded-lg p-0.5 border border-white/5">
                        <button onClick={() => setSpawnMode('RANDOM')} className={`px-2 py-1 rounded text-[10px] font-bold transition-all ${spawnMode === 'RANDOM' ? 'bg-cyan-500/20 text-cyan-300' : 'text-slate-500 hover:text-slate-300'}`}>RND</button>
                        <button onClick={() => setSpawnMode('DRAFT')} className={`px-2 py-1 rounded text-[10px] font-bold transition-all ${spawnMode === 'DRAFT' ? 'bg-amber-500/20 text-amber-300' : 'text-slate-500 hover:text-slate-300'}`}>FIX</button>
                    </div>

                    {/* Role Select (Only in Draft) */}
                    {spawnMode === 'DRAFT' && (
                        <select 
                            value={draftRole} 
                            onChange={(e) => setDraftRole(e.target.value as Role)} 
                            className="bg-black/40 text-xs text-white rounded-lg px-2 py-1 border border-white/5 outline-none cursor-pointer hover:border-cyan-500/30"
                        >
                            {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    )}
                </div>
            )}

            {/* SUB MENU: OBSTACLE SETTINGS */}
            {isObstacleTool && (
                <div className="liquid-card !rounded-2xl p-2 flex items-center gap-3 animate-slide-down origin-top shadow-xl border-t-0" onPointerDown={e => e.stopPropagation()}>
                    <select 
                        value={selectedObstacle} 
                        onChange={(e) => setSelectedObstacle(e.target.value)} 
                        className="bg-black/40 text-xs text-white rounded-lg px-3 py-1.5 border border-white/5 outline-none cursor-pointer hover:border-amber-500/30 w-32"
                    >
                        {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                    </select>

                    {/* Scene Select Shortcut */}
                    <select value={currentSceneId} onChange={(e) => onSetScene(e.target.value)} className="bg-black/40 text-[10px] text-slate-400 rounded-lg px-2 py-1.5 border border-white/5 outline-none cursor-pointer hover:text-white w-24">
                        {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                </div>
            )}
        </div>
    );
};

