import React, { useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { Role, Skill } from '../../types';
import { UnitStatusTab } from '../inspector/tabs/UnitStatusTab';
import { BehaviorTreeTab } from '../inspector/tabs/BehaviorTreeTab';
import { Icons } from './icons';

interface UnitDetailViewProps {
    agent: Agent;
    db: Skill[];
    engine: GameEngine;
}

export const UnitDetailView: React.FC<UnitDetailViewProps> = ({ agent, db, engine }) => {
    const [subTab, setSubTab] = useState<'STATUS' | 'AI'>('STATUS');
    const [version, setVersion] = useState(0); 

    // Refresh Loop for visual updates (Health, AI Nodes)
    useEffect(() => {
        const interval = setInterval(() => setVersion(n => n + 1), 100); // 10 FPS is enough for UI
        return () => clearInterval(interval);
    }, []);

    const handleUpdate = () => {
        setVersion(n => n + 1);
    };

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-6 h-6" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-6 h-6" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-6 h-6" />;
            case Role.MAGE: return <Icons.RoleMage className="w-6 h-6" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-6 h-6" />;
            default: return null;
        }
    };

    return (
        <div className="flex flex-col h-full w-full select-none">
            {/* UNIT HEADER (Liquid Glass) */}
            <div className="p-5 border-b border-white/10 shrink-0 z-20 flex items-center justify-between gap-4 bg-slate-900/40 backdrop-blur-md">
                <div className="flex items-center gap-4">
                    <div className={`w-12 h-12 flex items-center justify-center rounded-2xl liquid-card-dark border text-2xl shadow-inner ${agent.team === 0 ? 'border-blue-500/50 text-blue-400' : 'border-red-500/50 text-red-400'}`}>
                        {renderRoleIcon(agent.role)}
                    </div>
                    <div>
                        <div className="font-mono font-black text-2xl leading-none text-white tracking-tight">{agent.id}</div>
                        <div className="flex items-center gap-2 mt-1">
                            <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase bg-white/5 px-2 py-0.5 rounded-full border border-white/5">Level 1</span>
                            <span className={`text-[10px] font-bold tracking-widest uppercase ${agent.team === 0 ? 'text-blue-400' : 'text-red-400'}`}>{agent.role}</span>
                        </div>
                    </div>
                </div>

                {/* SUB TABS (Liquid Capsules) */}
                <div className="flex liquid-card-dark p-1 gap-1">
                    <button onClick={() => setSubTab('STATUS')} className={`px-6 py-2 text-xs rounded-xl font-bold transition-all uppercase tracking-wider ${subTab === 'STATUS' ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 shadow-[0_0_15px_rgba(6,182,212,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>STATUS</button>
                    <button onClick={() => setSubTab('AI')} className={`px-6 py-2 text-xs rounded-xl font-bold transition-all uppercase tracking-wider ${subTab === 'AI' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30 shadow-[0_0_15px_rgba(245,158,11,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>BEHAVIOR</button>
                </div>
            </div>

            {/* CONTENT AREA */}
            <div className="flex-1 overflow-hidden relative">
                {subTab === 'STATUS' ? (
                    <UnitStatusTab 
                        agent={agent} 
                        db={db} 
                        onHoverSkill={() => {}} 
                        onUpdate={handleUpdate}
                    />
                ) : (
                    <BehaviorTreeTab 
                        agent={agent} 
                        version={version}
                        engine={engine} 
                    />
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { LogTab } from '../inspector/tabs/LogTab';
import { SkillDbTab } from '../inspector/tabs/SkillDbTab';
import { UnitDetailView } from '../ui/UnitDetailView';
import { Icons } from './icons';

interface ModalManagerProps {
    showLogs: boolean;
    showDB: boolean;
    showUnitDetail: boolean;
    selectedAgent: Agent | null;
    engine: GameEngine;
    onClose: () => void;
}

export const ModalManager: React.FC<ModalManagerProps> = ({
    showLogs, showDB, showUnitDetail, selectedAgent, engine, onClose
}) => {

    if (!showLogs && !showDB && (!showUnitDetail || !selectedAgent)) {
        return null;
    }

    return (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-md p-4 md:p-8 animate-fade-in" 
             onClick={onClose}>

            {/* Main Modal Container */}
            <div className="liquid-card w-full h-[90%] max-w-6xl overflow-hidden flex flex-col animate-bounce-in bg-black/80" onClick={e => e.stopPropagation()}>

                {/* Header */}
                <div className="flex justify-between items-center p-5 border-b border-white/10 shrink-0 bg-white/5">
                    <h2 className="text-lg font-bold text-white tracking-widest flex items-center gap-3">
                        {showLogs && <><Icons.Log className="w-6 h-6 text-cyan-400" /> BATTLE LOGS</>}
                        {showDB && <><Icons.Database className="w-6 h-6 text-amber-400" /> SKILL DATABASE</>}
                        {showUnitDetail && <><Icons.Settings className="w-6 h-6 text-cyan-400" /> NEURAL ANALYSIS</>}
                    </h2>
                    <button onClick={onClose} className="w-10 h-10 rounded-xl hover:bg-white/10 flex items-center justify-center text-slate-400 hover:text-white transition-all border border-transparent hover:border-white/10">
                        <Icons.Close className="w-5 h-5" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-hidden relative min-h-0">
                    {showLogs && <LogTab engine={engine} />}
                    {showDB && <SkillDbTab db={engine.skillDB} onUpdate={() => {}} />}
                    {showUnitDetail && selectedAgent && <UnitDetailView agent={selectedAgent} db={engine.skillDB} engine={engine} />}
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState, memo } from 'react';
import { LogEntry, Team } from '../../../types';
import { Icons } from '../../ui/icons';

interface LogTabProps {
    engine: any;
}

const LogItem = memo(({ log }: { log: LogEntry }) => (
    <div className="group flex items-start gap-4 py-3 px-4 border-b border-white/5 hover:bg-white/5 transition-all duration-200 text-xs font-mono relative overflow-hidden">
        {/* Hover Highlight Bar */}
        <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-cyan-500/0 group-hover:bg-cyan-500/50 transition-colors"></div>

        <span className="text-slate-600 shrink-0 w-12 text-right group-hover:text-cyan-500/70 transition-colors pt-0.5">
            {log.time}s
        </span>
        <div className="flex-1 min-w-0">
            <div className="flex items-center gap-3 mb-1">
                <span className={`font-bold tracking-tight text-sm ${log.team === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_8px_rgba(96,165,250,0.4)]' : (log.team === Team.RED ? 'text-red-400 drop-shadow-[0_0_8px_rgba(248,113,113,0.4)]' : 'text-slate-400')}`}>
                    {log.agentId || 'SYSTEM'}
                </span>
                <span className="liquid-tag bg-white/5 border-white/10 text-slate-300">
                    {log.action}
                </span>
                {log.target && log.target !== '自身' && (
                    <>
                        <span className="text-slate-600">➜</span>
                        <span className="text-amber-200 opacity-90 font-bold tracking-tight">{log.target}</span>
                    </>
                )}
            </div>
            <p className="text-slate-400 group-hover:text-slate-200 transition-colors leading-relaxed opacity-80 pl-1">
                {log.detail}
            </p>
        </div>
    </div>
));

export const LogTab: React.FC<LogTabProps> = ({ engine }) => {
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);

    useEffect(() => {
        const interval = setInterval(() => {
            if (engine.logs.length !== localLogs.length) setLocalLogs(engine.logs.slice(-100));
        }, 200);
        return () => clearInterval(interval);
    }, [engine, localLogs.length]);

    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Control Header */}
            <div className="flex justify-between items-center p-5 border-b border-white/10 shrink-0 bg-white/[0.02]">
                <div className="flex items-center gap-3">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse box-shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                    <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest text-glow-cyan">REAL-TIME DATA STREAM</span>
                </div>
                <button 
                    onClick={downloadLogs} 
                    className="liquid-btn px-4 py-1.5 !text-[10px] rounded-lg border-white/20 text-slate-300 hover:text-white"
                >
                    EXPORT JSON
                </button>
            </div>

            {/* Log Stream */}
            <div className="flex-1 overflow-y-auto custom-scrollbar pb-24 scroll-smooth">
                {localLogs.slice().reverse().map(log => (
                    <LogItem key={log.id} log={log} />
                ))}
                {localLogs.length === 0 && (
                    <div className="flex flex-col items-center justify-center h-40 opacity-30 gap-3 mt-10 text-slate-500">
                        <Icons.Empty className="w-12 h-12 opacity-50" />
                        <span className="text-xs font-mono tracking-widest">AWAITING SIGNAL...</span>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './showcase/types';
import { DEFAULT_MATRIX_CONFIG } from './showcase/defaults';
import { useMatrixRain } from './showcase/useMatrixRain';
import { ShowcaseSettings } from './showcase/ShowcaseSettings';
import { Icons } from './icons';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [config, setConfig] = useState<MatrixConfig>(DEFAULT_MATRIX_CONFIG);
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [showSettings, setShowSettings] = useState(false);

    // Track window size for canvas init
    const [viewport, setViewport] = useState({ w: window.innerWidth, h: window.innerHeight });

    useEffect(() => {
        const handleResize = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Hook: Handles the Matrix Rain rendering on the transparent canvas
    useMatrixRain(canvasRef, config, viewport.w, viewport.h);

    // Helper: Determine UI Layout classes
    const getLayoutClasses = () => {
        switch (layout) {
            case 'CENTER': 
                return 'inset-0 flex-col justify-center items-center text-center p-4 md:p-8';
            case 'BOTTOM_CENTER': 
                return 'bottom-12 left-0 right-0 mx-auto w-full max-w-[calc(100vw-4rem)] md:max-w-5xl flex-col md:flex-row justify-between items-center';
            case 'BOTTOM_LEFT': 
                return 'bottom-10 left-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-start';
            case 'BOTTOM_RIGHT': 
                return 'bottom-10 right-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-end text-right';
            default: 
                return 'inset-0 justify-center items-center';
        }
    };

    const isCompact = layout !== 'CENTER';
    const isWideBar = layout === 'BOTTOM_CENTER';

    const getRgbaBg = (hex: string, alpha: number) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        const r = parseInt(result[1], 16);
        const g = parseInt(result[2], 16);
        const b = parseInt(result[3], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    };

    return (
        <div className="absolute inset-0 z-50 overflow-hidden pointer-events-none">

            {/* LAYER 1: Background Color Overlay */}
            <div 
                className="absolute inset-0 transition-colors duration-300"
                style={{ backgroundColor: getRgbaBg(config.bgColor, config.enabled ? config.bgOpacity : 0) }}
            ></div>

            {/* LAYER 2: Matrix Rain Canvas */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 block w-full h-full pointer-events-none mix-blend-screen"
            />

            {/* LAYER 3: CRT Scanline / Vignette Effects */}
            {config.enabled && config.bgOpacity > 0.1 && (
                <>
                    <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_90%)] pointer-events-none"></div>
                </>
            )}

            {/* LAYER 4: UI Content */}
            <div className={`absolute z-[55] flex animate-slide-up pointer-events-none transition-all duration-500 ${getLayoutClasses()}`}>

                {/* Main Liquid Card */}
                <div className={`liquid-card p-8 md:p-10 pointer-events-auto flex max-w-full ${isWideBar ? 'w-full flex-col md:flex-row items-center gap-8' : 'flex-col items-center gap-8 w-full'}`}>

                    {/* Content Text */}
                    <div className={`relative flex flex-col max-w-full ${isWideBar ? 'items-center md:items-start text-center md:text-left flex-1' : (layout.includes('RIGHT') ? 'items-end' : 'items-center')}`}>

                        {/* Header Badge */}
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-cyan-950/30 border border-cyan-500/30 text-[10px] text-cyan-400 font-mono tracking-widest mb-4 shadow-[0_0_10px_rgba(6,182,212,0.2)]">
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse box-shadow-[0_0_5px_cyan]"></span>
                            <span>SYSTEM_READY // V4.0.3</span>
                        </div>

                        <h1 className={`font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-100 to-cyan-500 font-mono tracking-tighter drop-shadow-[0_0_30px_rgba(6,182,212,0.5)] ${isCompact ? 'text-5xl' : 'text-7xl md:text-8xl'}`}>
                            TACTICAL.OS
                        </h1>

                        <div className="text-slate-400 font-mono text-xs tracking-[0.4em] uppercase mt-3 opacity-80 mix-blend-plus-lighter">
                            Neural Battle Simulation
                        </div>
                    </div>

                    {/* Start Button */}
                    <div className={`relative shrink-0 ${isCompact && !isWideBar ? 'w-full' : ''}`}>
                        <button 
                            onClick={onEnter}
                            className={`group liquid-btn-primary rounded-2xl overflow-hidden transition-all duration-300 ${isWideBar ? 'px-16 py-6 w-full md:w-auto text-xl' : 'w-full px-12 py-5 text-lg'} shadow-[0_0_30px_rgba(6,182,212,0.2)]`}
                        >
                            <span className="relative flex items-center justify-center gap-4 z-10">
                                <span>INITIALIZE</span>
                                <Icons.Play className="w-5 h-5 fill-current group-hover:translate-x-1 transition-transform" />
                            </span>
                        </button>
                    </div>
                </div>
            </div>

            {/* LAYER 5: Controls */}
            <div className="absolute top-6 left-6 z-[60] pointer-events-auto">
                <button 
                    onClick={() => setShowSettings(!showSettings)}
                    className={`liquid-icon-btn hover:text-cyan-400 hover:border-cyan-500/50 hover:bg-white/10 ${showSettings ? 'text-cyan-400 border-cyan-500/50 bg-white/10' : 'text-slate-400'}`}
                    title="特效設定"
                >
                    <Icons.Settings className={`w-5 h-5 ${showSettings ? 'animate-spin-slow' : ''}`} />
                </button>
            </div>

            <ShowcaseSettings 
                show={showSettings} 
                onClose={() => setShowSettings(false)}
                config={config} 
                setConfig={setConfig} 
                timeScale={timeScale}
                setTimeScale={setTimeScale}
                layout={layout}
                setLayout={setLayout}
            />
        </div>
    );
};

import React from 'react';
import GameCanvas from './components/GameCanvas';

// UI Components
import { ShowcaseOverlay } from './components/ui/ShowcaseOverlay';
import { PlaybackHUD } from './components/ui/PlaybackHUD';
import { MapEditorToolbar } from './components/ui/MapEditorToolbar';
import { UnitInspectorHUD } from './components/ui/UnitInspectorHUD';
import { SystemMenu } from './components/ui/SystemMenu';
import { ModalManager } from './components/ui/ModalManager';
import { Icons } from './components/ui/icons';

// Hook
import { useGameApp } from './hooks/useGameApp';

function App() {
  const { engineRef, state, setters, actions } = useGameApp();

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {state.showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="liquid-glass px-6 py-3 rounded-full border-red-500/50 flex items-center gap-3 shadow-xl text-red-200 bg-red-950/80">
                    <Icons.Warning className="w-6 h-6 text-red-400" />
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {state.isShowcaseMode && (
        <ShowcaseOverlay 
            onEnter={actions.enterManualMode} 
            timeScale={state.timeScale} 
            setTimeScale={setters.setTimeScale} 
        />
      )}

      {/* --- HUD LAYERS --- */}

      {/* 1. Playback Controls */}
      <PlaybackHUD 
          hidden={state.isShowcaseMode}
          isPlaying={state.isPlaying}
          winner={state.winner}
          timeScale={state.timeScale}
          onTogglePlay={actions.togglePlay}
          onRestart={actions.handleReset}
          onRandom={actions.handleRandomBattlefield} 
          onSetTimeScale={setters.setTimeScale}
          onShowcase={() => { setters.setIsShowcaseMode(true); actions.startShowcaseMatch(); }}
      />

      {/* 2. System Menu */}
      {!state.isShowcaseMode && (
          <SystemMenu 
              onToggleLogs={() => setters.setShowLogs(!state.showLogs)}
              onToggleDB={() => setters.setShowDB(!state.showDB)}
              onDownloadSpec={actions.downloadSpec}
          />
      )}

      {/* 3. Unit Inspector */}
      {!state.isShowcaseMode && state.selectedAgent && (
          <UnitInspectorHUD 
              agent={state.selectedAgent} 
              onClose={() => actions.handleSelectAgent(null)} 
              onExpand={() => setters.setShowUnitDetail(true)}
          />
      )}

      {/* 4. Modals (Logs / DB / Details) */}
      {!state.isShowcaseMode && (
          <ModalManager 
              showLogs={state.showLogs}
              showDB={state.showDB}
              showUnitDetail={state.showUnitDetail}
              selectedAgent={state.selectedAgent}
              engine={engineRef.current}
              onClose={() => {
                  setters.setShowLogs(false);
                  setters.setShowDB(false);
                  setters.setShowUnitDetail(false);
              }}
          />
      )}

      {/* MAIN GAME VIEW */}
      <div className="flex-1 relative z-0 bg-slate-900">
            <GameCanvas 
                engine={engineRef.current} 
                tool={state.tool}
                selectedObstacle={state.selectedObstacle}
                hpInput={state.hpInput}
                selectedAgent={state.selectedAgent}
                hoveredSkill={state.hoveredSkill}
                isShowcaseMode={state.isShowcaseMode}
                spawnMode={state.spawnMode}
                draftRole={state.draftRole}
                onSelect={actions.handleSelectAgent} 
                onWin={actions.onWin}
                winner={state.winner}
                rematch={actions.rematch}
                transitionPhase={state.transitionPhase}
            />
      </div>

      {/* 5. Map Editor Dock */}
      {!state.isShowcaseMode && (
          <MapEditorToolbar 
              tool={state.tool}
              setTool={setters.setTool}
              mapW={state.mapW} setMapW={(w) => actions.handleUpdateMapSize(w, state.mapH)}
              mapH={state.mapH} setMapH={(h) => actions.handleUpdateMapSize(state.mapW, h)}
              currentSceneId={state.currentSceneId}
              onSetScene={actions.handleSetScene}
              spawnMode={state.spawnMode} setSpawnMode={setters.setSpawnMode}
              draftRole={state.draftRole} setDraftRole={setters.setDraftRole}
              hpInput={state.hpInput} setHpInput={setters.setHpInput}
              selectedObstacle={state.selectedObstacle} setSelectedObstacle={setters.setSelectedObstacle}
          />
      )}
    </div>
  );
}

export default App;

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 36; 
        const isBlue = team === Team.BLUE;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); // Isometric projection

        // 1. Drop Shadow (Heavy grounding)
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.beginPath(); 
        ctx.arc(0, 8, radius + 2, 0, Math.PI*2); 
        ctx.fill();

        // 2. Physical Material Body
        if (isBlue) {
            // IMPERIAL: White Marble & Gold
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#f8fafc'); // White marble
            grad.addColorStop(1, '#94a3b8'); // Grey shading
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

            // Gold Rim (Solid metal)
            ctx.strokeStyle = '#d97706'; // Dark Gold border
            ctx.lineWidth = 6;
            ctx.stroke();
            ctx.strokeStyle = '#fbbf24'; // Bright Gold highlight
            ctx.lineWidth = 3;
            ctx.stroke();

            // Inner Tech Circuit (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.6, 0, Math.PI*2);
            ctx.fillStyle = '#1e3a8a'; // Dark Blue recessed area
            ctx.fill();
            ctx.strokeStyle = '#60a5fa'; // Glowing blue line
            ctx.lineWidth = 2;
            ctx.stroke();

        } else {
            // COVENANT: Dark Iron & Magma
            const grad = ctx.createLinearGradient(-radius, -radius, radius, radius);
            grad.addColorStop(0, '#27272a'); // Iron
            grad.addColorStop(1, '#000000'); 
            ctx.fillStyle = grad;

            // Jagged Shape base
            ctx.beginPath();
            const sides = 8;
            for(let i=0; i<=sides; i++) {
                const a = (i/sides) * Math.PI*2;
                const r = radius * (i%2===0 ? 1.0 : 0.9); // Gear/Spike shape
                const x = Math.cos(a)*r;
                const y = Math.sin(a)*r;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // Iron Rim
            ctx.strokeStyle = '#52525b';
            ctx.lineWidth = 4;
            ctx.stroke();

            // Inner Magma Core (The Projector)
            ctx.beginPath(); ctx.arc(0, 0, radius * 0.5, 0, Math.PI*2);
            ctx.fillStyle = '#450a0a'; // Dark Red
            ctx.fill();
            ctx.strokeStyle = '#ef4444'; // Glowing Red
            ctx.lineWidth = 2;
            ctx.stroke();
        }

        // 3. Projector Lens Flare (Center)
        // This suggests the unit is being projected FROM here
        ctx.fillStyle = isBlue ? '#fff' : '#fecaca';
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();

        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;

        // Emissive holographic text color
        const color = team === Team.BLUE ? '#e0f2fe' : '#fecaca';
        const shadowColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';

        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.shadowColor = shadowColor;
        ctx.shadowBlur = 10;
        ctx.lineWidth = 3;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.translate(cx, cy);

        // Scale down to fit nicely in 64x64
        const scale = 1.2;
        ctx.scale(scale, scale);

        // Vector Drawings instead of Emojis
        ctx.beginPath();
        if (role === Role.TANK) {
            // Shield Icon
            ctx.moveTo(0, 12);
            ctx.lineTo(9, 12);
            ctx.lineTo(12, -6);
            ctx.lineTo(0, -12);
            ctx.lineTo(-12, -6);
            ctx.lineTo(-9, 12);
            ctx.closePath();
            ctx.stroke();
            // Inner cross
            ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(0, 6); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-6, 0); ctx.lineTo(6, 0); ctx.stroke();

        } else if (role === Role.WARRIOR) {
            // Crossed Swords
            const drawSword = () => {
                ctx.moveTo(-8, -8); ctx.lineTo(8, 8); // Blade
                ctx.moveTo(-5, -8); ctx.lineTo(-8, -5); // Hilt Guard
                ctx.moveTo(5, 8); ctx.lineTo(8, 5); // Tip detail
            };
            ctx.save();
            ctx.beginPath();
            drawSword();
            ctx.stroke();
            ctx.scale(-1, 1); // Flip for X
            ctx.beginPath();
            drawSword();
            ctx.stroke();
            ctx.restore();

        } else if (role === Role.RANGER) {
            // Bow & Arrow
            ctx.beginPath();
            ctx.arc(0, 0, 12, -Math.PI/2, Math.PI/2); // Bow string
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(0, -14); ctx.lineTo(0, 14); // Bow Riser
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(14, 0); // Arrow
            ctx.lineTo(10, -4); ctx.moveTo(14, 0); ctx.lineTo(10, 4); // Arrow head
            ctx.stroke();

        } else if (role === Role.MAGE) {
            // Staff / Spark
            ctx.beginPath();
            ctx.moveTo(-10, 10); ctx.lineTo(10, -10); // Staff
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(10, -10, 5, 0, Math.PI*2); // Orb
            ctx.stroke();
            // Sparkles
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(14, -14, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(6, -6, 1.5, 0, Math.PI*2); ctx.fill();

        } else if (role === Role.SUPPORT) {
            // Cross / Ankh
            ctx.beginPath();
            ctx.moveTo(0, -12); ctx.lineTo(0, 12);
            ctx.moveTo(-8, -4); ctx.lineTo(8, -4);
            ctx.stroke();
            // Circle top
            ctx.beginPath(); ctx.arc(0, -8, 4, 0, Math.PI*2); ctx.stroke();
        }

        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);
        return canvas; 
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;

        ctx.beginPath();
        ctx.arc(cx, cy, 15, 0, Math.PI*2);
        ctx.arc(cx-10, cy-5, 10, 0, Math.PI*2);
        ctx.arc(cx+10, cy-5, 10, 0, Math.PI*2);
        ctx.fill();

        return canvas;
    }
};

import { createCanvas } from "./CanvasUtils";

const ICON_SIZE = 32;
const STATUS_SIZE = 48;

export const UIFactory = {

    generateSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);

        // Background Frame
        ctx.fillStyle = '#1e293b'; 
        ctx.fillRect(0, 0, ICON_SIZE, ICON_SIZE);

        ctx.strokeStyle = '#334155'; 
        ctx.strokeRect(0, 0, ICON_SIZE, ICON_SIZE);

        // Symbol drawing
        ctx.translate(ICON_SIZE / 2, ICON_SIZE / 2);
        ctx.fillStyle = color;
        ctx.strokeStyle = color;
        ctx.shadowColor = color; 
        ctx.shadowBlur = 5;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';

        ctx.beginPath();
        switch (visual) {
            case 'SLASH': 
                // Slash Arc
                ctx.arc(0, 0, 8, -Math.PI/2, 0);
                ctx.stroke();
                // Blade
                ctx.beginPath(); ctx.moveTo(-8, 8); ctx.lineTo(8, -8); ctx.stroke();
                break;
            case 'ARROW': 
                // Arrow
                ctx.moveTo(-6, 6); ctx.lineTo(6, -6);
                ctx.lineTo(2, -6); ctx.moveTo(6, -6); ctx.lineTo(6, -2);
                ctx.stroke();
                break;
            case 'FIREBALL': 
                // Flame
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.moveTo(0, -8); ctx.lineTo(0, -4);
                ctx.stroke();
                break;
            case 'BOLT': 
                // Lightning
                ctx.moveTo(2, -8); ctx.lineTo(-4, 0); ctx.lineTo(4, 0); ctx.lineTo(-2, 8);
                ctx.stroke();
                break;
            case 'BEAM': 
                // Laser
                ctx.moveTo(-8, -8); ctx.lineTo(8, 8);
                ctx.moveTo(8, -8); ctx.lineTo(-8, 8);
                ctx.stroke();
                ctx.beginPath(); ctx.arc(0,0,4,0,Math.PI*2); ctx.fill();
                break;
            case 'SMASH': 
                // Hammer
                ctx.rect(-6, -8, 12, 8);
                ctx.moveTo(0, 0); ctx.lineTo(0, 10);
                ctx.stroke();
                break;
            case 'BOMB': 
                // Bomb
                ctx.arc(0, 2, 6, 0, Math.PI*2);
                ctx.stroke();
                ctx.beginPath(); ctx.moveTo(4, -4); ctx.lineTo(8, -8); ctx.stroke();
                break;
            default:
                ctx.arc(0, 0, 6, 0, Math.PI*2);
                ctx.fill();
        }

        return canvas;
    },

    generateStatusIcon(type: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(STATUS_SIZE, STATUS_SIZE);
        const cx = STATUS_SIZE / 2;
        const cy = STATUS_SIZE / 2;

        ctx.translate(cx, cy);
        ctx.shadowBlur = 5;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (type) {
            case 'STUN':
                ctx.strokeStyle = '#facc15';
                ctx.shadowColor = '#facc15';
                // Spiral
                ctx.beginPath();
                for(let i=0; i<10; i++) {
                    const angle = i * 0.5;
                    const r = 2 + i * 1.5;
                    const x = Math.cos(angle) * r;
                    const y = Math.sin(angle) * r;
                    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
                }
                ctx.stroke();
                break;
            case 'SILENCE':
                ctx.strokeStyle = '#e2e8f0';
                ctx.shadowColor = '#94a3b8';
                // Chat bubble with dots
                ctx.strokeRect(-12, -10, 24, 16);
                ctx.beginPath();
                ctx.moveTo(-6, -2); ctx.lineTo(-6, -2);
                ctx.moveTo(0, -2); ctx.lineTo(0, -2);
                ctx.moveTo(6, -2); ctx.lineTo(6, -2);
                ctx.lineWidth = 4; // dots
                ctx.stroke();
                break;
            case 'POISON': // DoT
                ctx.strokeStyle = '#4ade80';
                ctx.shadowColor = '#22c55e';
                // Skull simple
                ctx.beginPath(); ctx.arc(0, -2, 10, 0, Math.PI*2); ctx.stroke();
                ctx.beginPath(); ctx.moveTo(-4, 10); ctx.lineTo(4, 10); ctx.stroke();
                break;
            case 'BURN': // DoT
                ctx.fillStyle = '#f87171';
                ctx.shadowColor = '#ef4444';
                // Flame
                ctx.beginPath();
                ctx.arc(0, 5, 8, 0, Math.PI*2);
                ctx.moveTo(0, -10); ctx.lineTo(-5, 0); ctx.lineTo(5, 0);
                ctx.fill();
                break;
            case 'REGEN': // HoT
                ctx.strokeStyle = '#86efac';
                ctx.shadowColor = '#4ade80';
                // Cross
                ctx.beginPath();
                ctx.moveTo(0, -10); ctx.lineTo(0, 10);
                ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
                ctx.stroke();
                break;
            case 'BANISH':
                ctx.strokeStyle = '#d8b4fe';
                ctx.shadowColor = '#c084fc';
                // Ghost shape
                ctx.beginPath();
                ctx.arc(0, -5, 10, Math.PI, 0);
                ctx.lineTo(10, 10);
                ctx.lineTo(5, 5); ctx.lineTo(0, 10);
                ctx.lineTo(-5, 5); ctx.lineTo(-10, 10);
                ctx.closePath();
                ctx.stroke();
                break;
            case 'POLYMORPH':
                ctx.strokeStyle = '#fbcfe8';
                ctx.shadowColor = '#f472b6';
                // Sheep curly
                ctx.beginPath();
                ctx.arc(0, 0, 10, 0, Math.PI*2);
                ctx.moveTo(-12, -5); ctx.arc(-8, -5, 4, 0, Math.PI*2);
                ctx.stroke();
                break;
            case 'STASIS':
                ctx.fillStyle = '#fef08a';
                ctx.shadowColor = '#facc15';
                // Shield solid
                ctx.beginPath();
                ctx.moveTo(-10, -10); ctx.lineTo(10, -10);
                ctx.lineTo(10, 0); ctx.lineTo(0, 12); ctx.lineTo(-10, 0);
                ctx.closePath();
                ctx.fill();
                break;
        }

        return canvas;
    }
};

