export const LogTab: React.FC<LogTabProps> = ({ engine }) => {
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);
    const endRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const interval = setInterval(() => {
            if (engine.logs.length !== localLogs.length) {
                setLocalLogs(engine.logs.slice(-100)); // Keep last 100
            }
        }, 200);
        return () => clearInterval(interval);
    }, [engine, localLogs.length]);

    // Auto-scroll to bottom on new logs (if near bottom)
    useEffect(() => {
        endRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [localLogs]);

    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Control Header */}
            <div className="flex justify-between items-center p-5 border-b border-white/5 shrink-0">
                <div className="flex items-center gap-3">
                    <div className="relative">
                        <span className="w-2 h-2 rounded-full bg-emerald-500 absolute animate-ping opacity-75"></span>
                        <span className="w-2 h-2 rounded-full bg-emerald-500 relative block shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                    </div>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Data Stream</span>
                </div>
                <button 
                    onClick={downloadLogs} 
                    className="liquid-btn px-3 py-1.5 !text-[10px] !rounded-lg border-white/10 text-slate-400 hover:text-white hover:border-cyan-500/30"
                >
                    <Icons.Save className="w-3 h-3 mr-1.5" /> EXPORT
                </button>
            </div>

            {/* Log Stream */}
            <div className="flex-1 overflow-y-auto custom-scrollbar px-4 py-4 space-y-1 relative">
                {localLogs.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-40 opacity-30 gap-4 mt-10">
                        <div className="w-16 h-16 rounded-full border-2 border-dashed border-slate-600 animate-spin-slow"></div>
                        <span className="text-xs font-mono tracking-widest text-slate-500">AWAITING INPUT...</span>
                    </div>
                ) : (
                    localLogs.map(log => <LogItem key={log.id} log={log} />)
                )}
                <div ref={endRef} />
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Role, Skill, Team } from '../../../types';
import { SKILL_FIELD_GROUPS, TAG_MAP, ROLE_MAP } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';

interface SkillDbTabProps {
    db: Skill[];
    onUpdate: () => void;
}

export const SkillDbTab: React.FC<SkillDbTabProps> = ({ db, onUpdate }) => {
    const [dbTypeTab, setDbTypeTab] = useState<'ALL' | 'BASIC' | 'ACTIVE' | 'ULT'>('ALL');
    const [dbRoleFilter, setDbRoleFilter] = useState<Role | 'ALL'>('ALL');
    const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);

    const filteredSkills = db.filter(s => {
        if (dbTypeTab !== 'ALL' && s.tag !== dbTypeTab) return false;
        if (dbRoleFilter !== 'ALL' && s.role !== dbRoleFilter) return false;
        return true;
    });

    const updateSkill = (field: keyof Skill, value: any) => {
        const skill = db.find(s => s.id === selectedSkillId);
        if (skill) { 
            if (field === 'team') {
                if (value === 'ANY') (skill as any)[field] = undefined;
                else if (value === 'BLUE') (skill as any)[field] = Team.BLUE;
                else if (value === 'RED') (skill as any)[field] = Team.RED;
            } else {
                (skill as any)[field] = value; 
            }
            onUpdate(); 
        }
    };

    return (
        <div className="flex flex-col h-full bg-transparent">
            {/* Header / Controls */}
            <div className="p-5 border-b border-white/5 shrink-0 space-y-4">
                <div className="flex justify-between items-end">
                    <div className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Neural Archive</div>
                    <div className="text-[10px] font-mono text-cyan-500/80 bg-cyan-950/30 px-2 py-1 rounded-md border border-cyan-500/20">
                        {filteredSkills.length} ENTRIES
                    </div>
                </div>

                <div className="flex flex-col gap-3">
                    {/* Type Tabs */}
                    <div className="flex bg-black/40 p-1 gap-1 rounded-xl border border-white/5">
                        {['ALL', 'BASIC', 'ACTIVE', 'ULT'].map(t => (
                            <button 
                                key={t}
                                onClick={() => setDbTypeTab(t as any)} 
                                className={`flex-1 py-2 text-[10px] rounded-lg font-bold transition-all uppercase tracking-wider ${dbTypeTab === t ? 'bg-cyan-500/20 text-cyan-300 shadow-[0_0_10px_rgba(6,182,212,0.1)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}
                            >
                                {t === 'ALL' ? 'ALL' : TAG_MAP[t].label}
                            </button>
                        ))}
                    </div>

                    {/* Role Select */}
                    <div className="relative group">
                        <select 
                            className="liquid-input w-full h-10 text-xs appearance-none cursor-pointer uppercase font-bold tracking-wider !bg-black/40 hover:!border-white/20 transition-colors"
                            value={dbRoleFilter}
                            onChange={(e) => setDbRoleFilter(e.target.value as any)}
                        >
                            <option value="ALL">FILTER CLASS: ALL</option>
                            {Object.values(Role).map(r => <option key={r} value={r}>FILTER: {ROLE_MAP[r].label}</option>)}
                        </select>
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[10px]">▼</div>
                    </div>
                </div>
            </div>

            {/* List Area */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 pb-24 space-y-3">
                {filteredSkills.map(skill => {
                    const isSelected = selectedSkillId === skill.id;
                    return (
                        <div 
                            key={skill.id} 
                            className={`liquid-card !rounded-2xl transition-all duration-300 overflow-hidden border ${isSelected ? 'border-cyan-500/40 bg-slate-900/80 shadow-[0_4px_20px_rgba(0,0,0,0.4)]' : 'border-white/5 bg-white/[0.02] hover:bg-white/[0.05] hover:border-white/10'}`}
                        >
                            <div 
                                className="flex items-center gap-4 p-3 cursor-pointer select-none"
                                onClick={() => setSelectedSkillId(isSelected ? null : skill.id)}
                            >
                                <SkillIcon skill={skill} className={`w-12 h-12 !rounded-xl border ${isSelected ? 'border-cyan-500/50' : 'border-white/10'}`} />
                                <div className="flex-1 min-w-0">
                                    <div className={`font-bold text-sm ${isSelected ? 'text-cyan-300' : 'text-slate-200'}`}>{skill.name}</div>
                                    <div className="flex gap-2 items-center mt-1.5">
                                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-wider bg-black/30 px-1.5 py-0.5 rounded-md border border-white/5">{ROLE_MAP[skill.role].label}</span>
                                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-md border bg-opacity-10 border-opacity-20 ${skill.tag === 'ULT' ? 'text-purple-300 bg-purple-500 border-purple-400' : (skill.tag === 'ACTIVE' ? 'text-blue-300 bg-blue-500 border-blue-400' : 'text-slate-400 bg-slate-500 border-slate-400')}`}>
                                            {TAG_MAP[skill.tag].label}
                                        </span>
                                    </div>
                                </div>
                                <div className={`w-6 h-6 rounded-full flex items-center justify-center bg-white/5 transition-transform duration-300 ${isSelected ? 'rotate-90 text-cyan-400 bg-cyan-900/30' : 'text-slate-600'}`}>
                                    ›
                                </div>
                            </div>

                            {/* Edit Form */}
                            {isSelected && (
                                <div className="p-4 bg-black/40 border-t border-white/5 space-y-6 animate-slide-down">
                                    {SKILL_FIELD_GROUPS.map((group) => (
                                        <div key={group.name} className="space-y-3">
                                            <div className="flex items-center gap-2 pb-1 border-b border-white/5">
                                                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{group.name}</span>
                                            </div>

                                            <div className="grid grid-cols-2 gap-4">
                                                {group.fields.map((field) => {
                                                    const val = (skill as any)[field.key];
                                                    let displayVal = val;

                                                    if (field.key === 'team') {
                                                        if (val === undefined) displayVal = 'ANY';
                                                        else if (val === Team.BLUE) displayVal = 'BLUE';
                                                        else if (val === Team.RED) displayVal = 'RED';
                                                    } else if (val === undefined || val === null) {
                                                        displayVal = '';
                                                    }

                                                    const isWide = field.type === 'textarea';

                                                    return (
                                                        <div key={field.key} className={isWide ? "col-span-2 space-y-1.5" : "space-y-1.5"}>
                                                            <label className="text-[9px] font-bold text-slate-400 block ml-1" title={field.label}>{field.label}</label>

                                                            {field.type === 'textarea' ? (
                                                                <textarea 
                                                                    className="liquid-input w-full p-3 h-24 resize-none !rounded-xl leading-relaxed !bg-black/50"
                                                                    value={displayVal}
                                                                    onChange={e => updateSkill(field.key, e.target.value)}
                                                                />
                                                            ) : field.type === 'select' ? (
                                                                <div className="relative">
                                                                    <select 
                                                                        className="liquid-input w-full h-9 text-xs appearance-none cursor-pointer !bg-black/50 !rounded-xl pr-8"
                                                                        value={displayVal}
                                                                        onChange={e => {
                                                                            const v = e.target.value;
                                                                            if (v === 'NONE' || v === 'ANY' || v === '') updateSkill(field.key, undefined);
                                                                            else updateSkill(field.key, v); 
                                                                        }}
                                                                    >
                                                                        {field.options ? 
                                                                            field.options.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>) :
                                                                            field.simpleOptions?.map(opt => <option key={opt} value={opt}>{opt}</option>)
                                                                        }
                                                                    </select>
                                                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[10px]">▼</div>
                                                                </div>
                                                            ) : field.type === 'color' ? (
                                                                <div className="flex gap-2 items-center">
                                                                    <div className="relative flex-1">
                                                                        <input 
                                                                            type="text" 
                                                                            className="liquid-input w-full h-9 text-xs font-mono !bg-black/50 !rounded-xl" 
                                                                            value={displayVal} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                    <div className="relative w-9 h-9 rounded-xl overflow-hidden border border-white/20 shadow-inner shrink-0">
                                                                        <input 
                                                                            type="color" 
                                                                            className="absolute -top-1/2 -left-1/2 w-[200%] h-[200%] cursor-pointer p-0 border-0" 
                                                                            value={displayVal.startsWith('#') ? displayVal : '#ffffff'} 
                                                                            onChange={e => updateSkill(field.key, e.target.value)} 
                                                                        />
                                                                    </div>
                                                                </div>
                                                            ) : (
                                                                <input 
                                                                    type={field.type} 
                                                                    className="liquid-input w-full h-9 text-xs font-mono !bg-black/50 !rounded-xl"
                                                                    value={displayVal}
                                                                    step={field.step || 1}
                                                                    onChange={e => updateSkill(field.key, field.type === 'number' ? parseFloat(e.target.value) : e.target.value)}
                                                                />
                                                            )}
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Agent } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    onClose: () => void;
    onExpand?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
    '待機': 'IDLE',
    '移動': 'MOVING',
    '詠唱 BASIC': 'CASTING',
    '詠唱 ACTIVE': 'CASTING',
    '詠唱 ULT': 'CASTING ULT',
    '暈眩': 'STUNNED',
    '放逐': 'BANISHED',
    '沉默': 'SILENCED',
    '死亡': 'KIA'
};

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, onClose, onExpand }) => {
    const [isMinimized, setIsMinimized] = useState(false);

    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 40
    });

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/50' : 'border-red-500/50';
    const glowClass = isBlue ? 'shadow-[0_0_30px_rgba(59,130,246,0.15)]' : 'shadow-[0_0_30px_rgba(239,68,68,0.15)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-6 h-6" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-6 h-6" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-6 h-6" />;
            case Role.MAGE: return <Icons.RoleMage className="w-6 h-6" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-6 h-6" />;
            default: return null;
        }
    };

    return (
        <div 
            ref={ref}
            className={`z-30 w-[calc(100%-2rem)] md:w-80 pointer-events-auto select-none transition-transform duration-200`}
            style={style}
            {...dragHandlers}
        >
            {isMinimized ? (
                // Minimized Pill
                <div 
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab ${isDragging ? 'cursor-grabbing' : ''} w-fit ml-auto border-l-4 ${borderColor}`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-6 h-6 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        <Icons.Expand className="w-4 h-4" />
                    </button>
                </div>
            ) : (
                // Full Card
                <div className={`liquid-card !rounded-3xl p-5 flex flex-col gap-4 ${glowClass} cursor-grab ${isDragging ? 'cursor-grabbing scale-[1.01]' : ''}`}>

                    {/* Header */}
                    <div className="flex justify-between items-start">
                        <div className="flex items-center gap-4 pointer-events-none">
                            {/* Class Icon Container (Liquid Style) */}
                            <div className={`w-14 h-14 flex items-center justify-center rounded-2xl liquid-card-dark border ${borderColor} ${themeColor} text-2xl shadow-inner relative overflow-hidden`}>
                                <div className={`absolute inset-0 opacity-20 bg-gradient-to-br from-white to-transparent`}></div>
                                {renderRoleIcon(agent.role)}
                            </div>
                            <div>
                                <div className={`font-mono font-black text-2xl ${themeColor} leading-none tracking-tight`}>{agent.id}</div>
                                <div className="flex items-center gap-2 mt-1.5">
                                    <span className="liquid-tag bg-white/5 border-white/10 text-slate-400 shadow-sm">{agent.role}</span>
                                    <span className={`liquid-tag ${isBlue ? 'bg-blue-500/10 border-blue-500/30 text-blue-300' : 'bg-red-500/10 border-red-500/30 text-red-300'} shadow-sm`}>LV.1</span>
                                </div>
                            </div>
                        </div>

                        {/* Controls */}
                        <div className="flex gap-1" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setIsMinimized(true)} className="liquid-icon-btn w-8 h-8 text-xs bg-transparent border-transparent hover:bg-white/10">
                                <Icons.Minimize className="w-4 h-4" />
                            </button>
                            {onExpand && (
                                <button onClick={onExpand} className="liquid-icon-btn w-8 h-8 text-xs bg-transparent border-transparent hover:bg-cyan-500/20 hover:text-cyan-400">
                                    <Icons.Expand className="w-4 h-4" />
                                </button>
                            )}
                            <button onClick={onClose} className="liquid-icon-btn w-8 h-8 text-xs bg-transparent border-transparent hover:bg-red-500/20 hover:text-red-400">
                                <Icons.Close className="w-4 h-4" />
                            </button>
                        </div>
                    </div>

                    <div className="h-px bg-white/5 w-full"></div>

                    {/* Vitals (Liquid Tube Style) */}
                    <div className="space-y-4 pointer-events-none">
                        {/* HP */}
                        <div className="relative group">
                            <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1.5 tracking-wider">
                                <span>INTEGRITY</span>
                                <span className={`font-mono ${agent.hp < agent.maxHp * 0.3 ? 'text-red-400 animate-pulse' : 'text-green-400'}`}>{Math.ceil(agent.hp)} / {agent.maxHp}</span>
                            </div>
                            <div className="h-3 bg-black/40 rounded-full p-0.5 border border-white/5 shadow-inner">
                                <div className="h-full rounded-full overflow-hidden relative w-full">
                                    <div 
                                        className="h-full bg-gradient-to-r from-green-800 via-green-500 to-green-400 transition-all duration-300 ease-out" 
                                        style={{width: `${Math.max(0, hpPct)}%`}}
                                    >
                                        <div className="absolute top-0 left-0 w-full h-[1px] bg-white/30"></div>
                                        <div className="absolute bottom-0 left-0 w-full h-[1px] bg-black/20"></div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        {/* MP */}
                        <div className="relative group">
                            <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-1.5 tracking-wider">
                                <span>ENERGY</span>
                                <span className="font-mono text-blue-400">{Math.floor(agent.mp)}%</span>
                            </div>
                            <div className="h-2.5 bg-black/40 rounded-full p-0.5 border border-white/5 shadow-inner">
                                <div className="h-full rounded-full overflow-hidden relative w-full">
                                    <div 
                                        className="h-full bg-gradient-to-r from-blue-800 via-blue-500 to-blue-400 transition-all duration-300 ease-out" 
                                        style={{width: `${mpPct}%`}}
                                    >
                                        <div className="absolute top-0 left-0 w-full h-[1px] bg-white/30"></div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* AI Monitor */}
                    <div className="flex justify-between items-center bg-black/30 rounded-2xl p-4 pointer-events-none border border-white/5">
                        <div className="flex flex-col gap-1">
                            <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">NEURAL STATE</span>
                            <span className={`text-sm font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300 text-glow-cyan'}`}>
                                {STATUS_LABELS[agent.btStatus] || agent.btStatus}
                            </span>
                        </div>
                        {/* Active Effects */}
                        <div className="flex gap-1.5">
                            {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300 shadow-[0_0_10px_rgba(245,158,11,0.3)]">STUN</span>}
                            {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300">SILENCE</span>}
                            {agent.banished && <span className="liquid-tag bg-purple-500/20 border-purple-500/50 text-purple-300 shadow-[0_0_10px_rgba(168,85,247,0.3)]">BANISH</span>}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

