    return (
        <div className="flex flex-col h-full w-full select-none">
            {/* UNIT HEADER (Liquid Glass) */}
            <div className="p-5 pb-6 shrink-0 z-20 flex items-center justify-between gap-4 bg-slate-900/40 backdrop-blur-md border-b border-white/5 shadow-lg">
                <div className="flex items-center gap-5">
                    <div className={`w-14 h-14 flex items-center justify-center rounded-2xl bg-black/40 border text-2xl shadow-inner relative overflow-hidden ${agent.team === 0 ? 'border-blue-500/50 text-blue-400' : 'border-red-500/50 text-red-400'}`}>
