import React from 'react';
import { BTNode } from '../../../engine/behaviorTree';
import { NodeState } from '../../../types';

interface TreeNodeProps {
    node: BTNode;
    version: number;
    now: number;
}

export const TreeNode: React.FC<TreeNodeProps> = ({ node, version, now }) => {
    // Logic for Visual Persistence
    const timeDiff = now - node.lastRunTime;
    let visualState: NodeState | null = node.status;
    let isFading = false;
    let opacity = 1.0;

    if (!visualState && node.lastResult) {
        if (timeDiff < 1000) { 
            visualState = node.lastResult;
            isFading = true;
            if (timeDiff > 200) opacity = 0.7;
            if (timeDiff > 500) opacity = 0.4;
        }
    }

    const statusStyle = (s: NodeState | null) => {
        switch (s) {
            case NodeState.RUNNING: return "border-amber-500/80 bg-amber-950/80 text-amber-100 shadow-[0_0_20px_rgba(245,158,11,0.4)] ring-1 ring-amber-400 animate-pulse-glow z-10 scale-105";
            case NodeState.SUCCESS: return "border-emerald-500/50 bg-emerald-950/60 text-emerald-100 shadow-[0_0_15px_rgba(16,185,129,0.2)]";
            case NodeState.FAILURE: return "border-red-800/50 bg-red-950/60 text-red-200 opacity-60";
            default: return "border-slate-700 bg-slate-800/80 text-slate-500 backdrop-blur-sm";
        }
    };

    const typeSymbol = (t: string) => {
        if(t === '?') return <span className="text-purple-400 font-bold mr-2 text-lg drop-shadow-md">?</span>;
        if(t === '->') return <span className="text-blue-400 font-bold mr-2 text-lg drop-shadow-md">➜</span>;
        if(t === 'COND') return <span className="text-pink-400 text-sm mr-2 font-bold">◆</span>;
        if(t === 'ACT') return <span className="text-yellow-400 text-sm mr-2 font-bold">⚡</span>;
        return null;
    }

    return (
        <div className="flex flex-col items-center">
            <div 
                className={`flex items-center px-5 py-3 rounded-2xl border transition-all duration-200 cursor-default select-none min-w-[140px] justify-center backdrop-blur-md ${statusStyle(visualState)}`}
                style={{ opacity: opacity }}
            >
                {typeSymbol(node.type)}
                <span className="whitespace-nowrap truncate max-w-[180px] font-bold text-xs tracking-wider font-mono">{node.n}</span>
            </div>
            {node.c && node.c.length > 0 && (
                <div className="flex flex-col items-center">
                    <div className={`w-px h-8 ${isFading ? 'bg-slate-600/30' : 'bg-slate-600/60'}`}></div>
                    <div className="flex items-start gap-4">
                        {node.c.map((child, idx) => (
                            <div key={child.id} className="flex flex-col items-center relative">
                                {/* Connector Lines */}
                                <div className="absolute top-0 left-0 w-full h-8 -mt-8 pointer-events-none">
                                     {node.c.length > 1 && (
                                         <>
                                            {idx === 0 && <div className="absolute right-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx === node.c.length - 1 && <div className="absolute left-0 top-0 w-1/2 h-px bg-slate-600/60 translate-y-8"></div>}
                                            {idx > 0 && idx < node.c.length - 1 && <div className="absolute left-0 top-0 w-full h-px bg-slate-600/60 translate-y-8"></div>}
                                         </>
                                     )}
                                     <div className="absolute left-1/2 top-0 w-px h-8 bg-slate-600/60 translate-y-8 -translate-x-1/2"></div>
                                </div>

                                <div className="pt-8">
                                    <TreeNode node={child} version={version} now={now} />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Agent } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    onClose: () => void;
    onExpand?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
    '待機': 'IDLE',
    '移動': 'MOVING',
    '詠唱 BASIC': 'CASTING',
    '詠唱 ACTIVE': 'CASTING',
    '詠唱 ULT': 'CASTING ULT',
    '暈眩': 'STUNNED',
    '放逐': 'BANISHED',
    '沉默': 'SILENCED',
    '死亡': 'KIA'
};

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, onClose, onExpand }) => {
    const [isMinimized, setIsMinimized] = useState(false);

    // The ref moves the outer container
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 40
    });

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/50' : 'border-red-500/50';
    const glowClass = isBlue ? 'shadow-[0_8px_32px_rgba(59,130,246,0.25)]' : 'shadow-[0_8px_32px_rgba(239,68,68,0.25)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-5 h-5" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-5 h-5" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-5 h-5" />;
            case Role.MAGE: return <Icons.RoleMage className="w-5 h-5" />;
