                                        <div className="flex justify-between items-center mb-1">
                                            <span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 rounded-md border ${tag === 'ULT' ? 'text-purple-300 border-purple-500/30 bg-purple-500/10' : (tag === 'ACTIVE' ? 'text-cyan-300 border-cyan-500/30 bg-cyan-500/10' : 'text-slate-300 border-slate-500/30 bg-slate-500/10')}`}>
                                                {TAG_MAP[tag].label}
