                                            <div className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[8px]">▼</div>
                                        </div>
                                    </div>
                                </div>

                                {currentSkill && (
                                    <div className="px-3 py-2 text-xs bg-black/20 border-t border-white/5">
                                        <div className="grid grid-cols-4 gap-1 text-[10px] font-mono text-slate-400">
                                            <div className="bg-black/30 rounded px-1 text-center border border-white/5"><span className="text-slate-500">PWR</span> <span className="text-slate-200">{currentSkill.power}</span></div>
                                            <div className="bg-black/30 rounded px-1 text-center border border-white/5"><span className="text-slate-500">CD</span> <span className="text-slate-200">{currentSkill.cd}s</span></div>
                                            <div className="bg-black/30 rounded px-1 text-center border border-white/5"><span className="text-slate-500">MP</span> <span className="text-blue-300">{currentSkill.cost}</span></div>
                                            <div className="bg-black/30 rounded px-1 text-center border border-white/5"><span className="text-slate-500">RNG</span> <span className="text-slate-200">{currentSkill.range}</span></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

import React, { useState, useRef } from 'react';
import { Agent } from '../../engine/game';
import { Team, Role } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';

interface UnitInspectorHUDProps {
    agent: Agent | null;
    onClose: () => void;
    onExpand?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
    '待機': 'IDLE',
    '移動': 'MOVING',
    '詠唱 BASIC': 'CASTING',
    '詠唱 ACTIVE': 'CASTING',
    '詠唱 ULT': 'CASTING ULT',
    '暈眩': 'STUNNED',
    '放逐': 'BANISHED',
    '沉默': 'SILENCED',
    '死亡': 'KIA'
};

export const UnitInspectorHUD: React.FC<UnitInspectorHUDProps> = ({ agent, onClose, onExpand }) => {
    const [isMinimized, setIsMinimized] = useState(false);

    // The ref moves the outer container
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'bottom-right',
        margin: 40
    });

    if (!agent) return null;

    const isBlue = agent.team === Team.BLUE;
    const themeColor = isBlue ? 'text-blue-400' : 'text-red-400';
    const borderColor = isBlue ? 'border-blue-500/50' : 'border-red-500/50';
    const glowClass = isBlue ? 'shadow-[0_8px_32px_rgba(59,130,246,0.25)]' : 'shadow-[0_8px_32px_rgba(239,68,68,0.25)]';

    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-5 h-5" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-5 h-5" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-5 h-5" />;
            case Role.MAGE: return <Icons.RoleMage className="w-5 h-5" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-5 h-5" />;
            default: return null;
        }
    };

    return (
        <div 
            ref={ref}
            className={`z-30 w-[calc(100%-2rem)] md:w-72 pointer-events-auto select-none transition-transform duration-75 ease-out`}
            style={style}
        >
            {isMinimized ? (
                // Minimized Pill (Fully Draggable)
                <div 
                    {...dragHandlers}
                    className={`liquid-card !rounded-full p-2 pl-3 flex items-center gap-3 cursor-grab active:cursor-grabbing w-fit ml-auto border-l-4 ${borderColor} ${glowClass}`}
                >
                    <div className={`w-2 h-2 rounded-full ${isBlue ? 'bg-blue-500 box-shadow-[0_0_10px_blue]' : 'bg-red-500 box-shadow-[0_0_10px_red]'} animate-pulse`}></div>
                    <span className="font-mono font-bold text-xs text-white tracking-widest">{agent.id}</span>
                    <button 
                        onClick={(e) => { e.stopPropagation(); setIsMinimized(false); }}
                        onPointerDown={e => e.stopPropagation()}
                        className="w-8 h-8 flex items-center justify-center rounded-full bg-white/5 hover:bg-white/20 text-slate-300 hover:text-white transition-all"
                    >
                        <Icons.Expand className="w-4 h-4" />
                    </button>
                </div>
            ) : (
                // Full Card
                <div className={`liquid-card !rounded-[24px] overflow-hidden flex flex-col ${glowClass} border border-white/10 backdrop-blur-3xl bg-slate-900/90`}>

                    {/* Header - DRAGGABLE HANDLE ONLY */}
                    <div 
                        {...dragHandlers}
                        className={`p-4 pb-3 bg-gradient-to-b from-white/5 to-transparent relative cursor-grab active:cursor-grabbing ${isDragging ? 'cursor-grabbing' : ''}`}
                    >
                        <div className="flex justify-between items-start mb-2 pointer-events-none">
                            <div className="flex items-center gap-3">
                                {/* Role Icon */}
                                <div className={`w-10 h-10 flex items-center justify-center rounded-xl bg-black/40 border ${borderColor} ${themeColor} shadow-inner`}>
                                    {renderRoleIcon(agent.role)}
                                </div>
                                <div className="flex flex-col">
                                    <div className={`font-mono font-black text-lg ${themeColor} leading-none tracking-tight drop-shadow-md`}>{agent.id}</div>
                                    <div className="flex items-center gap-1.5 mt-1">
                                        <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">{agent.role}</span>
                                        <span className={`text-[9px] font-bold px-1.5 rounded-md ${isBlue ? 'bg-blue-500/20 text-blue-300' : 'bg-red-500/20 text-red-300'}`}>LV.1</span>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Controls (Absolute positioning to overlay the draggable header but remain clickable) */}
                        <div className="absolute top-4 right-4 flex gap-1 pointer-events-auto" onPointerDown={e => e.stopPropagation()}>
                            <button onClick={() => setIsMinimized(true)} className="liquid-icon-btn w-6 h-6 text-[10px] bg-white/5 hover:bg-white/20 text-slate-400 hover:text-white border-transparent">
                                <Icons.Minimize className="w-3 h-3" />
                            </button>
                            {onExpand && (
                                <button onClick={onExpand} className="liquid-icon-btn w-6 h-6 text-[10px] bg-cyan-500/10 hover:bg-cyan-500/30 text-cyan-400 border-transparent">
                                    <Icons.Expand className="w-3 h-3" />
                                </button>
                            )}
                            <button onClick={onClose} className="liquid-icon-btn w-6 h-6 text-[10px] bg-red-500/10 hover:bg-red-500/30 text-red-400 border-transparent">
                                <Icons.Close className="w-3 h-3" />
                            </button>
                        </div>

                        {/* Integrated Slim Bars (Non-interactive) */}
                        <div className="space-y-1 mt-1 pointer-events-none">
                            {/* HP */}
                            <div className="h-1.5 bg-black/50 rounded-full overflow-hidden w-full flex">
                                <div 
                                    className="h-full bg-gradient-to-r from-emerald-600 to-emerald-400 transition-all duration-300" 
                                    style={{width: `${Math.max(0, hpPct)}%`}}
                                ></div>
                            </div>
                            {/* MP */}
                            {agent.maxMp > 0 && (
                                <div className="h-1 bg-black/50 rounded-full overflow-hidden w-full flex">
                                    <div 
                                        className="h-full bg-gradient-to-r from-blue-700 to-cyan-400 transition-all duration-300" 
                                        style={{width: `${mpPct}%`}}
                                    ></div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Compact Body: Status Only - NOT DRAGGABLE */}
                    <div className="px-4 pb-4 pt-0 cursor-default" onPointerDown={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center bg-black/20 rounded-xl p-3 border border-white/5">
                            <div className="flex flex-col">
                                <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-0.5">STATE</span>
                                <span className={`text-xs font-mono font-bold ${agent.hp <= 0 ? 'text-slate-600' : 'text-cyan-300 text-glow-cyan'}`}>
                                    {STATUS_LABELS[agent.btStatus] || agent.btStatus}
                                </span>
                            </div>
                            {/* Active Effects */}
                            <div className="flex gap-1">
                                {agent.stunTimer > 0 && <span className="liquid-tag bg-amber-500/20 border-amber-500/50 text-amber-300 text-[9px] px-1.5">STUN</span>}
                                {agent.silenceTimer > 0 && <span className="liquid-tag bg-slate-700/50 border-slate-500 text-slate-300 text-[9px] px-1.5">SILENCE</span>}
                                {agent.banished && <span className="liquid-tag bg-purple-500/20 border-purple-500/50 text-purple-300 text-[9px] px-1.5">BANISH</span>}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../engine/game';
import { Role, Skill, Team } from '../../types';
import { UnitStatusTab } from '../inspector/tabs/UnitStatusTab';
import { BehaviorTreeTab } from '../inspector/tabs/BehaviorTreeTab';
import { Icons } from './icons';
import { ROLE_MAP, Helpers } from '../inspector/InspectorConstants';

interface UnitDetailViewProps {
    agent: Agent;
    db: Skill[];
    engine: GameEngine;
}

export const UnitDetailView: React.FC<UnitDetailViewProps> = ({ agent, db, engine }) => {
    const [subTab, setSubTab] = useState<'STATUS' | 'AI'>('STATUS');
    const [version, setVersion] = useState(0); 
    const [isConfigExpanded, setIsConfigExpanded] = useState(false);

    // Refresh Loop for visual updates (Health, AI Nodes)
    useEffect(() => {
        const interval = setInterval(() => setVersion(n => n + 1), 100); // 10 FPS is enough for UI
        return () => clearInterval(interval);
    }, []);

    const handleUpdate = () => {
        setVersion(n => n + 1);
    };

    const setRole = (r: string) => { 
        agent.role = r as Role; 
        handleUpdate(); 
    };

    const renderRoleIcon = (role: Role) => {
        switch (role) {
            case Role.TANK: return <Icons.RoleTank className="w-6 h-6" />;
            case Role.WARRIOR: return <Icons.RoleWarrior className="w-6 h-6" />;
            case Role.RANGER: return <Icons.RoleRanger className="w-6 h-6" />;
            case Role.MAGE: return <Icons.RoleMage className="w-6 h-6" />;
            case Role.SUPPORT: return <Icons.RoleSupport className="w-6 h-6" />;
            default: return null;
        }
    };

    const roleConfig = Helpers.getRoleConfig(agent.role);
    const hpPct = (agent.hp / agent.maxHp) * 100;
    const mpPct = (agent.mp / agent.maxMp) * 100;

    return (
        <div className="flex flex-col h-full w-full select-none overflow-hidden">

            {/* 1. IDENTITY QUADRANT (Interactive Header) */}
            <div className="shrink-0 z-20 p-5 pb-2 bg-gradient-to-b from-slate-900 via-slate-900/95 to-slate-900/80 backdrop-blur-md border-b border-white/5 shadow-lg">
                <div 
                    onClick={() => setIsConfigExpanded(!isConfigExpanded)}
                    className={`liquid-card-dark relative border transition-all duration-300 overflow-hidden cursor-pointer group ${isConfigExpanded ? 'border-cyan-500/50 bg-slate-800/80' : 'border-white/5 hover:border-cyan-500/30 hover:bg-white/[0.05]'}`}
                >
                    {/* Breathing Hint */}
                    <div className="absolute top-3 right-3 flex items-center gap-2">
                        <span className={`text-[9px] font-mono tracking-widest transition-opacity uppercase ${isConfigExpanded ? 'text-cyan-400 opacity-100' : 'text-slate-500 opacity-0 group-hover:opacity-100'}`}>
                            {isConfigExpanded ? 'CLOSE CONFIG' : 'EDIT CONFIG'}
                        </span>
                        <div className={`w-2 h-2 rounded-full transition-all ${isConfigExpanded ? 'bg-cyan-400 shadow-[0_0_8px_cyan]' : 'bg-slate-600 group-hover:bg-cyan-500/50 group-hover:animate-pulse'}`}></div>
                    </div>

                    <div className="p-4 space-y-4">
                        {/* Top Row: Identity */}
                        <div className="flex items-center gap-4">
                            {/* Role Icon */}
                            <div className={`w-12 h-12 flex items-center justify-center rounded-xl bg-black/40 border-2 ${roleConfig.border} ${roleConfig.color} shadow-lg shrink-0`}>
                                {renderRoleIcon(agent.role)}
                            </div>

                            <div className="flex-1 min-w-0">
                                <div className="flex items-baseline gap-2">
                                    <h3 className="text-2xl font-black text-white font-mono tracking-tight truncate">{agent.id}</h3>
                                    <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-white/10 text-slate-300 border border-white/5">LV.1</span>
                                </div>
                                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5 flex items-center gap-2">
                                    <span className={roleConfig.color}>{ROLE_MAP[agent.role].label}</span>
                                    <span>•</span>
                                    <span className={agent.team === Team.BLUE ? 'text-blue-400' : 'text-red-400'}>{agent.team === Team.BLUE ? 'ALLIANCE' : 'HORDE'}</span>
                                </div>
                            </div>
                        </div>

                        {/* Middle Row: Vitals (Bars) */}
                        <div className="space-y-2">
                            {/* HP */}
                            <div className="space-y-1">
                                <div className="flex justify-between text-[9px] font-bold text-slate-400 uppercase tracking-wider">
                                    <span>Integrity</span>
                                    <span className="text-green-400 font-mono">{Math.round(agent.hp)} / {agent.maxHp}</span>
                                </div>
                                <div className="h-1.5 bg-black/50 rounded-full overflow-hidden border border-white/5">
                                    <div className="h-full bg-green-500 transition-all duration-300 shadow-[0_0_10px_rgba(34,197,94,0.3)]" style={{width: `${hpPct}%`}}></div>
                                </div>
                            </div>
                            {/* MP */}
                            <div className="space-y-1">
                                <div className="flex justify-between text-[9px] font-bold text-slate-400 uppercase tracking-wider">
                                    <span>Energy</span>
                                    <span className="text-blue-400 font-mono">{Math.floor(agent.mp)} / {agent.maxMp}</span>
                                </div>
                                <div className="h-1.5 bg-black/50 rounded-full overflow-hidden border border-white/5">
                                    <div className="h-full bg-blue-500 transition-all duration-300 shadow-[0_0_10px_rgba(59,130,246,0.3)]" style={{width: `${mpPct}%`}}></div>
                                </div>
                            </div>
                        </div>

                        {/* Bottom Row: Editor Controls (Collapsed by default) */}
                        {isConfigExpanded && (
                            <div className="pt-4 border-t border-white/10 grid grid-cols-2 gap-3 animate-slide-down" onClick={e => e.stopPropagation()}>
                                <div className="col-span-2">
                                    <label className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mb-1 block">Role Class</label>
                                    <select 
                                        className="liquid-input h-9 w-full text-xs font-bold bg-black/50 !rounded-lg"
                                        value={agent.role} 
                                        onChange={(e) => setRole(e.target.value)}
                                    >
                                        {Object.values(Role).map(r => <option key={r} value={r}>{ROLE_MAP[r].label}</option>)}
                                    </select>
                                </div>
                                <div>
                                    <label className="text-[9px] font-bold text-green-500/70 uppercase tracking-widest mb-1 block">Max HP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-9 w-full text-center text-green-400 font-mono font-bold text-sm !bg-black/50 !rounded-lg"
                                        value={Math.round(agent.maxHp)} 
                                        onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; handleUpdate(); }} 
                                    />
                                </div>
                                <div>
                                    <label className="text-[9px] font-bold text-blue-500/70 uppercase tracking-widest mb-1 block">Max MP</label>
                                    <input 
                                        type="number" 
                                        className="liquid-input h-9 w-full text-center text-blue-400 font-mono font-bold text-sm !bg-black/50 !rounded-lg"
                                        value={Math.round(agent.maxMp)} 
                                        onChange={(e) => { agent.maxMp = parseInt(e.target.value); handleUpdate(); }} 
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Tab Switcher (Integrated into Header Block) */}
                <div className="flex bg-black/30 p-1 gap-1 rounded-full border border-white/5 backdrop-blur-sm mt-3 mx-auto w-fit">
                    <button onClick={() => setSubTab('STATUS')} className={`px-8 py-2 text-[10px] rounded-full font-bold transition-all uppercase tracking-wider ${subTab === 'STATUS' ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30 shadow-[0_0_15px_rgba(6,182,212,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5 border border-transparent'}`}>LINKAGE</button>
                    <button onClick={() => setSubTab('AI')} className={`px-8 py-2 text-[10px] rounded-full font-bold transition-all uppercase tracking-wider ${subTab === 'AI' ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30 shadow-[0_0_15px_rgba(245,158,11,0.2)]' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5 border border-transparent'}`}>BEHAVIOR</button>
                </div>
            </div>

            {/* CONTENT AREA */}
            <div className="flex-1 overflow-hidden relative min-h-0 bg-slate-900/50">
                {subTab === 'STATUS' ? (
                    <UnitStatusTab 
                        agent={agent} 
                        db={db} 
                        onHoverSkill={() => {}} 
                        onUpdate={handleUpdate}
                    />
                ) : (
                    <BehaviorTreeTab 
                        agent={agent} 
                        version={version}
                        engine={engine} 
                    />
                )}
            </div>
        </div>
    );
};

import React from 'react';
import { Agent } from '../../../engine/game';
import { Role, Skill, Team } from '../../../types';
import { ROLE_MAP, TAG_MAP } from '../InspectorConstants';
import { SkillIcon } from '../parts/SkillIcon';
import { Icons } from '../../ui/icons';

interface UnitStatusTabProps {
    agent: Agent;
    db: Skill[];
    onHoverSkill?: (skill: Skill | null) => void;
    onUpdate: () => void;
}

export const UnitStatusTab: React.FC<UnitStatusTabProps> = ({ agent, db, onHoverSkill, onUpdate }) => {

    const setSkill = (idx: number, id: string) => {
        agent.skillIds[idx] = id || null; 
        onUpdate();
    };

    return (
        <div className="flex flex-col h-full bg-transparent overflow-hidden">

            {/* SKILL SLOTS (Scrollable Area) */}
            <div className="flex-1 overflow-y-auto custom-scrollbar min-h-0 px-5 py-4 pb-24">
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] flex items-center gap-2 mb-4 sticky top-0 bg-slate-900/95 py-2 z-10 border-b border-white/5 backdrop-blur-md">
                    <Icons.Database className="w-3 h-3" />
                    NEURAL LINKAGE
                </div>

                <div className="space-y-4">
                    {['ULT', 'ACTIVE', 'BASIC'].map((tag, i) => {
                        const currentSkillId = agent.skillIds[i];
                        const currentSkill = db.find(s => s.id === currentSkillId);

                        const availableSkills = db.filter(s => s.tag === tag);
                        const skillsByRole: Record<string, Skill[]> = {};
                        availableSkills.forEach(s => {
                            if(!skillsByRole[s.role]) skillsByRole[s.role] = [];
                            skillsByRole[s.role].push(s);
                        });
                        const roleOrder = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

                        return (
                            <div key={i} className="liquid-card !bg-slate-900/40 border border-white/5 transition-all hover:border-white/20 group !rounded-2xl overflow-hidden" onMouseEnter={() => onHoverSkill && onHoverSkill(currentSkill || null)} onMouseLeave={() => onHoverSkill && onHoverSkill(null)}>
                                <div className="flex items-center gap-4 p-4 bg-white/[0.02]">
                                    <SkillIcon skill={currentSkill || null} className="w-12 h-12 !rounded-xl shadow-lg shrink-0" />
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-center mb-1.5">
                                            <span className={`text-[9px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-md border ${tag === 'ULT' ? 'text-purple-300 border-purple-500/30 bg-purple-500/10' : (tag === 'ACTIVE' ? 'text-cyan-300 border-cyan-500/30 bg-cyan-500/10' : 'text-slate-300 border-slate-500/30 bg-slate-500/10')}`}>
                                                {TAG_MAP[tag].label} SLOT
                                            </span>
                                            {currentSkill && <span className="text-[9px] text-slate-600 font-mono">{currentSkill.id}</span>}
                                        </div>
                                        <div className="relative">
                                            <select 
                                                className={`liquid-input h-10 w-full text-xs font-bold appearance-none cursor-pointer uppercase tracking-wide !rounded-lg pr-8 ${!currentSkillId ? 'text-slate-500 !bg-black/30' : 'text-slate-200 !bg-black/50 hover:!bg-black/70'}`}
                                                value={agent.skillIds[i] || ""} 
                                                onChange={(e) => setSkill(i, e.target.value)}
                                            >
                                                <option value="">-- NO LINKAGE --</option>
                                                {roleOrder.map(role => {
                                                    const skills = skillsByRole[role];
                                                    if (!skills || skills.length === 0) return null;
                                                    return (
                                                        <optgroup key={role} label={ROLE_MAP[role].label} className="bg-slate-900 text-slate-400">
                                                            {skills.map(s => (
                                                                <option key={s.id} value={s.id} className="text-white">
                                                                    {s.name} {s.team !== undefined ? (s.team === Team.BLUE ? '🔵' : '🔴') : ''}
                                                                </option>
                                                            ))}
                                                        </optgroup>
                                                    );
                                                })}
                                            </select>
                                            <div className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none text-[8px]">▼</div>
                                        </div>
                                    </div>
                                </div>

                                {currentSkill && (
                                    <div className="px-4 py-3 text-xs bg-black/20 border-t border-white/5">
                                        <div className="text-slate-400 italic mb-3 leading-relaxed border-l-2 border-white/10 pl-3">
                                            {currentSkill.desc}
                                        </div>
                                        <div className="grid grid-cols-4 gap-2 text-[10px] font-mono text-slate-400">
                                            <div className="bg-black/30 rounded px-2 py-1 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">POWER</span> <span className="text-slate-200 text-xs">{currentSkill.power}</span></div>
                                            <div className="bg-black/30 rounded px-2 py-1 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">COOLDOWN</span> <span className="text-slate-200 text-xs">{currentSkill.cd}s</span></div>
                                            <div className="bg-black/30 rounded px-2 py-1 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">COST</span> <span className="text-blue-300 text-xs">{currentSkill.cost}</span></div>
                                            <div className="bg-black/30 rounded px-2 py-1 text-center border border-white/5"><span className="text-slate-500 block text-[8px] uppercase">RANGE</span> <span className="text-slate-200 text-xs">{currentSkill.range}</span></div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
