export const Helpers = {
    getRoleConfig: (role: Role) => ROLE_MAP[role] || { label: role, color: 'text-slate-400', border: 'border-slate-500' },

    getTeamConfig: (team: Team) => TEAM_MAP[team] || { label: 'Unknown', color: 'text-slate-400', bg: 'bg-slate-800' },

    getTagLabel: (tag: string) => TAG_MAP[tag]?.label || tag,

    getCCColor: (type?: string) => CC_TYPES.find(c => c.value === type)?.color || '#fff',

    getEffectLabel: (type?: string) => EFFECT_TYPES.find(e => e.value === type)?.label || type,

    getStatusLabel: (status: string) => {
        // Mapping raw strings from game engine to friendly UI labels
        if(status === '待機') return 'IDLE';
        if(status === '移動') return 'MOVING';
        if(status === '暈眩') return 'STUNNED';
        if(status === '放逐') return 'BANISHED';
        if(status === '沉默') return 'SILENCED';
        if(status === '死亡') return 'KIA';
        if(status.startsWith('詠唱')) return 'CASTING';
        return status;
    }
};

import * as PIXI from 'pixi.js';
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team } from "../../types";
import { TerrainRenderer } from "../renderers/grid/TerrainRenderer";
import { createCanvas } from "./CanvasUtils";
import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";

// Cache storage
const textureCache: Map<string, PIXI.Texture> = new Map();

export const TextureManager = {

    getUnitTexture(role: Role, team: Team, part: 'base' | 'weapon' | 'icon'): PIXI.Texture {
        const key = `UNIT_${role}_${team}_${part}`;
        if (textureCache.has(key)) return textureCache.get(key)!;

        const assets = SpriteManager.getUnitImages(role, team);
        // Convert HTMLCanvasElement to PIXI.Texture
        const texture = PIXI.Texture.from(assets[part]);
        textureCache.set(key, texture);
        return texture;
    },

    getObstacleTexture(type: string): PIXI.Texture {
        const key = `OBS_${type}`;
        if (textureCache.has(key)) return textureCache.get(key)!;

        const canvas = SpriteManager.getObstacleSprite(type);
        const texture = PIXI.Texture.from(canvas);
        textureCache.set(key, texture);
        return texture;
    },

    getVFXTexture(type: string, color: string): PIXI.Texture {
        const key = `VFX_${type}_${color}`;
        if (textureCache.has(key)) return textureCache.get(key)!;

        let canvas: HTMLCanvasElement;
        if (type === 'PROJECTILE') {
            // Default to BOLT if visual not specified, specific visuals handled by getProjectile
            canvas = AssetManager.getProjectile('BOLT', color); 
        } else if (type === 'BLAST') {
            canvas = AssetManager.getBlastZone(color);
        } else if (type === 'GLOW') {
            canvas = AssetManager.getGlowSprite(color);
        } else if (type === 'FOG') {
            canvas = AssetManager.getFogCloud(color);
        } else {
            // Generic fallback
            canvas = AssetManager.getVFX(type, color);
        }

        const texture = PIXI.Texture.from(canvas);
        textureCache.set(key, texture);
        return texture;
    },

    // Procedural Terrain Texture Generation
    // We generate a "Block" texture for each theme to allow batching
    getTerrainBlockTexture(themeKey: string, height: number): PIXI.Texture {
        const key = `TERRAIN_${themeKey}_H${height}`;
        if (textureCache.has(key)) return textureCache.get(key)!;

        const theme = TERRAIN_THEMES[themeKey] || TERRAIN_THEMES['VOID'];

        // Dimensions: Hex Width + Height + Block Height
        const w = HEX_SIZE * 2;
        const h = HEX_SIZE * 2 + height + 20;
        const { canvas, ctx } = createCanvas(w, h);

        // Center drawing
        ctx.translate(w/2, h - (HEX_SIZE * 0.6) - 10);

        TerrainRenderer.drawBlockGeometry(ctx, 0, 0, HEX_SIZE, height, theme);

        const texture = PIXI.Texture.from(canvas);
        textureCache.set(key, texture);
        return texture;
    },

    getPrerenderedTexture(key: string, drawFn: (ctx: CanvasRenderingContext2D) => void, w: number = 64, h: number = 64): PIXI.Texture {
        if (textureCache.has(key)) return textureCache.get(key)!;
        const { canvas, ctx } = createCanvas(w, h);
        drawFn(ctx);
        const t = PIXI.Texture.from(canvas);
        textureCache.set(key, t);
        return t;
    }
};

import * as PIXI from 'pixi.js';
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Camera } from "../systems/CameraSystem";
import { Hex, Skill } from "../../types";
import { TextureManager } from "../graphics/TextureManager";
import { HEX_SIZE, UNIT_VISUAL_HEIGHT, UNIT_BODY_OFFSET } from "../../constants";
import { AssetManager } from "../assets";

// Types
interface PixiUnitContainer extends PIXI.Container {
    agentId: string;
    bodySprite: PIXI.Sprite;
    shadowSprite: PIXI.Graphics;
    hpBar: PIXI.Graphics;
}

export class PixiRenderer {
    public app: PIXI.Application;

    // Layers
    private worldContainer: PIXI.Container; // Affected by Camera
    private backgroundLayer: PIXI.Container;
    private terrainLayer: PIXI.Container;
    private decalLayer: PIXI.Container; // Ground effects
    private objectLayer: PIXI.Container; // Units & Obstacles sorted by Y
    private vfxLayer: PIXI.Container; // Floating particles
    private hudLayer: PIXI.Container; // Screen space

    // State Sync
    private unitMap: Map<string, PixiUnitContainer> = new Map();
    private particlePool: PIXI.Sprite[] = [];
    private activeParticles: PIXI.Sprite[] = [];

    // Config
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(canvas: HTMLCanvasElement, width: number, height: number) {
        this.app = new PIXI.Application({
            view: canvas,
            width: width,
            height: height,
            backgroundColor: 0x000000,
            antialias: true,
            resolution: window.devicePixelRatio || 1,
            autoDensity: true
        });

        // Setup Layers
        this.worldContainer = new PIXI.Container();
        this.worldContainer.sortableChildren = true;

        this.backgroundLayer = new PIXI.Container();
        this.terrainLayer = new PIXI.Container();
        this.decalLayer = new PIXI.Container();
        this.objectLayer = new PIXI.Container();
        this.objectLayer.sortableChildren = true; // Y-Sort enabled
        this.vfxLayer = new PIXI.Container();
        this.hudLayer = new PIXI.Container(); // Screen space

        this.app.stage.addChild(this.backgroundLayer);
        this.app.stage.addChild(this.worldContainer);
        this.app.stage.addChild(this.hudLayer);

        this.worldContainer.addChild(this.terrainLayer);
        this.worldContainer.addChild(this.decalLayer);
        this.worldContainer.addChild(this.objectLayer);
        this.worldContainer.addChild(this.vfxLayer);
    }

    public resize(w: number, h: number) {
        this.app.renderer.resize(w, h);
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public destroy() {
        this.app.destroy(false, true); // Don't destroy canvas
    }

    // --- MAIN RENDER LOOP ---

    public render(
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number,
        hoveredHex: Hex | null
    ) {
        // 1. Sync Camera
        this.syncCamera(camera, engine);

        // 2. Sync Background (Simple color for now, can use TilingSprite later)
        const bgHex = parseInt(engine.currentScene.background.replace('#', '0x'));
        this.app.renderer.background.color = bgHex;

        // 3. Sync Grid/Terrain
        this.syncTerrain(engine);

        // 4. Sync Units (Create/Update/Remove)
        this.syncUnits(engine, highlight);

        // 5. Sync Projectiles & VFX
        this.syncVFX(engine);

        // 6. Sync Obstacles
        this.syncObstacles(engine);
    }

    // --- SYNC METHODS ---

    private syncCamera(camera: Camera, engine: GameEngine) {
        // Apply Trauma Shake from Engine's CameraSystem (accessed via global renderer logic if needed, 
        // but here we just take the raw camera pos passed in).
        // If we want shake, we should pass the shaken camera coords.
        const cx = this.app.screen.width / 2;
        const cy = this.app.screen.height / 2;

        this.worldContainer.position.set(cx, cy);
        this.worldContainer.scale.set(camera.zoom);
        this.worldContainer.pivot.set(camera.x, camera.y);
    }

    private syncTerrain(engine: GameEngine) {
        // Optimization: Only rebuild if map version changes
        // For dynamic height transitions, we might need to update y positions

        // This is a simplified "Immediate Mode" style for the grid to handle the transition animation
        // In a real optimized scenario, we would cache this container.
        this.terrainLayer.removeChildren();

        const scene = engine.currentScene;
        const keys = Array.from(engine.mapKeys); // e.g. "0,0"

        keys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Animation
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);
            const drawY = pos.y + offset;

            // Cull off-screen
            if (drawY > pos.y + 1000) return;

            // Get Texture
            const texture = TextureManager.getTerrainBlockTexture(scene.textureType, h);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0); // Bottom center
            sprite.position.set(pos.x, drawY);

            // Tint if hovered
            // Note: Mouse interaction in Pixi needs mapping. For now relying on React state passed down.
            // (hoveredHex logic would be applied here)

            this.terrainLayer.addChild(sprite);
        });
    }

    private syncUnits(engine: GameEngine, highlight: Agent | null) {
        const aliveIds = new Set<string>();

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            aliveIds.add(agent.id);

            let container = this.unitMap.get(agent.id);
            if (!container) {
                container = this.createUnitContainer(agent);
                this.unitMap.set(agent.id, container);
                this.objectLayer.addChild(container);
            }

            // Update Position & Z-Index
            const h = engine.map.getTerrainHeight(agent.q, agent.r);
            // Physics interpolation handled in Agent class, we just read px/py
            const visualY = agent.py - h; 

            container.position.set(agent.px, visualY);
            container.zIndex = agent.py; // Sort by ground Y

            // Update Body Visuals (Scale/Rotation based on anim)
            this.updateUnitVisuals(container, agent, engine.battleTime, highlight === agent);
        });

        // Cleanup dead units
        for (const [id, container] of this.unitMap) {
            if (!aliveIds.has(id)) {
                this.objectLayer.removeChild(container);
                container.destroy({ children: true });
                this.unitMap.delete(id);
            }
        }
    }

    private createUnitContainer(agent: Agent): PixiUnitContainer {
        const container = new PIXI.Container() as PixiUnitContainer;
        container.agentId = agent.id;

        // Shadow
        const shadow = new PIXI.Graphics();
        shadow.beginFill(0x000000, 0.4);
        shadow.drawEllipse(0, 0, 15, 8);
        shadow.endFill();
        container.addChild(shadow);
        container.shadowSprite = shadow;

        // Body Sprite (Base)
        const texture = TextureManager.getUnitTexture(agent.role, agent.team, 'base');
        const sprite = new PIXI.Sprite(texture);
        sprite.anchor.set(0.5, 0.7); // Anchor near bottom
        container.addChild(sprite);
        container.bodySprite = sprite;

        // HP Bar
        const bar = new PIXI.Graphics();
        container.addChild(bar);
        container.hpBar = bar;

        return container;
    }

    private updateUnitVisuals(c: PixiUnitContainer, agent: Agent, t: number, isSelected: boolean) {
        // Physics Z bounce
        const jumpY = -agent.physics.z - UNIT_BODY_OFFSET; 
        c.bodySprite.y = jumpY;

        // Scale/Facing
        const facing = agent.facing;
        c.bodySprite.scale.x = facing; 

        // HP Bar Draw
        c.hpBar.clear();
        if (agent.hp < agent.maxHp) {
            c.hpBar.y = -UNIT_VISUAL_HEIGHT - 20 + jumpY;
            c.hpBar.beginFill(0x000000);
            c.hpBar.drawRect(-20, 0, 40, 6);
            c.hpBar.beginFill(0x00ff00);
            c.hpBar.drawRect(-19, 1, 38 * (agent.hp / agent.maxHp), 4);
        }

        // Selection Highlight
        if (isSelected) {
            c.bodySprite.tint = 0xAAAAFF;
        } else {
            c.bodySprite.tint = 0xFFFFFF;
        }
    }

    private syncVFX(engine: GameEngine) {
        // Clear previous frame's immediate mode particles
        // In a real optimized system, we would maintain a persistent pool
        // But for this hybrid step, we regenerate sprites from logic data
        this.vfxLayer.removeChildren();

        // 1. Draw Projectiles
        engine.combat.projectiles.forEach(p => {
            const texture = TextureManager.getVFXTexture('PROJECTILE', p.skill.color);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - 50); // Visual offset

            // Calculate rotation
            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            sprite.rotation = Math.atan2(dy, dx);

            this.vfxLayer.addChild(sprite);
        });

        // 2. Draw Particles (Using logic from VFXSystem)
        // This is where Pixi shines - batch rendering
        engine.vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            let texture: PIXI.Texture;

            if (p.type === 'SMOKE') texture = TextureManager.getVFXTexture('FOG', p.color);
            else if (p.type === 'GLOW') texture = TextureManager.getVFXTexture('GLOW', p.color);
            else if (p.type === 'BLAST') texture = TextureManager.getVFXTexture('BLAST', p.color);
            else texture = TextureManager.getVFXTexture('SPARK', p.color); // Default dot

            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - p.z);
            sprite.alpha = p.life / p.maxLife;
            sprite.tint = parseInt(p.color.replace('#', '0x'));

            // Scale based on size
            const scale = p.size / 32; 
            sprite.scale.set(scale);
            sprite.rotation = p.rotation;

            // Add to correct layer based on type (Ground vs Air)
            if (['BLAST', 'DECAL'].includes(p.type)) {
                this.decalLayer.addChild(sprite);
            } else {
                this.vfxLayer.addChild(sprite);
            }
        });
    }

    private syncObstacles(engine: GameEngine) {
        // Similar to terrain, could be optimized. 
        // For now, iterate map obstacles and place sprites.
        // We use a simple ID check to avoid recreating existing ones would be better
        // But for this phase, let's clear and redraw to ensure correctness with "Painter Mode"

        // Remove old obstacle sprites (filter out units)
        this.objectLayer.children.forEach(c => {
            if (!(c as PixiUnitContainer).agentId) { 
                c.destroy(); 
            }
        });

        // Re-add non-unit children (Units are persistent)
        // Actually, safer to manage a separate container list for obstacles
        // ... simplified for this snippet:

        engine.map.obstacles.forEach((type, key) => {
            const [q, r] = key.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);

            const texture = TextureManager.getObstacleTexture(type);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0);
            sprite.position.set(pos.x, pos.y - h + offset);
            sprite.zIndex = pos.y; // Sort with units

            this.objectLayer.addChild(sprite);
        });
    }

    // --- UTILS ---

    // Bridge to get hex from screen (Raycasting logic)
    public getHexAtScreenPoint(mx: number, my: number, camera: Camera, engine: GameEngine): Hex | null {
        // Inverse Transform
        const worldX = (mx - this.app.screen.width / 2) / camera.zoom + camera.x;
        const worldY = (my - this.app.screen.height / 2) / camera.zoom + camera.y;

        // Simple approximation (heightless)
        return HexUtils.fromPx(worldX, worldY, engine.mapConfig);
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return engine.map.getTerrainHeight(q, r);
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { PixiRenderer } from '../engine/pixi/PixiRenderer'; // NEW RENDERER
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate PixiRenderer ONCE using Lazy Initialization.
    // Note: We cast to any here to bypass interface mismatch during migration if needed, 
    // but we updated hooks to accept generic renderer shape.
    const rendererRef = useRef<PixiRenderer | null>(null);

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System (Updated hooks/useGameInput.ts needs to accept PixiRenderer)
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as any, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Init & Render Handler
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        // NOTE: In Pixi mode, `ctx` is unused because Pixi handles the WebGL context.
        // We just use this loop trigger to call renderer.render()

        if (!rendererRef.current && canvasRef.current) {
            // Initialize Pixi App on first draw if not ready
            const width = wrapperRef.current?.clientWidth || 800;
            const height = wrapperRef.current?.clientHeight || 600;
            rendererRef.current = new PixiRenderer(canvasRef.current, width, height);
        }

        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC FIX ---
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.4);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        // Call the Pixi Render Pipeline
        rendererRef.current.render(
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex
        );

    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
            if (rendererRef.current) {
                rendererRef.current.resize(w, h);
            }
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    // We still use useGameLoop to drive the update cycle (engine.tick), 
    // even though Pixi has its own ticker, we want control over the logic timestep.
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef as any, // Cast for compatibility
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    // Win Callback Sync
    useEffect(() => {
        engine.onWin = onWin;
    }, [engine, onWin]);

    // Cleanup Pixi on unmount
    useEffect(() => {
        return () => {
            if (rendererRef.current) {
                rendererRef.current.destroy();
                rendererRef.current = null;
            }
        };
    }, []);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            {/* Canvas managed by Pixi */}
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - Liquid Glass Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-md w-full">
                        <h2 className={`text-6xl font-black mb-2 tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_20px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.6)]'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <div className="h-1 w-20 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <button onClick={rematch} className="liquid-btn px-10 py-4 rounded-full text-xl font-bold bg-white/10 hover:bg-white/20 border-white/20 text-white shadow-lg w-full">
                            再戰一局
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS, LOG_COLORS } from "../constants";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { VFXSystem } from "./systems/vfx";

// Re-export for compatibility
export { Agent, SpecialVisualStatus };

export class GameEngine {
    public agents: Agent[] = [];

    // Delegated to MapSystem
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }

    // Delegated to CombatSystem (Single Source of Truth)
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];

    public isRunning: boolean = false;
    public timeScale: number = 1.0;
    public battleTime: number = 0;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public onWin?: (team: Team) => void;

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    // Subsystems
    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;
    public vfx: VFXSystem;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.vfx = new VFXSystem();

        this.map.randomizeEnvironment(this);
    }

    // --- Passthroughs ---

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }

    // Updated to support Paint Mode
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    // Updated to support flying logic check
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // --- Core Logic Control ---

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
        }

        this.agentMap.clear();

        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); // Use AI System
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.agentMap.clear();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);

            // Re-link skills immediately so Tooltips/UI work while paused
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });

            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        this.combat.projectiles = []; // Clear projectiles via combat system
        this.events = []; // Clear pending events
        this.battleTime = 0;
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');

        // BUG FIX: Do NOT auto-play. Wait for user to click play.
        // this.play(); 
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = []; // Clear projectiles via combat system
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
    }

    // --- Main Game Loop ---

    tick(dt: number) {
        if (!this.isRunning) return;

        // Memory Optimization: Reuse array instead of reallocation
        this.events.length = 0;

        this.updateDirector(dt); // AI Director Logic

        // Win Condition Check
        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }
        if (blue === 0 && red > 0) { this.stop(); this.onWin?.(Team.RED); }
        else if (red === 0 && blue > 0) { this.stop(); this.onWin?.(Team.BLUE); }

        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            // Physics delegated to MovementSystem
            this.movement.updatePhysics(a, dt, this);

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // --- DELEGATED SYSTEMS ---
            this.status.update(a, dt, this);

            // Movement Update
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            // AI Update
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    // --- Loop Sub-Methods ---

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // Ensure current target is still valid
        const current = this.agents.find(a => a.id === this.directorTargetId);
        if (!current || current.hp <= 0) {
            this.directorTimer = -1; // Force switch
        }

        if (this.directorTimer <= 0) {
            // Pick new target logic (simplified for brevity, logic remains same)
            const alive = this.agents.filter(a => a.hp > 0);
            if (alive.length > 0) {
                const ultCasters = alive.filter(a => a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT');
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0;
                     return;
                }

                this.directorTargetId = alive[Math.floor(Math.random() * alive.length)].id;
                this.directorTimer = 3.0;
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 

            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    // Rich Logging Overhaul
    log(agent: Agent | null, typeOrAction: LogActionType | string, actionNameOrTarget: string | null, detailOrTargetInfo: string, legacyDetail?: string) {
        const time = this.battleTime.toFixed(1);

        let actionType: LogActionType = 'SYSTEM';
        let actionName = 'Action';
        let targetInfo = '';
        let detail = '';
        let color = LOG_COLORS.SYSTEM;

        // Handle Legacy Calls (from StatusSystem, AgentManager, etc.)
        // Old: log(agent, actionString, targetId, detailString)
        const isLegacy = !this.isLogActionType(typeOrAction);

        if (isLegacy) {
            const rawAction = typeOrAction as string;
            actionName = rawAction;
            targetInfo = actionNameOrTarget || '';
            detail = detailOrTargetInfo;

            // Map Legacy strings to Types
            if (rawAction === '死亡') { actionType = 'DEATH'; color = LOG_COLORS.DEATH; }
            else if (rawAction === '放逐結束') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '中斷') { actionType = 'CC'; color = LOG_COLORS.CC; }
            else if (rawAction === '命中') { actionType = 'HIT'; color = LOG_COLORS.HIT; }
            else { actionType = 'SYSTEM'; }
        } else {
            // New Rich Signature
            // log(agent, type, actionName, targetInfo, detail)
            actionType = typeOrAction as LogActionType;
            actionName = actionNameOrTarget || '';
            targetInfo = detailOrTargetInfo || '';
            detail = legacyDetail || '';

            switch(actionType) {
                case 'MOVE': color = LOG_COLORS.MOVE; break;
                case 'CAST': color = LOG_COLORS.CAST; break;
                case 'HIT': color = LOG_COLORS.HIT; break;
                case 'HEAL': color = LOG_COLORS.HEAL; break;
                case 'DECISION': color = LOG_COLORS.DECISION; break;
                case 'DEATH': color = LOG_COLORS.DEATH; break;
                case 'CC': color = LOG_COLORS.CC; break;
                default: color = LOG_COLORS.SYSTEM; break;
            }
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10), // Tick
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: actionType,
            actionName: actionName,
            targetInfo: targetInfo,
            detail: detail,
            visualColor: color,
            // Legacy compat
            action: actionName,
            target: targetInfo,
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }

    private isLogActionType(val: any): val is LogActionType {
        return ['MOVE','CAST','HIT','DECISION','DEATH','SYSTEM','HEAL','CC'].includes(val);
    }
}

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    // public vfx: VFXSystem; // Moved to GameEngine
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        // this.vfx = new VFXSystem(); // Removed
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        // Use engine.vfx
        engine.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            engine.vfx, // Use engine.vfx
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        // High-DPI Handling
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        this.camera.sync(camera);
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        // Logic: All sub-systems return standard RenderableItems.
        // We aggregate them into a single list and Z-Sort them.
        let renderList: RenderableItem[] = [];

        // Grid + Obstacles
        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.vfx.state.gridFlashes, engine.projectiles, // Use engine.vfx
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        // VFX (Ground/Physical)
        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            engine.vfx, // Use engine.vfx
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        // Units
        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Sorting: Y-Sort primarily, Z-Index secondarily
        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            // Hack for "Always Top" layers (z > 50)
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. Tactical Overlay Lines
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 8. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, engine.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase); // Use engine.vfx

        // 9. HUD (Health bars, floating text)
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 10. Holographic Director HUD (Screen Space)
        if (engine.directorTargetId) {
            ctx.restore(); // Exit Camera Space
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
            ctx.save(); // Dummy save to match restore below
        } else {
            ctx.restore();
            ctx.save();
        }

        // 11. Post Processing & Debug
        ctx.restore(); 
        this.camera.applyPostProcessing(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

import * as PIXI from 'pixi.js';
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Camera } from "../systems/CameraSystem";
import { Hex, Skill } from "../../types";
import { TextureManager } from "../graphics/TextureManager";
import { HEX_SIZE, UNIT_VISUAL_HEIGHT, UNIT_BODY_OFFSET } from "../../constants";
import { AssetManager } from "../assets";

// Types
type PixiUnitContainer = PIXI.Container & {
    agentId: string;
    bodySprite: PIXI.Sprite;
    shadowSprite: PIXI.Graphics;
    hpBar: PIXI.Graphics;
}

export class PixiRenderer {
    public app: PIXI.Application;

    // Layers
    private worldContainer: PIXI.Container; // Affected by Camera
    private backgroundLayer: PIXI.Container;
    private terrainLayer: PIXI.Container;
    private decalLayer: PIXI.Container; // Ground effects
    private objectLayer: PIXI.Container; // Units & Obstacles sorted by Y
    private vfxLayer: PIXI.Container; // Floating particles
    private hudLayer: PIXI.Container; // Screen space

    // State Sync
    private unitMap: Map<string, PixiUnitContainer> = new Map();
    private particlePool: PIXI.Sprite[] = [];
    private activeParticles: PIXI.Sprite[] = [];

    // Config
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(canvas: HTMLCanvasElement, width: number, height: number) {
        this.app = new PIXI.Application({
            view: canvas,
            width: width,
            height: height,
            backgroundColor: 0x000000,
            antialias: true,
            resolution: window.devicePixelRatio || 1,
            autoDensity: true
        });

        // Setup Layers
        this.worldContainer = new PIXI.Container();
        this.worldContainer.sortableChildren = true;

        this.backgroundLayer = new PIXI.Container();
        this.terrainLayer = new PIXI.Container();
        this.decalLayer = new PIXI.Container();
        this.objectLayer = new PIXI.Container();
        this.objectLayer.sortableChildren = true; // Y-Sort enabled
        this.vfxLayer = new PIXI.Container();
        this.hudLayer = new PIXI.Container(); // Screen space

        this.app.stage.addChild(this.backgroundLayer);
        this.app.stage.addChild(this.worldContainer);
        this.app.stage.addChild(this.hudLayer);

        this.worldContainer.addChild(this.terrainLayer);
        this.worldContainer.addChild(this.decalLayer);
        this.worldContainer.addChild(this.objectLayer);
        this.worldContainer.addChild(this.vfxLayer);
    }

    public resize(w: number, h: number) {
        this.app.renderer.resize(w, h);
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public destroy() {
        this.app.destroy(false, true); // Don't destroy canvas
    }

    // --- MAIN RENDER LOOP ---

    public render(
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number,
        hoveredHex: Hex | null
    ) {
        // 1. Sync Camera
        this.syncCamera(camera, engine);

        // 2. Sync Background (Simple color for now, can use TilingSprite later)
        const bgHex = parseInt(engine.currentScene.background.replace('#', '0x'));
        this.app.renderer.background.color = bgHex;

        // 3. Sync Grid/Terrain
        this.syncTerrain(engine);

        // 4. Sync Units (Create/Update/Remove)
        this.syncUnits(engine, highlight);

        // 5. Sync Projectiles & VFX
        this.syncVFX(engine);

        // 6. Sync Obstacles
        this.syncObstacles(engine);
    }

    // Stub update method to satisfy useGameLoop contract
    public update(dt: number, engine: GameEngine) {
        // vfx update is handled by GameRenderer or should be here if Pixi is active renderer
        // Currently handled by game engine or 2d renderer side effect if not fully migrated
    }

    // --- SYNC METHODS ---

    private syncCamera(camera: Camera, engine: GameEngine) {
        // Apply Trauma Shake from Engine's CameraSystem (accessed via global renderer logic if needed, 
        // but here we just take the raw camera pos passed in).
        // If we want shake, we should pass the shaken camera coords.
        const cx = this.app.screen.width / 2;
        const cy = this.app.screen.height / 2;

        this.worldContainer.position.set(cx, cy);
        this.worldContainer.scale.set(camera.zoom);
        this.worldContainer.pivot.set(camera.x, camera.y);
    }

    private syncTerrain(engine: GameEngine) {
        // Optimization: Only rebuild if map version changes
        // For dynamic height transitions, we might need to update y positions

        // This is a simplified "Immediate Mode" style for the grid to handle the transition animation
        // In a real optimized scenario, we would cache this container.
        this.terrainLayer.removeChildren();

        const scene = engine.currentScene;
        const keys = Array.from(engine.mapKeys); // e.g. "0,0"

        keys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Animation
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);
            const drawY = pos.y + offset;

            // Cull off-screen
            if (drawY > pos.y + 1000) return;

            // Get Texture
            const texture = TextureManager.getTerrainBlockTexture(scene.textureType, h);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0); // Bottom center
            sprite.position.set(pos.x, drawY);

            // Tint if hovered
            // Note: Mouse interaction in Pixi needs mapping. For now relying on React state passed down.
            // (hoveredHex logic would be applied here)

            this.terrainLayer.addChild(sprite);
        });
    }

    private syncUnits(engine: GameEngine, highlight: Agent | null) {
        const aliveIds = new Set<string>();

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            aliveIds.add(agent.id);

            let container = this.unitMap.get(agent.id);
            if (!container) {
                container = this.createUnitContainer(agent);
                this.unitMap.set(agent.id, container);
                this.objectLayer.addChild(container);
            }

            // Update Position & Z-Index
            const h = engine.map.getTerrainHeight(agent.q, agent.r);
            // Physics interpolation handled in Agent class, we just read px/py
            const visualY = agent.py - h; 

            container.position.set(agent.px, visualY);
            container.zIndex = agent.py; // Sort by ground Y

            // Update Body Visuals (Scale/Rotation based on anim)
            this.updateUnitVisuals(container, agent, engine.battleTime, highlight === agent);
        });

        // Cleanup dead units
        for (const [id, container] of this.unitMap) {
            if (!aliveIds.has(id)) {
                this.objectLayer.removeChild(container);
                container.destroy({ children: true });
                this.unitMap.delete(id);
            }
        }
    }

    private createUnitContainer(agent: Agent): PixiUnitContainer {
        const container = new PIXI.Container() as PixiUnitContainer;
        container.agentId = agent.id;

        // Shadow
        const shadow = new PIXI.Graphics();
        shadow.beginFill(0x000000, 0.4);
        shadow.drawEllipse(0, 0, 15, 8);
        shadow.endFill();
        container.addChild(shadow);
        container.shadowSprite = shadow;

        // Body Sprite (Base)
        const texture = TextureManager.getUnitTexture(agent.role, agent.team, 'base');
        const sprite = new PIXI.Sprite(texture);
        sprite.anchor.set(0.5, 0.7); // Anchor near bottom
        container.addChild(sprite);
        container.bodySprite = sprite;

        // HP Bar
        const bar = new PIXI.Graphics();
        container.addChild(bar);
        container.hpBar = bar;

        return container;
    }

    private updateUnitVisuals(c: PixiUnitContainer, agent: Agent, t: number, isSelected: boolean) {
        // Physics Z bounce
        const jumpY = -agent.physics.z - UNIT_BODY_OFFSET; 
        c.bodySprite.y = jumpY;

        // Scale/Facing
        const facing = agent.facing;
        c.bodySprite.scale.x = facing; 

        // HP Bar Draw
        c.hpBar.clear();
        if (agent.hp < agent.maxHp) {
            c.hpBar.y = -UNIT_VISUAL_HEIGHT - 20 + jumpY;
            c.hpBar.beginFill(0x000000);
            c.hpBar.drawRect(-20, 0, 40, 6);
            c.hpBar.beginFill(0x00ff00);
            c.hpBar.drawRect(-19, 1, 38 * (agent.hp / agent.maxHp), 4);
        }

        // Selection Highlight
        if (isSelected) {
            c.bodySprite.tint = 0xAAAAFF;
        } else {
            c.bodySprite.tint = 0xFFFFFF;
        }
    }

    private syncVFX(engine: GameEngine) {
        // Clear previous frame's immediate mode particles
        // In a real optimized system, we would maintain a persistent pool
        // But for this hybrid step, we regenerate sprites from logic data
        this.vfxLayer.removeChildren();

        // 1. Draw Projectiles
        engine.combat.projectiles.forEach(p => {
            const texture = TextureManager.getVFXTexture('PROJECTILE', p.skill.color);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - 50); // Visual offset

            // Calculate rotation
            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            sprite.rotation = Math.atan2(dy, dx);

            this.vfxLayer.addChild(sprite);
        });

        // 2. Draw Particles (Using logic from VFXSystem)
        // This is where Pixi shines - batch rendering
        engine.vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            let texture: PIXI.Texture;

            if (p.type === 'SMOKE') texture = TextureManager.getVFXTexture('FOG', p.color);
            else if (p.type === 'GLOW') texture = TextureManager.getVFXTexture('GLOW', p.color);
            else if (p.type === 'BLAST') texture = TextureManager.getVFXTexture('BLAST', p.color);
            else texture = TextureManager.getVFXTexture('SPARK', p.color); // Default dot

            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - p.z);
            sprite.alpha = p.life / p.maxLife;
            sprite.tint = parseInt(p.color.replace('#', '0x'));

            // Scale based on size
            const scale = p.size / 32; 
            sprite.scale.set(scale);
            sprite.rotation = p.rotation;

            // Add to correct layer based on type (Ground vs Air)
            if (['BLAST', 'DECAL'].includes(p.type)) {
                this.decalLayer.addChild(sprite);
            } else {
                this.vfxLayer.addChild(sprite);
            }
        });
    }

    private syncObstacles(engine: GameEngine) {
        // Similar to terrain, could be optimized. 
        // For now, iterate map obstacles and place sprites.
        // We use a simple ID check to avoid recreating existing ones would be better
        // But for this phase, let's clear and redraw to ensure correctness with "Painter Mode"

        // Remove old obstacle sprites (filter out units)
        this.objectLayer.children.forEach(c => {
            if (!(c as PixiUnitContainer).agentId) { 
                c.destroy(); 
            }
        });

        // Re-add non-unit children (Units are persistent)
        // Actually, safer to manage a separate container list for obstacles
        // ... simplified for this snippet:

        engine.map.obstacles.forEach((type, key) => {
            const [q, r] = key.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);

            const texture = TextureManager.getObstacleTexture(type);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0);
            sprite.position.set(pos.x, pos.y - h + offset);
            sprite.zIndex = pos.y; // Sort with units

            this.objectLayer.addChild(sprite);
        });
    }

    // --- UTILS ---

    // Bridge to get hex from screen (Raycasting logic)
    public getHexAtScreenPoint(mx: number, my: number, camera: Camera, engine: GameEngine): Hex | null {
        // Inverse Transform
        const worldX = (mx - this.app.screen.width / 2) / camera.zoom + camera.x;
        const worldY = (my - this.app.screen.height / 2) / camera.zoom + camera.y;

        // Simple approximation (heightless)
        return HexUtils.fromPx(worldX, worldY, engine.mapConfig);
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return engine.map.getTerrainHeight(q, r);
    }
}

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<any>; // Changed to any to support PixiRenderer
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan, onCameraZoom 
    } = props;

    // --- State Refs (Mutable for Performance) ---
    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Action Context Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const lastPaintHex = useRef<string>("");

    // Config Refs (Sync with props to avoid stale closures in event listeners)
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // --- 1. HELPERS: Coordinate Mapping & Hit Testing ---

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!rendererRef.current) {
             return HexUtils.fromPx(
                sx / cameraRef.current.zoom + cameraRef.current.x,
                sy / cameraRef.current.zoom + cameraRef.current.y,
                engine.mapConfig
            );
        }
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPos = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        let h = BLOCK_HEIGHT + 6;

        if (rendererRef.current) {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        }

        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgent = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;

        // Painter's Algorithm Hit Test (Front units first)
        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            let h = 0;
            if (rendererRef.current) {
                h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            }
            const visualY = a.py - h - 40; 
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);

        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    // --- 2. LOGIC: Action Execution ---

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;

        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
            return;
        }

        const existingAgent = engine.getAgentAt(h.q, h.r);
        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            let agent: Agent | null = null;
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                // Assign random skills for draft role
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        }
    };

    // --- 3. EVENT HANDLERS (Unified Logic) ---

    const handleInputStart = (sx: number, sy: number, isRightClick: boolean) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        if (isRightClick) {
            interactionMode.current = 'PAN';
            return;
        }

        // 1. Hit Test Agent
        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN'; // Wait to see if drag or click
            return;
        }

        // 2. Editing Logic
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (isEditing) {
            // Hit Obstacle?
            if (tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
                const obsType = engine.obstacles.get(HexUtils.key(h));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            // Paint Tool?
            if (tool !== ToolType.SELECT) {
                // Immediate paint on down for better feel
                if (engine.isValid(h.q, h.r)) {
                    executePaintAction(h);
                    interactionMode.current = 'PAINT';
                }
                return;
            }
        }

        interactionMode.current = 'DOWN'; // Default to potential pan
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        // Cursor & Hover Logic
        if (cvs) {
            const { tool, winner } = configRef.current;
            const isEditing = !engine.isRunning && winner === null;
            const hitAgent = getHitAgent(sx, sy);

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (isEditing && tool !== ToolType.SELECT) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        const prev = lastPointerPos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastPointerPos.current = { x: sx, y: sy };

        // --- Active State Handling ---
        if (interactionMode.current === 'PAN') {
            onCameraPan(dx, dy);
            return;
        }
        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executePaintAction(h);
            return;
        }
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // --- State Transition (Threshold Check) ---
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 8) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;

                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; // Lift
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    // Remove from grid temporarily
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    const wPos = getWorldPos(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                } else {
                    interactionMode.current = 'PAN';
                    onCameraPan(dx, dy);
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        // Click Logic (Released without dragging)
        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (isEditing && engine.hasObstacle(h.q, h.r) && tool === ToolType.DELETE) {
                engine.removeObstacle(h.q, h.r);
            } else if (!pressedAgentRef.current) {
                onSelect(null);
            }
        }

        // Drop Logic
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, agent.id, agent.movementType);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                // Revert
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); // Revert
        }

        // Reset
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
    };

    // --- 4. BINDINGS ---

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        // --- Mouse ---
        const onMouseDown = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top, e.button === 2);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };
        const onCtx = (e: MouseEvent) => e.preventDefault();

        // --- Touch ---
        const getTouchPos = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };
        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputStart(x, y, false);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE'; 
            }
        };
        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputMove(x, y);
            } else if (e.touches.length === 2) {
                const t1 = getTouchPos(e.touches[0]);
                const t2 = getTouchPos(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    onCameraZoom((dist - lastPinchDist.current) * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };
        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getTouchPos(e.changedTouches[0]);
                handleInputEnd(x, y);
            }
            if (e.touches.length < 2) lastPinchDist.current = 0;
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchEnd);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import * as PIXI from 'pixi.js';
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Camera } from "../systems/CameraSystem";
import { Hex, Skill } from "../../types";
import { TextureManager } from "../graphics/TextureManager";
import { HEX_SIZE, UNIT_VISUAL_HEIGHT, UNIT_BODY_OFFSET } from "../../constants";
import { AssetManager } from "../assets";

// Types
type PixiUnitContainer = PIXI.Container & {
    agentId: string;
    bodySprite: PIXI.Sprite;
    shadowSprite: PIXI.Graphics;
    hpBar: PIXI.Graphics;
}

export class PixiRenderer {
    public app: PIXI.Application;

    // Layers
    private worldContainer: PIXI.Container; // Affected by Camera
    private backgroundLayer: PIXI.Container;
    private terrainLayer: PIXI.Container;
    private decalLayer: PIXI.Container; // Ground effects
    private objectLayer: PIXI.Container; // Units & Obstacles sorted by Y
    private vfxLayer: PIXI.Container; // Floating particles
    private hudLayer: PIXI.Container; // Screen space

    // State Sync
    private unitMap: Map<string, PixiUnitContainer> = new Map();

    // Config
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(canvas: HTMLCanvasElement, width: number, height: number) {
        this.app = new PIXI.Application({
            view: canvas,
            width: width,
            height: height,
            backgroundColor: 0x000000,
            antialias: true,
            resolution: window.devicePixelRatio || 1,
            autoDensity: true,
            autoStart: false, // We control the render loop
            sharedTicker: true
        });

        // Setup Layers
        this.worldContainer = new PIXI.Container();
        this.worldContainer.sortableChildren = true;

        this.backgroundLayer = new PIXI.Container();
        this.terrainLayer = new PIXI.Container();
        this.decalLayer = new PIXI.Container();
        this.objectLayer = new PIXI.Container();
        this.objectLayer.sortableChildren = true; // Y-Sort enabled
        this.vfxLayer = new PIXI.Container();
        this.hudLayer = new PIXI.Container(); // Screen space

        this.app.stage.addChild(this.backgroundLayer);
        this.app.stage.addChild(this.worldContainer);
        this.app.stage.addChild(this.hudLayer);

        this.worldContainer.addChild(this.terrainLayer);
        this.worldContainer.addChild(this.decalLayer);
        this.worldContainer.addChild(this.objectLayer);
        this.worldContainer.addChild(this.vfxLayer);
    }

    public resize(w: number, h: number) {
        this.app.renderer.resize(w, h);
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public destroy() {
        try {
            this.app.destroy(false, true); // Don't destroy canvas
        } catch(e) {
            console.warn("Pixi destroy failed", e);
        }
    }

    // --- MAIN RENDER LOOP ---

    public render(
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null
    ) {
        if (!this.app || !this.app.renderer) return;

        // 1. Sync Camera
        this.syncCamera(camera, engine);

        // 2. Sync Background
        try {
            const bgHex = parseInt(engine.currentScene.background.replace('#', '0x'));
            // V7 compatible
            (this.app.renderer as any).background.color = bgHex;
        } catch(e) {
            // Fallback for older V7
            (this.app.renderer as any).backgroundColor = 0x000000;
        }

        // 3. Sync Grid/Terrain
        this.syncTerrain(engine);

        // 4. Sync Units (Create/Update/Remove)
        this.syncUnits(engine, highlight);

        // 5. Sync Projectiles & VFX
        this.syncVFX(engine);

        // 6. Sync Obstacles
        this.syncObstacles(engine);

        // 7. Trigger Render
        this.app.render();
    }

    // Stub update method to satisfy useGameLoop contract
    public update(dt: number, engine: GameEngine) {
        // vfx update is handled by game engine
    }

    // --- SYNC METHODS ---

    private syncCamera(camera: Camera, engine: GameEngine) {
        const cx = this.app.screen.width / 2;
        const cy = this.app.screen.height / 2;

        this.worldContainer.position.set(cx, cy);
        this.worldContainer.scale.set(camera.zoom);
        this.worldContainer.pivot.set(camera.x, camera.y);
    }

    private syncTerrain(engine: GameEngine) {
        // Optimization: Check if map needs rebuild
        // For now, naive rebuild for correctness during dev, but heavily batched by texture
        this.terrainLayer.removeChildren();

        const scene = engine.currentScene;
        const keys = Array.from(engine.mapKeys);

        keys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Animation
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);
            const drawY = pos.y + offset;

            // Cull off-screen (Loose bounds)
            if (drawY > pos.y + 1500) return;

            // Get Texture
            const texture = TextureManager.getTerrainBlockTexture(scene.textureType, h);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0); // Bottom center
            sprite.position.set(pos.x, drawY);

            this.terrainLayer.addChild(sprite);
        });
    }

    private syncUnits(engine: GameEngine, highlight: Agent | null) {
        const aliveIds = new Set<string>();

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            aliveIds.add(agent.id);

            let container = this.unitMap.get(agent.id);
            if (!container) {
                container = this.createUnitContainer(agent);
                this.unitMap.set(agent.id, container);
                this.objectLayer.addChild(container);
            }

            // Update Position & Z-Index
            const h = engine.map.getTerrainHeight(agent.q, agent.r);
            const visualY = agent.py - h; 

            container.position.set(agent.px, visualY);
            container.zIndex = agent.py; 

            this.updateUnitVisuals(container, agent, engine.battleTime, highlight === agent);
        });

        // Cleanup dead units
        for (const [id, container] of this.unitMap) {
            if (!aliveIds.has(id)) {
                this.objectLayer.removeChild(container);
                container.destroy({ children: true });
                this.unitMap.delete(id);
            }
        }
    }

    private createUnitContainer(agent: Agent): PixiUnitContainer {
        const container = new PIXI.Container() as PixiUnitContainer;
        container.agentId = agent.id;

        // Shadow
        const shadow = new PIXI.Graphics();
        shadow.beginFill(0x000000, 0.4);
        shadow.drawEllipse(0, 0, 15, 8);
        shadow.endFill();
        container.addChild(shadow);
        container.shadowSprite = shadow;

        // Body Sprite (Base)
        const texture = TextureManager.getUnitTexture(agent.role, agent.team, 'base');
        const sprite = new PIXI.Sprite(texture);
        sprite.anchor.set(0.5, 0.7); // Anchor near bottom
        container.addChild(sprite);
        container.bodySprite = sprite;

        // HP Bar
        const bar = new PIXI.Graphics();
        container.addChild(bar);
        container.hpBar = bar;

        return container;
    }

    private updateUnitVisuals(c: PixiUnitContainer, agent: Agent, t: number, isSelected: boolean) {
        // Physics Z bounce
        const jumpY = -agent.physics.z - UNIT_BODY_OFFSET; 
        c.bodySprite.y = jumpY;

        // Scale/Facing
        const facing = agent.facing;
        c.bodySprite.scale.x = facing; 

        // HP Bar Draw
        c.hpBar.clear();
        if (agent.hp < agent.maxHp) {
            const barY = -UNIT_VISUAL_HEIGHT - 20 + jumpY;
            c.hpBar.beginFill(0x000000);
            c.hpBar.drawRect(-20, barY, 40, 6);
            c.hpBar.beginFill(0x00ff00);
            c.hpBar.drawRect(-19, barY + 1, 38 * (agent.hp / agent.maxHp), 4);
        }

        // Selection Highlight
        if (isSelected) {
            c.bodySprite.tint = 0xAAAAFF;
        } else {
            c.bodySprite.tint = 0xFFFFFF;
        }
    }

    private syncVFX(engine: GameEngine) {
        this.vfxLayer.removeChildren();

        // 1. Draw Projectiles
        engine.combat.projectiles.forEach(p => {
            const texture = TextureManager.getVFXTexture('PROJECTILE', p.skill.color);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - 50); 

            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            sprite.rotation = Math.atan2(dy, dx);

            this.vfxLayer.addChild(sprite);
        });

        // 2. Draw Particles
        engine.vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            let texture: PIXI.Texture;

            if (p.type === 'SMOKE') texture = TextureManager.getVFXTexture('FOG', p.color);
            else if (p.type === 'GLOW') texture = TextureManager.getVFXTexture('GLOW', p.color);
            else if (p.type === 'BLAST') texture = TextureManager.getVFXTexture('BLAST', p.color);
            else texture = TextureManager.getVFXTexture('SPARK', p.color); 

            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - p.z);
            sprite.alpha = p.life / p.maxLife;
            sprite.tint = parseInt(p.color.replace('#', '0x'));

            // Scale
            const scale = p.size / 32; 
            sprite.scale.set(scale);
            sprite.rotation = p.rotation;

            if (['BLAST', 'DECAL'].includes(p.type)) {
                this.decalLayer.addChild(sprite);
            } else {
                this.vfxLayer.addChild(sprite);
            }
        });
    }

    private syncObstacles(engine: GameEngine) {
        // Prune non-unit objects
        this.objectLayer.children.forEach(c => {
            if (!(c as PixiUnitContainer).agentId) { 
                c.destroy(); 
            }
        });

        engine.map.obstacles.forEach((type, key) => {
            const [q, r] = key.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);

            const texture = TextureManager.getObstacleTexture(type);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0);
            sprite.position.set(pos.x, pos.y - h + offset);
            sprite.zIndex = pos.y; 

            this.objectLayer.addChild(sprite);
        });
    }

    // --- UTILS ---

    public getHexAtScreenPoint(mx: number, my: number, camera: Camera, engine: GameEngine): Hex | null {
        const worldX = (mx - this.app.screen.width / 2) / camera.zoom + camera.x;
        const worldY = (my - this.app.screen.height / 2) / camera.zoom + camera.y;

        return HexUtils.fromPx(worldX, worldY, engine.mapConfig);
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return engine.map.getTerrainHeight(q, r);
    }
}

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<any | null>, // Relaxed type to support PixiRenderer
    onDraw: (ctx: CanvasRenderingContext2D | null, fps: number) => void,
    onResize: (logicalWidth: number, logicalHeight: number) => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);
    const isMountedRef = useRef(true);
    const resizeTimerRef = useRef<number | null>(null);

    // Store callbacks to prevent effect re-triggering
    const drawCallbackRef = useRef(onDraw);
    const resizeCallbackRef = useRef(onResize);

    useEffect(() => {
        drawCallbackRef.current = onDraw;
        resizeCallbackRef.current = onResize;
    }, [onDraw, onResize]);

    // 1. LIFECYCLE & RESIZE OBSERVER (High-DPI Support)
    useEffect(() => {
        isMountedRef.current = true;
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!isMountedRef.current) return;

            window.requestAnimationFrame(() => {
                if (!isMountedRef.current || !canvasRef.current || !entries[0]) return;

                const { width, height } = entries[0].contentRect;

                // High-DPI Logic
                const dpr = window.devicePixelRatio || 1;
                const logicalW = Math.floor(width);
                const logicalH = Math.floor(height);

                // Physical pixels (Buffer size)
                const physicalW = Math.floor(width * dpr);
                const physicalH = Math.floor(height * dpr);

                if (logicalW === 0 || logicalH === 0) return;

                // Only update if dimensions actually changed to avoid flicker
                if (canvasRef.current.width !== physicalW || canvasRef.current.height !== physicalH) {
                    // 1. Set Physical Buffer Size (High Res)
                    canvasRef.current.width = physicalW;
                    canvasRef.current.height = physicalH;

                    // 2. Set CSS Display Size (Logical Res)
                    canvasRef.current.style.width = `${logicalW}px`;
                    canvasRef.current.style.height = `${logicalH}px`;

                    // 3. Debounce Logical Resize (Camera Recenter)
                    if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
                    resizeTimerRef.current = window.setTimeout(() => {
                        if (isMountedRef.current) {
                            // Pass LOGICAL dimensions to avoiding reading DOM again
                            resizeCallbackRef.current(logicalW, logicalH);
                        }
                    }, 50);
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);

        return () => {
            isMountedRef.current = false;
            resizeObserver.disconnect();
            if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
            cancelAnimationFrame(frameRef.current);
        };
    }, [wrapperRef, canvasRef]);

    // 2. MAIN GAME LOOP
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!isMountedRef.current) return;

            // CRITICAL FIX: Allow loop to run even if renderer isn't ready, so it can be initialized in callback
            // Also allow null ctx for WebGL/Pixi usage
            if (!canvasRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            // Try to get 2D context, but don't enforce it (Pixi uses WebGL)
            const ctx = canvasRef.current.getContext('2d');

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update
            if (engine.isRunning) {
                acc += dt;
                if (acc > 250) acc = 250; 

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0 && rendererRef.current && rendererRef.current.processEventsWithEngine) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update
            if (rendererRef.current && rendererRef.current.update) {
                rendererRef.current.update(dt / 1000, engine);
            }

            // Delegate Drawing (This is where PixiRenderer gets created/called)
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);

        return () => {
            cancelAnimationFrame(frameRef.current);
        };
    }, [engine, canvasRef, rendererRef]);

    return { fpsRef };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { PixiRenderer } from '../engine/pixi/PixiRenderer'; // NEW RENDERER
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref (Mutable to avoid re-renders during loop)
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate PixiRenderer ONCE using Lazy Initialization.
    const rendererRef = useRef<PixiRenderer | null>(null);

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as any, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 3. Init & Render Handler
    // ctx might be null if using WebGL (Pixi), so we type it as any or nullable
    const handleDraw = useCallback((ctx: any, fps: number) => {

        // --- LAZY INIT PIXI RENDERER ---
        if (!rendererRef.current && canvasRef.current && wrapperRef.current) {
            const width = wrapperRef.current.clientWidth;
            const height = wrapperRef.current.clientHeight;
            if (width > 0 && height > 0) {
                console.log("Initializing PixiRenderer", width, height);
                rendererRef.current = new PixiRenderer(canvasRef.current, width, height);

                // Initial resize to match device pixel ratio which the loop set on the canvas
                rendererRef.current.resize(width, height);
            }
        }

        if (!rendererRef.current) return;

        // --- ANIMATION LOGIC ---
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.4);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        // Call the Pixi Render Pipeline
        rendererRef.current.render(
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex
        );

    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, camera]);

    // Resize Logic
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
            if (rendererRef.current) {
                rendererRef.current.resize(w, h);
            }
        }
    }, [centerCamera]);

    // 4. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef as any, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    // Win Callback Sync
    useEffect(() => {
        engine.onWin = onWin;
    }, [engine, onWin]);

    // Cleanup Pixi on unmount
    useEffect(() => {
        return () => {
            if (rendererRef.current) {
                rendererRef.current.destroy();
                rendererRef.current = null;
            }
        };
    }, []);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            {/* Canvas managed by Pixi */}
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN - Liquid Glass Style */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-md w-full">
                        <h2 className={`text-6xl font-black mb-2 tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_20px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.6)]'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <div className="h-1 w-20 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <button onClick={rematch} className="liquid-btn px-10 py-4 rounded-full text-xl font-bold bg-white/10 hover:bg-white/20 border-white/20 text-white shadow-lg w-full">
                            再戰一局
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import * as PIXI from 'pixi.js';
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { Camera } from "../systems/CameraSystem";
import { Hex, Skill } from "../../types";
import { TextureManager } from "../graphics/TextureManager";
import { HEX_SIZE, UNIT_VISUAL_HEIGHT, UNIT_BODY_OFFSET } from "../../constants";
import { AssetManager } from "../assets";

// Types
type PixiUnitContainer = PIXI.Container & {
    agentId: string;
    bodySprite: PIXI.Sprite;
    shadowSprite: PIXI.Graphics;
    hpBar: PIXI.Graphics;
}

export class PixiRenderer {
    public app: PIXI.Application;

    // Layers
    private worldContainer: PIXI.Container; // Affected by Camera
    private backgroundLayer: PIXI.Container;
    private terrainLayer: PIXI.Container;
    private decalLayer: PIXI.Container; // Ground effects
    private objectLayer: PIXI.Container; // Units & Obstacles sorted by Y
    private vfxLayer: PIXI.Container; // Floating particles
    private hudLayer: PIXI.Container; // Screen space

    // State Sync
    private unitMap: Map<string, PixiUnitContainer> = new Map();

    // Config
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(canvas: HTMLCanvasElement, width: number, height: number) {
        const appConfig = {
            view: canvas,
            width: width,
            height: height,
            backgroundColor: 0x000000,
            antialias: true,
            resolution: window.devicePixelRatio || 1,
            autoDensity: true,
            autoStart: false, // We control the render loop
            sharedTicker: true
        };

        try {
            this.app = new PIXI.Application(appConfig);
        } catch (e) {
            console.warn("WebGL initialization failed, falling back to Canvas renderer.", e);
            // Fallback to Canvas renderer
            this.app = new PIXI.Application({ ...appConfig, forceCanvas: true });
        }

        // Setup Layers
        this.worldContainer = new PIXI.Container();
        this.worldContainer.sortableChildren = true;

        this.backgroundLayer = new PIXI.Container();
        this.terrainLayer = new PIXI.Container();
        this.decalLayer = new PIXI.Container();
        this.objectLayer = new PIXI.Container();
        this.objectLayer.sortableChildren = true; // Y-Sort enabled
        this.vfxLayer = new PIXI.Container();
        this.hudLayer = new PIXI.Container(); // Screen space

        this.app.stage.addChild(this.backgroundLayer);
        this.app.stage.addChild(this.worldContainer);
        this.app.stage.addChild(this.hudLayer);

        this.worldContainer.addChild(this.terrainLayer);
        this.worldContainer.addChild(this.decalLayer);
        this.worldContainer.addChild(this.objectLayer);
        this.worldContainer.addChild(this.vfxLayer);
    }

    public resize(w: number, h: number) {
        this.app.renderer.resize(w, h);
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public destroy() {
        try {
            this.app.destroy(false, true); // Don't destroy canvas
        } catch(e) {
            console.warn("Pixi destroy failed", e);
        }
    }

    // --- MAIN RENDER LOOP ---

    public render(
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null
    ) {
        if (!this.app || !this.app.renderer) return;

        // 1. Sync Camera
        this.syncCamera(camera, engine);

        // 2. Sync Background
        try {
            const bgHex = parseInt(engine.currentScene.background.replace('#', '0x'));
            // V7 compatible
            (this.app.renderer as any).background.color = bgHex;
        } catch(e) {
            // Fallback for older V7
            (this.app.renderer as any).backgroundColor = 0x000000;
        }

        // 3. Sync Grid/Terrain
        this.syncTerrain(engine);

        // 4. Sync Units (Create/Update/Remove)
        this.syncUnits(engine, highlight);

        // 5. Sync Projectiles & VFX
        this.syncVFX(engine);

        // 6. Sync Obstacles
        this.syncObstacles(engine);

        // 7. Trigger Render
        this.app.render();
    }

    // Stub update method to satisfy useGameLoop contract
    public update(dt: number, engine: GameEngine) {
        // vfx update is handled by game engine
    }

    // --- SYNC METHODS ---

    private syncCamera(camera: Camera, engine: GameEngine) {
        const cx = this.app.screen.width / 2;
        const cy = this.app.screen.height / 2;

        this.worldContainer.position.set(cx, cy);
        this.worldContainer.scale.set(camera.zoom);
        this.worldContainer.pivot.set(camera.x, camera.y);
    }

    private syncTerrain(engine: GameEngine) {
        // Optimization: Check if map needs rebuild
        // For now, naive rebuild for correctness during dev, but heavily batched by texture
        this.terrainLayer.removeChildren();

        const scene = engine.currentScene;
        const keys = Array.from(engine.mapKeys);

        keys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Animation
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);
            const drawY = pos.y + offset;

            // Cull off-screen (Loose bounds)
            if (drawY > pos.y + 1500) return;

            // Get Texture
            const texture = TextureManager.getTerrainBlockTexture(scene.textureType, h);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0); // Bottom center
            sprite.position.set(pos.x, drawY);

            this.terrainLayer.addChild(sprite);
        });
    }

    private syncUnits(engine: GameEngine, highlight: Agent | null) {
        const aliveIds = new Set<string>();

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;
            aliveIds.add(agent.id);

            let container = this.unitMap.get(agent.id);
            if (!container) {
                container = this.createUnitContainer(agent);
                this.unitMap.set(agent.id, container);
                this.objectLayer.addChild(container);
            }

            // Update Position & Z-Index
            const h = engine.map.getTerrainHeight(agent.q, agent.r);
            const visualY = agent.py - h; 

            container.position.set(agent.px, visualY);
            container.zIndex = agent.py; 

            this.updateUnitVisuals(container, agent, engine.battleTime, highlight === agent);
        });

        // Cleanup dead units
        for (const [id, container] of this.unitMap) {
            if (!aliveIds.has(id)) {
                this.objectLayer.removeChild(container);
                container.destroy({ children: true });
                this.unitMap.delete(id);
            }
        }
    }

    private createUnitContainer(agent: Agent): PixiUnitContainer {
        const container = new PIXI.Container() as PixiUnitContainer;
        container.agentId = agent.id;

        // Shadow
        const shadow = new PIXI.Graphics();
        shadow.beginFill(0x000000, 0.4);
        shadow.drawEllipse(0, 0, 15, 8);
        shadow.endFill();
        container.addChild(shadow);
        container.shadowSprite = shadow;

        // Body Sprite (Base)
        const texture = TextureManager.getUnitTexture(agent.role, agent.team, 'base');
        const sprite = new PIXI.Sprite(texture);
        sprite.anchor.set(0.5, 0.7); // Anchor near bottom
        container.addChild(sprite);
        container.bodySprite = sprite;

        // HP Bar
        const bar = new PIXI.Graphics();
        container.addChild(bar);
        container.hpBar = bar;

        return container;
    }

    private updateUnitVisuals(c: PixiUnitContainer, agent: Agent, t: number, isSelected: boolean) {
        // Physics Z bounce
        const jumpY = -agent.physics.z - UNIT_BODY_OFFSET; 
        c.bodySprite.y = jumpY;

        // Scale/Facing
        const facing = agent.facing;
        c.bodySprite.scale.x = facing; 

        // HP Bar Draw
        c.hpBar.clear();
        if (agent.hp < agent.maxHp) {
            const barY = -UNIT_VISUAL_HEIGHT - 20 + jumpY;
            c.hpBar.beginFill(0x000000);
            c.hpBar.drawRect(-20, barY, 40, 6);
            c.hpBar.beginFill(0x00ff00);
            c.hpBar.drawRect(-19, barY + 1, 38 * (agent.hp / agent.maxHp), 4);
        }

        // Selection Highlight
        if (isSelected) {
            c.bodySprite.tint = 0xAAAAFF;
        } else {
            c.bodySprite.tint = 0xFFFFFF;
        }
    }

    private syncVFX(engine: GameEngine) {
        this.vfxLayer.removeChildren();

        // 1. Draw Projectiles
        engine.combat.projectiles.forEach(p => {
            const texture = TextureManager.getVFXTexture('PROJECTILE', p.skill.color);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - 50); 

            const dx = p.targetPos.x - p.x;
            const dy = p.targetPos.y - p.y;
            sprite.rotation = Math.atan2(dy, dx);

            this.vfxLayer.addChild(sprite);
        });

        // 2. Draw Particles
        engine.vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            let texture: PIXI.Texture;

            if (p.type === 'SMOKE') texture = TextureManager.getVFXTexture('FOG', p.color);
            else if (p.type === 'GLOW') texture = TextureManager.getVFXTexture('GLOW', p.color);
            else if (p.type === 'BLAST') texture = TextureManager.getVFXTexture('BLAST', p.color);
            else texture = TextureManager.getVFXTexture('SPARK', p.color); 

            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - p.z);
            sprite.alpha = p.life / p.maxLife;
            sprite.tint = parseInt(p.color.replace('#', '0x'));

            // Scale
            const scale = p.size / 32; 
            sprite.scale.set(scale);
            sprite.rotation = p.rotation;

            if (['BLAST', 'DECAL'].includes(p.type)) {
                this.decalLayer.addChild(sprite);
            } else {
                this.vfxLayer.addChild(sprite);
            }
        });
    }

    private syncObstacles(engine: GameEngine) {
        // Prune non-unit objects
        this.objectLayer.children.forEach(c => {
            if (!(c as PixiUnitContainer).agentId) { 
                c.destroy(); 
            }
        });

        engine.map.obstacles.forEach((type, key) => {
            const [q, r] = key.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const offset = getTransitionOffset(pos.x, pos.y, engine.mapConfig, this.transitionT, this.transitionPhase);

            const texture = TextureManager.getObstacleTexture(type);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5, 1.0);
            sprite.position.set(pos.x, pos.y - h + offset);
            sprite.zIndex = pos.y; 

            this.objectLayer.addChild(sprite);
        });
    }

    // --- UTILS ---

    public getHexAtScreenPoint(mx: number, my: number, camera: Camera, engine: GameEngine): Hex | null {
        const worldX = (mx - this.app.screen.width / 2) / camera.zoom + camera.x;
        const worldY = (my - this.app.screen.height / 2) / camera.zoom + camera.y;

        return HexUtils.fromPx(worldX, worldY, engine.mapConfig);
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return engine.map.getTerrainHeight(q, r);
    }
}

import * as PIXI from 'pixi.js';
