        const facing = agent.facing;
        c.bodySprite.scale.x = facing; 

        // HP Bar Draw
        c.hpBar.clear();
        if (agent.hp < agent.maxHp) {
            const barY = -UNIT_VISUAL_HEIGHT - 20 + jumpY;
            c.hpBar.beginFill(0x000000);
            c.hpBar.drawRect(-20, barY, 40, 6);
            c.hpBar.beginFill(0x00ff00);
            c.hpBar.drawRect(-19, barY + 1, 38 * (agent.hp / agent.maxHp), 4);
        }

        // Selection Highlight
        if (isSelected) {
            c.bodySprite.tint = 0xAAAAFF;
        } else {
            c.bodySprite.tint = 0xFFFFFF;
        }
    }

    private syncVFX(engine: GameEngine) {
        this.vfxLayer.removeChildren();

        // 1. Draw Projectiles
        engine.combat.projectiles.forEach(p => {
            const texture = TextureManager.getVFXTexture('PROJECTILE', p.skill.color);
            const sprite = new PIXI.Sprite(texture);
            sprite.anchor.set(0.5);
            sprite.position.set(p.x, p.y - 50); 

